local config = {
  ui_story_5071_50710101_1_dialog_content = "<size=45>ううっ――</size>",
  ui_story_5071_50710101_2_dialog_content = "<color=#e8d9bb>ドサッ！！！</color>",
  ui_story_5071_50710101_3_dialog_content = "…",
  ui_story_5071_50710101_4_dialog_content = "うう…ゲホ、ゴホッ…",
  ui_story_5071_50710101_5_dialog_content = "駄目だ…",
  ui_story_5071_50710101_6_dialog_content = "あいつが全員殺したって！？",
  ui_story_5071_50710101_7_dialog_content = "1人だけ生きて<color=#FFB400>ヘカトン・レイク</color>から出て来たんだ。\n間違いないだろう。",
  ui_story_5071_50710101_8_dialog_content = "本当に信じられない…権力を手に入れるため、\n兄弟まで手にかけるとは…",
  ui_story_5071_50710101_9_dialog_content = "本当に…そんな奴に影ノ街の未来を預けていいのか？",
  ui_story_5071_50710101_10_dialog_content = "…",
  ui_story_5071_50710101_11_dialog_content = "これで…",
  ui_story_5071_50710101_12_dialog_content = "クッ…",
  ui_story_5071_50710101_13_dialog_content = "<size=50>満足かい？</size>",
  ui_story_5071_50710101_14_dialog_content = "<color=#e8d9bb>ドンドンドン！</color>",
  ui_story_5071_50710101_15_dialog_content = "――！！！",
  ui_story_5071_50710101_16_dialog_content = "…影となった者もまた、影に飲み込まれる危険にさらされているのか。",
  ui_story_5071_50710101_17_dialog_content = "影が隠しているのは、過去だけではないのか…我が兄弟よ。",
  ui_story_5071_50710101_18_dialog_content = "<color=#e8d9bb>ドンドンドン！</color>",
  ui_story_5071_50710101_19_dialog_content = "お父様、私です。ベセルです。",
  ui_story_5071_50710101_20_dialog_content = "入れ。",
  ui_story_5071_50710101_21_dialog_content = "はい。お父様、準備ができましたので…",
  ui_story_5071_50710101_22_dialog_content = "…",
  ui_story_5071_50710101_23_dialog_content = "お父様…大丈夫ですか？\nそこまでお疲れのご様子を見たのは初めてです…",
  ui_story_5071_50710101_24_dialog_content = "ハハ。いくら酒が好きでも飲み過ぎはいかんな。\n俺もそろそろ節制を考える歳になったか。",
  ui_story_5071_50710101_25_dialog_content = "…ご冗談はよしてください。",
  ui_story_5071_50710101_26_dialog_content = "そうだな。冗談ということにしておくか。\nところで、何の用だ？",
  ui_story_5071_50710101_27_dialog_content = "はい、準備ができたので出発いたします。",
  ui_story_5071_50710101_28_dialog_content = "双閣港に通じる道路の修繕はうまく行っているようだな。\n暗鬼の襲撃も少なくなっている。",
  ui_story_5071_50710101_29_dialog_content = "だが、影の目の届かない所だ。気を抜いてはならん。",
  ui_story_5071_50710101_30_dialog_content = "もちろん、お前ならきっと「客人」との会談に、\nうまく対応してくれると信じているぞ。",
  ui_story_5071_50710101_31_dialog_content = "はい、ご期待に応えてみせます。",
  ui_story_5071_50710101_32_dialog_content = "ベセル、お前は総合商会の会長だ。\n影ノ街のことだけ考えていればいい。",
  ui_story_5071_50710101_33_dialog_content = "お父様…",
  ui_story_5071_50710101_34_dialog_content = "俺もそろそろ出かける時間だ。ちょうどいい、見送ろう。",
  ui_story_5071_50710101_35_dialog_content = "…",
  ui_story_5071_50710101_36_dialog_content = "影の中から颯爽と飛び立ち、自由に空を馳せる商会…",
  ui_story_5071_50710101_37_dialog_content = "<color=#FFB400>あなたの夢</color>は…かなったの？",
  ui_story_5071_50710101_38_dialog_content = "<color=#e8d9bb>カシャ！</color>",
  ui_story_5071_50710101_39_dialog_content = "間違いありません！\nスクープネタの匂いがプンプンしていますよ！",
  ui_story_5071_50710101_40_dialog_content = "は？",
  ui_story_5071_50710101_41_dialog_content = "はじめまして！\n『デイリー・スクープ速報版』の記者、ブランディです！",
  ui_story_5071_50710101_42_dialog_content = "取材させてください。超大型飛空艇――<color=#FFB400>浮遊商会艇</color>について、どう思われますか？",
  ui_story_5071_50710101_43_dialog_content = "ノーコメントです。",
  ui_story_5071_50710101_44_dialog_content = "いきなり取材拒否ですか。\nやはりビジネス界の大物は一筋縄ではいかないようですね。",
  ui_story_5071_50710101_45_dialog_content = "ですが、大丈夫です。いいネタを見つけましたから…",
  ui_story_5071_50710101_46_dialog_content = "PlayerNameさん！こっちです！こっちを見てください！",
  ui_story_5071_50710101_47_dialog_content = "<color=#e8d9bb>カシャ！</color>",
  ui_story_5071_50710101_48_dialog_content = "PlayerNameさんも<color=#FFB400>初飛行の式典</color>に招待されたのですね。\n浮遊商会艇に対する感想を聞かせてもらえませんか？",
  ui_story_5071_50710101_49_dialog_content = "親近感がわくな",
  ui_story_5071_50710101_50_dialog_content = "使われてる技術は違うけど、この飛空艇も巨像と同じように、\n空を飛ぶ大きなものだからね。",
  ui_story_5071_50710101_51_dialog_content = "壮観だね",
  ui_story_5071_50710101_52_dialog_content = "今までは小型の飛空艇しか見たことなかったから。まさかシェオルさんが\n商会もろとも移動する巨大な飛空艇を造るとは思わなかった…",
  ui_story_5071_50710101_53_dialog_content = "確かに飛空艇の中では突出した存在ですが、\nPlayerNameさんのソラヴァンにはかないませんよね？",
  ui_story_5071_50710101_54_dialog_content = "それはそうだけど…でも、大きさで言ったら、\n前にコンサートを開いたイクストウルに匹敵するんじゃないかな？",
  ui_story_5071_50710101_55_dialog_content = "なるほど。これで明日の一面を飾る記事は決まりました――",
  ui_story_5071_50710101_56_dialog_content = "「さすが空の末裔！浮遊商会艇もソラヴァンには敵わない」！",
  ui_story_5071_50710101_57_dialog_content = "ちょっと待ってよ。そんなこと言ってないよ！？",
  ui_story_5071_50710101_58_dialog_content = "<color=#e8d9bb>ザザー…</color>",
  ui_story_5071_50710101_59_dialog_content = "傷つくことも失敗することも恐れない。\nあきらめなければ、必ず幸運はやってくる！",
  ui_story_5071_50710101_60_dialog_content = "みんな、お久しぶり！元気だったー？",
  ui_story_5071_50710101_61_dialog_content = "これは…影ノ街で大人気のアイドル、ゴルディじゃないか！？\nゴルディを呼ぶなんて、さすが浮遊商会だな！",
  ui_story_5071_50710101_62_dialog_content = "知らないの？ゴルディを大人気アイドルに育てたのは、\n浮遊商会のシェオル会長なのよ！",
  ui_story_5071_50710101_63_dialog_content = "浮遊商会はエンタメ業界にまで手を広げてるのか？\nシェオル会長は、いったいいくつの事業を手掛けてるんだ…",
  ui_story_5071_50710101_64_dialog_content = "アイドルだか、飛空艇だか知らないが、ただの人気取りだろう…\nシャドウマスターが出席しないなら、こんな式典、誰が参加するか。",
  ui_story_5071_50710101_65_dialog_content = "みんな、初飛行の式典がもうすぐ始まるわ！",
  ui_story_5071_50710101_66_dialog_content = "その前に新曲を披露しちゃうわよ。曲名は――",
  ui_story_5071_50710101_67_dialog_content = "<size=45>『マイ・ドリーム』！</size>",
  ui_story_5071_50710101_68_dialog_content = "みんなで一緒に風に乗って、空へ飛び立ちましょ！",
  ui_story_5071_50710101_69_dialog_content = "♪果てしない空、雲が晴れれば、そこには希望。\n夢は地平線の彼方、朝日と一緒に空を昇っていく♪",
  ui_story_5071_50710101_70_dialog_content = "♪翼を広げて、青い空へ。夢はすぐそこにあるの。まぶしい光を放って♪",
  ui_story_5071_50710101_71_dialog_content = "（さすがゴルディだ…さっきまでざわついてた来賓たちが、\n歌声に魅せられて、リズムに合わせて身体を動かしてる）",
  ui_story_5071_50710101_72_dialog_content = "（ただ…ファンクラブも来てるから…\nその黄色い叫び声で、鼓膜が破れちゃったみたい…）",
  ui_story_5071_50710101_73_dialog_content = "（シェオルさんが招待したお客さんなら、皆すごいんだろうな…\nどんな人たちなんだろう…）",
  ui_story_5071_50710101_74_dialog_content = "おお、いらっしゃったぞ！\nシャドウマスターだ、急いで出迎えよう――",
  ui_story_5071_50710101_75_dialog_content = "（イスタバンさんも来てるの？なんか珍しいな…）",
  ui_story_5071_50710101_76_dialog_content = "あと1分ほどで、テープカットが始まるわ。\nシャドウマスターはいつでも時間びったりなのね。",
  ui_story_5071_50710101_77_dialog_content = "最高のタイミングで姿を現すのは、ビジネスにとって重要だからな。\nシェオル会長から学んだコツさ。",
  ui_story_5071_50710101_78_dialog_content = "シャドウマスター！このような盛大な場でお会いできて光栄です！",
  ui_story_5071_50710101_79_dialog_content = "あ、あの…わ、私のことは覚えていらっしゃいますか？",
  ui_story_5071_50710101_80_dialog_content = "シャドウマスター、以前2人きりでお会いしたいとお手紙を差し上げたのですが、\nご覧になっていただけましたか？",
  ui_story_5071_50710101_81_dialog_content = "シャドウマスター！私も、その…シャドウマスター…",
  ui_story_5071_50710101_82_dialog_content = "皆さん、お静かに。シャドウマスターは本日浮遊商会艇で、\n皆さんとお話しする時間を設けています。",
  ui_story_5071_50710101_83_dialog_content = "とは言いましても、事前予約された方のみですが。",
  ui_story_5071_50710101_84_dialog_content = "今はステージで熱唱しているお嬢さんに視線を向けようではありませんか。",
  ui_story_5071_50710101_85_dialog_content = "シャドウマスターに会うのに、\nそんな煩わしい決まりがあったとは知りませんでした。",
  ui_story_5071_50710101_86_dialog_content = "…",
  ui_story_5071_50710101_87_dialog_content = "自己紹介が遅れました。大陸商会の会長ハンスです。まだ日が浅いもので、\n影ノ街の決まりをよく知らず、お気に触っていなければよいのですが。",
  ui_story_5071_50710101_88_dialog_content = "大陸商会の…ハンス会長だって！？公の場には顔を出さないって聞いてたが…\nさすがシェオル会長だな。あ、いや…シャドウマスターのおかげか。",
  ui_story_5071_50710101_89_dialog_content = "大陸商会？影ノ街にそんな商会あったの？",
  ui_story_5071_50710101_90_dialog_content = "近年になって影ノ街の外の町で商売を始めた商会だ。\n影ノ街に進出したばかりだが、かなり勢いに乗ってる商会だぞ。",
  ui_story_5071_50710101_91_dialog_content = "ハンスさん、お会いできてうれしいです。\n本当に来てくださるとは思いませんでした。",
  ui_story_5071_50710101_92_dialog_content = "浮遊商会は今回影ノ街じゅうの名だたる商会の会長をすべて招待されたのでしょう？\nこんな好機を逃す手はありません。",
  ui_story_5071_50710101_93_dialog_content = "しかも、めったに公の場に姿を現さないシャドウマスターもお見えになると聞いたので、\nぜひこの機にお会いしたいと思いまして。",
  ui_story_5071_50710101_94_dialog_content = "そして…あなたがシェオルさん、<color=#FFB400>浮遊商会</color>の会長でいらっしゃいますね？\n私にはまさに雲の上の存在です。",
  ui_story_5071_50710101_95_dialog_content = "ハンスさんは、冗談がお上手ですね。",
  ui_story_5071_50710101_96_dialog_content = "<color=#FFB400>大陸商会</color>のネットワークはアストラ各地に広がっているでしょう？\nそれに、空と大地は共存するものですよ。",
  ui_story_5071_50710101_97_dialog_content = "この飛空艇、素晴らしいですね。気に入りました。",
  ui_story_5071_50710101_98_dialog_content = "ハンスさんに気に入っていただけたなら、\n浮遊商会も光栄に思いますわ。",
  ui_story_5071_50710101_99_dialog_content = "ところで、シャドウマスター。2人だけでお話する機会をいただけませんか？",
  ui_story_5071_50710101_100_dialog_content = "ハンスさん、申し訳ございません――",
  ui_story_5071_50710101_101_dialog_content = "かわいらしいタコの紳士さん。\n私は今、シャドウマスターにお話しているのですよ。",
  ui_story_5071_50710101_102_dialog_content = "…",
  ui_story_5071_50710101_103_dialog_content = "ハンスさん、お申し出は考えておこう。",
  ui_story_5071_50710101_104_dialog_content = "ありがとうございます。よい知らせをお待ちしています。",
  ui_story_5071_50710101_105_dialog_content = "クレーケン、今の女性との会談をセッティングしてくれ。",
  ui_story_5071_50710101_106_dialog_content = "…はい。承知いたしました。",
  ui_story_5071_50710101_107_dialog_content = "（あら？シャドウマスターがあんな嫌味っぽい女のために、\n自らルールを破るなんて、どうしたのかしら？）",
  ui_story_5071_50710101_108_dialog_content = "PlayerName、いつまで隅でそうしているつもりだ？",
  ui_story_5071_50710101_109_dialog_content = "あ、イ、イスタバンさん…！こ、こんにちは。\nさっきは皆忙しそうで、挨拶できなくてすみません。",
  ui_story_5071_50710101_110_dialog_content = "行くぞ。次はお前が俺と登場する番だ。",
  ui_story_5071_50710101_111_dialog_content = "え？",
  ui_story_5071_50710101_112_dialog_content = "私の新曲、気に入ってくれたらうれしいわ！\n続いて、盛大にお迎えしましょう――",
  ui_story_5071_50710101_113_dialog_content = "シャドウマスターイスタバン氏、浮遊商会シェオル会長、\nアストラ大陸の賓客PlayerName氏の登場です！テープカット式の始まりです！",
  ui_story_5071_50710101_114_dialog_content = "こんな催しがあったなんて知りませんでした…",
  ui_story_5071_50710101_115_dialog_content = "フフ、緊張することないわ。\n目の前のリボンをハサミで切るだけよ。",
  ui_story_5071_50710101_116_dialog_content = "<color=#e8d9bb>カシャ！</color>",
  ui_story_5071_50710101_117_dialog_content = "この飛空艇は、シェオル女史が会長を務める浮遊商会が出資して造った、\n観光、ショッピング、レジャー、バカンスなどが楽しめる多目的施設を備えた超大型飛空艇です。",
  ui_story_5071_50710101_118_dialog_content = "今後は私のような普通の光霊も空の末裔のように、\n空の上の暮らしやレジャー、ショッピングを楽しめるようになります。",
  ui_story_5071_50710101_119_dialog_content = "今日は離陸後、影ノ街上空を一周し、夜には花火を上げて今日というこの日を祝います。\n考えただけでもロマンチックですよね！",
  ui_story_5071_50710101_120_dialog_content = "ただ、皆さんも風景に見とれてばかりいないで、\n飛空艇上で開催されるイベントにも参加してくださいね！",
  ui_story_5071_50710101_121_dialog_content = "ゴルディの握手会、アリーウッドの特別上映会のほか、\n有史以来最も透明性の高い浮遊オークションも開催されます！",
  ui_story_5071_50710101_122_dialog_content = "それでは皆さん、一緒にカウントダウンをお願いします――",
  ui_story_5071_50710101_123_dialog_content = "3…",
  ui_story_5071_50710101_124_dialog_content = "2…",
  ui_story_5071_50710101_125_dialog_content = "1！",
  ui_story_5071_50710101_126_dialog_content = "浮遊商会艇…",
  ui_story_5071_50710101_127_dialog_content = "<size=50>離陸です！</size>",
  ui_story_5071_50710101_128_dialog_content = "おお！離陸したぞ！本当に飛んだ！",
  ui_story_5071_50710101_129_dialog_content = "何を驚いてるんだ。飛空艇に初めて乗ったわけでもあるまいし。\n白夜城にいた頃は、これくらいの景色毎日観ていたぞ。",
  ui_story_5071_50710101_130_dialog_content = "白夜城はいい所かもしれないけど、あの島は動かないじゃない。\nそれにしても、シェオル会長の目利きの良さには感服するわ。",
  ui_story_5071_50710101_131_dialog_content = "確かに鋭いですね。",
  ui_story_5071_50710101_132_dialog_content = "ですが…空を飛ぶものは、いつか必ず…",
  ui_story_5071_50710101_X132_dialog_content = "地に落ちるものです。",
  ui_story_5071_50710201_1_dialog_content = "<color=#e8d9bb>浮遊商会艇・豪華客室</color>",
  ui_story_5071_50710201_2_dialog_content = "シャドウマスター、今日ようやく感謝の意を伝えることができます…",
  ui_story_5071_50710201_3_dialog_content = "シャドウマスターが間に入ってくださったおかげで、\n息子がついに願い通り、白夜城へ留学することになりました！",
  ui_story_5071_50710201_4_dialog_content = "ハハ、それは実に喜ばしい。",
  ui_story_5071_50710201_5_dialog_content = "息子さんは聡明で、自分の考えをしっかり持っている。\n留学できたのは、本人の努力の結果だろう。",
  ui_story_5071_50710201_6_dialog_content = "だが、何か心配事でもあるようだが？",
  ui_story_5071_50710201_7_dialog_content = "はい…白夜城の貴族からいじめられやしないかと心配で…",
  ui_story_5071_50710201_8_dialog_content = "ああ、私としたことが何を言っているのでしょう…\nシャドウマスター、馬鹿なことを言って申し訳ございません。",
  ui_story_5071_50710201_9_dialog_content = "心配するのも当然だ。お前の息子さんは優秀だ。",
  ui_story_5071_50710201_10_dialog_content = "彼には無事に戻り、留学で見聞きしたことや学んだことを活かして、\n影ノ街に学校を開いてほしいと俺も望んでいる。",
  ui_story_5071_50710201_11_dialog_content = "約束しよう。あなたの心配するようなことは決して起こらない。",
  ui_story_5071_50710201_12_dialog_content = "そう言っていただけて、私もようやく安心いたしました！",
  ui_story_5071_50710201_13_dialog_content = "こちらはうちで作ったワインです。どうかお受け取りください。\n貴重なお時間をいただき、ありがとうございました…",
  ui_story_5071_50710201_14_dialog_content = "気にするな。それでは。",
  ui_story_5071_50710201_15_dialog_content = "<color=#e8d9bb>浮遊商会艇・ゴルディ握手会</color>",
  ui_story_5071_50710201_16_dialog_content = "PlayerName、いつも応援ありがとう！",
  ui_story_5071_50710201_17_dialog_content = "あなたの期待に応えられるように、\nこれからももっと素敵な音楽を生み出せるよう頑張るわ！",
  ui_story_5071_50710201_18_dialog_content = "うん！ゴルディは本当に空と縁があるよね。\n今日の新曲も――",
  ui_story_5071_50710201_19_dialog_content = "おい、1人1分じゃないのか？前の人、時間オーバーでしょ！？",
  ui_story_5071_50710201_20_dialog_content = "ふふ、ごめんなさい、PlayerName。\n今度時間がある時、絶対事務所に遊びにきてね。",
  ui_story_5071_50710201_21_dialog_content = "ゴルディ！こっちとも話してくれよ！",
  ui_story_5071_50710201_22_dialog_content = "それにしても…ほんのしばらくの間にこんなにたくさんの人を\nファンにしちゃうなんて、ゴルディはすごいな…",
  ui_story_5071_50710201_23_dialog_content = "友だちは皆忙しそうだし…\nひとりであちこち見て回ろうかな。",
  ui_story_5071_50710201_24_dialog_content = "あ、あの…覚えていらっしゃいますか？\n昔隣に住んでいた者です。",
  ui_story_5071_50710201_25_dialog_content = "ご両親が亡くなられた時、シャドウマスターは家におられず…\n私がお二人のお葬式のお手伝いを…",
  ui_story_5071_50710201_26_dialog_content = "両親を静かな所に眠らせてくれてありがとう。\n当時の恩は忘れていない。",
  ui_story_5071_50710201_27_dialog_content = "い、いいえ、とんでもありません…\n今は私の方がご恩を賜りたく…",
  ui_story_5071_50710201_28_dialog_content = "シャドウマスターのおかげで、近年は雑貨店を数軒営むことができています。\nもちろん、浮遊商会の足下にも及びませんが、それなりに知られた存在となれました。",
  ui_story_5071_50710201_29_dialog_content = "しかし、ここへきて近くの商店が手を結び、私の店を潰そうとしており、\n実際に破産の寸前まで追い込まれております…",
  ui_story_5071_50710201_30_dialog_content = "なす術もなく困り果て、\nこうしてシャドウマスターにお願いにまいりました…",
  ui_story_5071_50710201_31_dialog_content = "何が望みだ？そいつらを片付けろと？",
  ui_story_5071_50710201_32_dialog_content = "や、やってくださるんですか？",
  ui_story_5071_50710201_33_dialog_content = "それより、なぜ総合商会に入らない？\n合法に営んでいさえすれば、やつらも色々な意味でお前を守るはずだろう？",
  ui_story_5071_50710201_34_dialog_content = "それは、その…総合商会に入るには、\n高額な会費が必要と聞いたもので…",
  ui_story_5071_50710201_35_dialog_content = "まだ入ってもいない、知りもしないのに、\n実際のところなど分かりはしないだろう？",
  ui_story_5071_50710201_36_dialog_content = "分かりました！きっとやつらに騙されていたんです！",
  ui_story_5071_50710201_37_dialog_content = "まだ…総合商会に入ることはできますか？",
  ui_story_5071_50710201_38_dialog_content = "俺は総合商会の会長ではない。だが、これだけは言える。\n総合商会の扉はいつでも開かれている。",
  ui_story_5071_50710201_39_dialog_content = "後悔するとすれば、\n今になってようやくその決断を下したことだろうな。",
  ui_story_5071_50710201_40_dialog_content = "ありがとうございます！シャドウマスター！\nこれからもずっとあなた様を…そして総合商会の決定を支持します！",
  ui_story_5071_50710201_41_dialog_content = "ご両親を埋葬してくださった方はすでになくなっているはず。\nさきほどの男は僕と同じ「趣味」があるようですね。",
  ui_story_5071_50710201_42_dialog_content = "そんなことはどうでもいい。\nクレーケン、これからのことを教えてやれ。",
  ui_story_5071_50710201_43_dialog_content = "承知いたしました。",
  ui_story_5071_50710201_44_dialog_content = "<color=#e8d9bb>浮遊商会艇・映画館の外</color>",
  ui_story_5071_50710201_45_dialog_content = "うーん…「実際にあった話を題材にした青春物語――\n『アリーウッド・ドリーム』絶賛上映中、チケット残り1枚」？",
  ui_story_5071_50710201_46_dialog_content = "リリカの最新作なんだね…最近どうしてるか全然ウワサを聞かなかったけど、\n新作の撮影に励んでたのか…",
  ui_story_5071_50710201_47_dialog_content = "特にやることもないし、売り上げに貢献してあげよう！",
  ui_story_5071_50710201_48_dialog_content = "すみません。『アリーウッド・ドリーム』のチケットをください！",
  ui_story_5071_50710201_49_dialog_content = "え、ええっ…？ブランディに先を越されちゃった！",
  ui_story_5071_50710201_50_dialog_content = "この子…ずっと黙ったままなんだ。",
  ui_story_5071_50710201_51_dialog_content = "迷子か？でも、子どもを探してる親なんていたか？",
  ui_story_5071_50710201_52_dialog_content = "どこの子だ？",
  ui_story_5071_50710201_53_dialog_content = "どうして人が集まってるんだろう？\n何かイベントでもやってるのかな…",
  ui_story_5071_50710201_54_dialog_content = "（くんくん――）",
  ui_story_5071_50710201_55_dialog_content = "え？子ども？",
  ui_story_5071_50710201_56_dialog_content = "ウオオン――",
  ui_story_5071_50710201_57_dialog_content = "え？ええっ？ど、どうして抱きつかれたの？",
  ui_story_5071_50710201_58_dialog_content = "人見知りの子どもが自分から抱き着いたってことは…\n家族かな？",
  ui_story_5071_50710201_59_dialog_content = "君はこの子のお兄さんだろう？こんな小さな子を独りにするなんて、\nダメじゃないか。さっきまで大泣きしてたんだよ。",
  ui_story_5071_50710201_60_dialog_content = "今後は気を付けるんだよ。",
  ui_story_5071_50710201_61_dialog_content = "……",
  ui_story_5071_50710201_62_dialog_content = "……",
  ui_story_5071_50710201_63_dialog_content = "あの…君は…？",
  ui_story_5071_50710201_64_dialog_content = "<color=#e8d9bb>グウゥ―…</color>",
  ui_story_5071_50710201_65_dialog_content = "お兄ちゃん…ボク、お腹空いちゃった…",
  ui_story_5071_50710201_66_dialog_content = "シャドウマスター、お変わりありませんか？",
  ui_story_5071_50710201_67_dialog_content = "侯爵殿か？てっきり最近は孫娘の勉学に付き合って、\n白夜城の荘園で過ごしているものと思っていたが。",
  ui_story_5071_50710201_68_dialog_content = "ははは。ずっと上にいたのでは、「改革」の名を借りて、\n私の資産を没収する輩が出てきてしまいますからね。",
  ui_story_5071_50710201_69_dialog_content = "総合商会は高額の会費で潤っているはずでしょう？\nまだ物足りないというのですか？",
  ui_story_5071_50710201_70_dialog_content = "ハハ、それとこれとは別の話だ、侯爵殿。",
  ui_story_5071_50710201_71_dialog_content = "あなたの商会は、総合商会の規定に違反した。\nだから差し押さえられたにすぎん。",
  ui_story_5071_50710201_72_dialog_content = "今後きちんと改め、これまでのような表沙汰にできない手段を捨てれば、\n商売を続けることは何でもない。",
  ui_story_5071_50710201_73_dialog_content = "総合商会の会費の大部分は、\n規定通り「税」として白夜城に納めている。",
  ui_story_5071_50710201_74_dialog_content = "総合商会は残りのわずかな会費収入で、\n普段の出費をまかなっているにすぎない。",
  ui_story_5071_50710201_75_dialog_content = "まやかしの言葉を口にする時のご令嬢の姿はあなたにそっくりですね。\n知らない人が見れば、きっと実の娘と思うでしょう。",
  ui_story_5071_50710201_76_dialog_content = "会長から説明を受けたなら、なぜ俺を訪ねてきた？",
  ui_story_5071_50710201_77_dialog_content = "イスタバン、私にまやかしは通じません…",
  ui_story_5071_50710201_78_dialog_content = "影ノ街が今の繁栄を保てているのは、なぜですか？",
  ui_story_5071_50710201_79_dialog_content = "イスタバン組がここまで大きくなれたのは、\n何のおかげですか？",
  ui_story_5071_50710201_80_dialog_content = "あなたの手は今この飛空艇に乗っている誰の手よりも汚れている…\nまさか、きれいさっぱり洗い流せると思っているのですか？",
  ui_story_5071_50710201_81_dialog_content = "あなたの放任する「改革」は、\nあなた自身の首を絞めることになりますよ！",
  ui_story_5071_50710201_82_dialog_content = "ハハ、そうか？",
  ui_story_5071_50710201_83_dialog_content = "それは実に楽しみだな…",
  ui_story_5071_50710201_84_dialog_content = "影ノ街を正常な軌道に乗せんとする「改革」が、\nいったいどう俺の首を絞めるのか、見てみたいな。",
  ui_story_5071_50710201_85_dialog_content = "モグモグ…モグモグ…",
  ui_story_5071_50710201_86_dialog_content = "ゆっくり食べなきゃ、のどに詰まらせちゃうよ！",
  ui_story_5071_50710201_87_dialog_content = "ローストチキンを2つにピザを4枚…それからケーキを5つ…\nいったい何日ご飯を食べてなかったの？",
  ui_story_5071_50710201_88_dialog_content = "モグモグ…ええっと、最後に食事してから、もう3時間たっちゃってるんだ。\nお腹ペコペコだよ…",
  ui_story_5071_50710201_89_dialog_content = "たった3時間で、こんなにお腹空くの！？",
  ui_story_5071_50710201_90_dialog_content = "ぼ、ボク…知らない人に会うと、緊張しちゃうんだ…\n緊張って、すごくエネルギーを使うから、それで…",
  ui_story_5071_50710201_91_dialog_content = "あ、あの…食事代はちゃんと返すから…",
  ui_story_5071_50710201_92_dialog_content = "シェ、シェオルさんを探すの…手伝ってくれない？",
  ui_story_5071_50710201_93_dialog_content = "シェオルさん…？",
  ui_story_5071_50710201_94_dialog_content = "ぼ、ボク…バージルっていうんだ。\nシェオルさんの所で働いてるんだよ。",
  ui_story_5071_50710201_95_dialog_content = "ゴホゴホッ…シェオルさん、こんな小さな子どもを働かせてるの？",
  ui_story_5071_50710201_96_dialog_content = "ご、ごご、誤解しないで！\nボクが雇ってほしいって頼んだんだ！",
  ui_story_5071_50710201_97_dialog_content = "どういうことかよく分からないけど、\n近くでシェオルさんの気配がするから――",
  ui_story_5071_50710201_98_dialog_content = "動くな！",
  ui_story_5071_50710201_99_dialog_content = "ターゲットだ！",
  ui_story_5071_50710201_100_dialog_content = "門番のワンコだよ！",
  ui_story_5071_50710201_101_dialog_content = "ワンコ出撃！",
  ui_story_5071_50710201_102_dialog_content = "あっちは…イスタバンさんの応接室だよね？",
  ui_story_5071_50710302_1_dialog_content = "どうされましたか？",
  ui_story_5071_50710302_2_dialog_content = "ありがとうございます。大丈夫です…何ともありません。",
  ui_story_5071_50710302_3_dialog_content = "パテ、パシ。いったいどういうことなの？",
  ui_story_5071_50710302_4_dialog_content = "ワンコたちはいい子の門番だよ。",
  ui_story_5071_50710302_5_dialog_content = "予約してないお客は悪い人、通すわけにはいかないよ。",
  ui_story_5071_50710302_6_dialog_content = "実に忠実なワンコだこと。\nただし、次からこんな大騒ぎはしないで。",
  ui_story_5071_50710302_7_dialog_content = "浮遊商会艇の上で暴れたりしたら、\n空から落ちちゃうかもしれないわよ。",
  ui_story_5071_50710302_8_dialog_content = "パテ、怖くないもん！\nパシも怖くないもん！",
  ui_story_5071_50710302_9_dialog_content = "でも、中でお客様と会っているシャドウマスターの邪魔をしたら、\n大変なことになるわよね？",
  ui_story_5071_50710302_10_dialog_content = "ボスの邪魔はダメ…いい子のワンコはちゃんとわかってるよ！",
  ui_story_5071_50710302_11_dialog_content = "あの…どこかの商会の会長に同行してこられた方ですか？\n失礼ですが、あなたをご招待した覚えはありませんが？",
  ui_story_5071_50710302_12_dialog_content = "本当によく似ています…近くで見ると、本当に瓜二つです…",
  ui_story_5071_50710302_13_dialog_content = "…？",
  ui_story_5071_50710302_14_dialog_content = "シェ、シェオル…さん！",
  ui_story_5071_50710302_15_dialog_content = "バージル？なぜ、あなたがここに？\n浮遊オークションの会場で待っているように言ったでしょ？",
  ui_story_5071_50710302_16_dialog_content = "ボ、ボク、さっきはお腹空いちゃって、何か食べようと思って出てきたんだけど…\n外は人がいっぱいで道に迷っちゃったんだ。",
  ui_story_5071_50710302_17_dialog_content = "でも、このお兄ちゃんが助けてくれたの！\nしかもおいしいものをいっぱい食べさせてくれたんだよ！",
  ui_story_5071_50710302_18_dialog_content = "あはは…大したことはしてないよ。",
  ui_story_5071_50710302_19_dialog_content = "あら？早々にPlayerNameとお友達になるなんて意外ね。\nバージルは知らない人に話しかけない質だと思っていたのにね。",
  ui_story_5071_50710302_20_dialog_content = "だ、だって…PlayerNameお兄ちゃんは骨董の匂いがするから、\nなんだか安心して…",
  ui_story_5071_50710302_21_dialog_content = "フフフ、それは確かにその通りね。\nPlayerNameは出土したばかりの骨董だもの。",
  ui_story_5071_50710302_22_dialog_content = "PlayerName…まさか、あの伝説の空の末裔さんですか！？",
  ui_story_5071_50710302_23_dialog_content = "申し訳ありません。まだ私の質問に答えていただいてませんわ。\nどなたですか？なぜ、こちらに？",
  ui_story_5071_50710302_24_dialog_content = "この飛空艇の警備員たちは、シャドウマスターの子犬さんたちと比べても、\n大して優しいとはいえませんよ。",
  ui_story_5071_50710302_25_dialog_content = "あ、わ、私は…イヴォンと申します。作家です。\n今日は十字路出版の特別執筆者として参りました。",
  ui_story_5071_50710302_26_dialog_content = "本当に申し訳ございません。先程はあのような騒ぎを起こしてしまい…\n今日この飛空艇でシャドウマスターにお会いするには事前予約が必要とは知らず…",
  ui_story_5071_50710302_27_dialog_content = "イヴォン…ボクの聞き間違いじゃないよね？\nあの有名な作家のイヴォンさん！？",
  ui_story_5071_50710302_28_dialog_content = "…あら。作家を長年続けていますが、\nこんなに小さな子も私の名前を知っているとは思いませんでした。",
  ui_story_5071_50710302_29_dialog_content = "イヴォンさんの作品は影ノ街の歴史を写し取ったものばかりです。\n影ノ街の読み書きのできる者は皆、あなたの作品を読んだことがありますよ。",
  ui_story_5071_50710302_30_dialog_content = "ただ、公には姿を見せない方だと思っていましたが…\n今日はなぜ…",
  ui_story_5071_50710302_31_dialog_content = "若い頃は、あれやこれやと気にすることも不安に思うことも多くありましたが、\nこれくらいの年になると、少し勇気も出てきたのです。",
  ui_story_5071_50710302_32_dialog_content = "そうでなかったら、未完成の作品のために、\n独り飛空艇に乗船などできませんでした。",
  ui_story_5071_50710302_33_dialog_content = "作品のためですか？",
  ui_story_5071_50710302_34_dialog_content = "一つ前の作品が酷評を受けてからというもの、\n筆を執る気が失せてしまっていたのですが――",
  ui_story_5071_50710302_35_dialog_content = "少し前に、<color=#FFB400>画家の友人</color>が出来まして、\nその方から色々と物語を聞いたのです。",
  ui_story_5071_50710302_36_dialog_content = "如何に心血を注ごうと、小説は真実の物語のように読者の心を掻き立てることはできません。\nその物語を聞いてから、私は夜も眠れぬほど興奮しています。",
  ui_story_5071_50710302_37_dialog_content = "あの物語をこのまま埋もれさせるわけにはいきません。\nですから、友人の励ましもあり、再び筆を執ったのですが…",
  ui_story_5071_50710302_38_dialog_content = "いくら素晴らしい物語でも、やはり細部の考証が必要です。\nそれでシャドウマスターを取材しようと、やって来たわけです。",
  ui_story_5071_50710302_39_dialog_content = "…危険なことは分かっています。シャドウマスターがご存じのことを\n私のような二流の作家に話してくれるかどうかも分かりませんし…",
  ui_story_5071_50710302_40_dialog_content = "小説を書くことが…どうして危険なんですか？",
  ui_story_5071_50710302_41_dialog_content = "この作品が世に出ることがかなえば、皆さんもお分かりになると思います。",
  ui_story_5071_50710302_42_dialog_content = "さすが作家さんですね。読者の興味をそそるのがお上手です。",
  ui_story_5071_50710302_43_dialog_content = "シェオルさん、こんなことをお願いするのは筋違いかとは思いますが、\nシャドウマスターに引き合わせてくださいませんか？お時間は取らせません！",
  ui_story_5071_50710302_44_dialog_content = "フフ、もしここで断れば、また影ノ街の文壇に\n商人は金のことばかりで、文化教養がないと酷評されるのでしょう？",
  ui_story_5071_50710302_45_dialog_content = "そうした評価を気にするタチではありませんが…\nイヴォンさんのファンとしては、断りがたい申し出ですね。",
  ui_story_5071_50710302_46_dialog_content = "今日はシャドウマスターもすでに「慣例破り」をしていることですし、\nここで少々お待ちください。",
  ui_story_5071_50710302_47_dialog_content = "コホン。イヴォンさん、バージルにサインを書いてもらえませんか？\n本人は恥ずかしくて言えないみたいなんですが…",
  ui_story_5071_50710302_48_dialog_content = "サインですか？構いませんよ。私の作品を気に入ってくれてうれしいです。\n今は原稿用紙しかないのですが、構いませんか？",
  ui_story_5071_50710302_49_dialog_content = "も…もちろん！！",
  ui_story_5071_50710302_50_dialog_content = "はい、どうぞ。サインだけでは物足りないのでは？\nまた会う機会があれば、本を一冊贈りましょう…",
  ui_story_5071_50710302_51_dialog_content = "そうですね…どの作品が一番お好きですか？",
  ui_story_5071_50710302_52_dialog_content = "ボ、ボボボボ、ボクは…『紅水銀の夫人』が一番好き！",
  ui_story_5071_50710302_53_dialog_content = "その題名…",
  ui_story_5071_50710302_54_option_content = "どこかで聞いたことがあるような…",
  ui_story_5071_50710302_55_dialog_content = "巨像にもあったはず！",
  ui_story_5071_50710302_56_option_content = "聞いたことない…",
  ui_story_5071_50710302_57_dialog_content = "『紅水銀の夫人』は…商会のトップだった、きれいだけど、\n冷酷な謎の女性「紅水銀の夫人」の伝奇小説なんだよ。",
  ui_story_5071_50710302_58_dialog_content = "夫人は愛する人のために貴族の身分を捨てて、\n影ノ街にやってきたんだ。",
  ui_story_5071_50710302_59_dialog_content = "旦那さんの死後は独りでたくさんの商会を切り盛りして、\nしかもひそかに旦那さんの仇を討ったんだ。",
  ui_story_5071_50710302_60_dialog_content = "『紅水銀の夫人』の話をしてるのかしら？\n私も大好きな作品よ。",
  ui_story_5071_50710302_61_dialog_content = "そ、そうなのですか？それはうれしいです…",
  ui_story_5071_50710302_62_dialog_content = "イヴォンさん、今人を遣ってお伺いを立てています。\n少ししたら返事があると思います。",
  ui_story_5071_50710302_63_dialog_content = "そうですか！心から感謝します、シェオルさん。",
  ui_story_5071_50710302_64_dialog_content = "運命とは時としてこうも不思議なのですね。余計なことを言うつもりはなかったのですが…\nあなたは本当に<color=#FFB400>メリッサ</color>夫人に瓜二つです。",
  ui_story_5071_50710302_65_dialog_content = "メリッサ…？お知り合いなのですか？\nつまり、『紅水銀の夫人』の物語は本当の…",
  ui_story_5071_50710302_66_dialog_content = "その通りです。紅水銀の夫人のモデルはメリッサ夫人です。",
  ui_story_5071_50710302_67_dialog_content = "メリッサ夫人？誰それ？",
  ui_story_5071_50710302_68_dialog_content = "君も知らないの？でも…そのメリッサ夫人って、\nシェオルさんにとって大切な人みたいだね。",
  ui_story_5071_50710302_69_dialog_content = "…",
  ui_story_5071_50710302_70_dialog_content = "イヴォンさん、マーキュリーの事績を本として残してくださり心から感謝します。\n本人がどんな人だったのか、本から想像できますから。",
  ui_story_5071_50710302_71_dialog_content = "メリッサ夫人のお子さんは仇にさらわれ、毒殺されたと聞きましたが…\nお母様と同様、力強く生きていらしたようですね。",
  ui_story_5071_50710302_72_dialog_content = "私はほとんど後悔を知らずに生きてきましたが、今はなぜ、早いうちに出版業に\n投資しなかったのかと後悔しています。そうすれば、もっと早くにお目にかかれましたのに。",
  ui_story_5071_50710302_73_dialog_content = "これからいくらでも機会はありますよ。\nもちろん、私の昔話にお付き合いいただければの話ですが。",
  ui_story_5071_50710302_74_dialog_content = "物語を聞くのはもともと好きなのです。\nマーキュリー夫人の話となれば、なおのこと…",
  ui_story_5071_50710302_75_dialog_content = "話は変わりますが、今執筆中の作品についても、\n喜んで投資いたします。",
  ui_story_5071_50710302_76_dialog_content = "それは、なんと…",
  ui_story_5071_50710302_77_dialog_content = "メリッサ夫人も、娘さんのこのような優秀な姿を見れば、\nきっと花のような美しい笑顔を浮かべることでしょうね。",
  ui_story_5071_50710302_78_dialog_content = "シェオルさんはお客様にはいつも寛大ですが、\n取引仲間には難題を出してばかりで困ります。",
  ui_story_5071_50710302_79_dialog_content = "あら？こんなに早くお返事が？",
  ui_story_5071_50710302_80_dialog_content = "こちらがイヴォン女史ですね。",
  ui_story_5071_50710302_81_dialog_content = "シャドウマスターがお会いになるそうです。\n僕に付いてきてください。中で少々お待ちいただけますか？",
  ui_story_5071_50710302_82_dialog_content = "！！！",
  ui_story_5071_50710302_83_dialog_content = "シェオルさん、お引き合わせいただき本当に感謝します！",
  ui_story_5071_50710302_84_dialog_content = "先程おっしゃっていたでしょう？運命の偶然です。\nシャドウマスターにお会いになった後、またお話しできることを楽しみにしています。",
  ui_story_5071_50710302_85_dialog_content = "こちらこそ楽しみにしています。",
  ui_story_5071_50710302_86_dialog_content = "…",
  ui_story_5071_50710302_87_dialog_content = "PlayerName、なぜまだぼうっとしているのかしら？",
  ui_story_5071_50710302_88_dialog_content = "それとも…",
  ui_story_5071_50710302_89_dialog_content = "私の過去に急に興味が湧いたのかしら？",
  ui_story_5071_50710401_1_dialog_content = "<color=#e8d9bb>10年ほど前</color>",
  ui_story_5071_50710401_2_dialog_content = "早く来いよ！あれが暗潮の危機を打ち負かしたっていう連合軍じゃないか？",
  ui_story_5071_50710401_3_dialog_content = "白夜城に向かってるみたいだ…ってことは、白夜城の騎士なのか！？",
  ui_story_5071_50710401_4_dialog_content = "白夜城の騎士はきらびやかな制服で着飾ってるはずだ。\nこの軍はみすぼらしいし、きっと影ノ街の軍だろうよ。",
  ui_story_5071_50710401_5_dialog_content = "影ノ街はとうの昔に暗鬼に潰されちまったんじゃないのか？\nまだ生きてるヤツがいたのか？",
  ui_story_5071_50710401_6_dialog_content = "白夜城の応援のおかげで、かなり生き残ったらしいぞ。",
  ui_story_5071_50710401_7_dialog_content = "やっぱり後ろ盾があると違うよな。\nどんなに乱れてようと尻尾を振りゃあ、ご主人様が助けてくれるんだからよ。",
  ui_story_5071_50710401_8_dialog_content = "シッ…大きな声で言うんじゃない！\nあいつらは張り手ひとつで暗鬼を殺せるんだ。気を付けろ。",
  ui_story_5071_50710401_9_dialog_content = "おや？ちょっと待てよ。あれってシェオルじゃないのか？\nおい、どこへ行くんだよ！？",
  ui_story_5071_50710401_10_dialog_content = "影であれこれ悪口を言うくらいなら、直接言えばいいでしょう？\n彼らは少なくとも暗鬼を倒した英雄なのよ。",
  ui_story_5071_50710401_11_dialog_content = "シェオル…確かにお前は何度も暗鬼を追っ払ってくれたけどよ。\nあいつらは暗鬼より恐ろしいかもしれねえ。厄介な事にならないように気を付けろ。",
  ui_story_5071_50710401_12_dialog_content = "安心してちょうだい…誰だって「甘い汁」と「金」には、\n逆らわないでしょうからね。",
  ui_story_5071_50710401_13_dialog_content = "止まれ！誰だ？",
  ui_story_5071_50710401_14_dialog_content = "そんなに怒らないでください。\nほら、私は暗鬼じゃありませんよ。",
  ui_story_5071_50710401_15_dialog_content = "この辺りは乾燥しているので、うちの店に寄って\n氷水でも飲んでもらおうかとお誘いに来ただけです。",
  ui_story_5071_50710401_16_dialog_content = "タダほど高い買い物はない。",
  ui_story_5071_50710401_17_dialog_content = "フフ。タダで食事は振る舞えませんが、タダのお水ならありますよ。\nもちろん、お代さえいただければ、食事もお出しします。",
  ui_story_5071_50710401_18_dialog_content = "本場のサソリの丸焼き弁当です。\n影ノ街に戻ったら、もう食べられませんよ。",
  ui_story_5071_50710401_19_dialog_content = "先を急ぐ。気持ちだけもらっておく。",
  ui_story_5071_50710401_20_dialog_content = "長い距離を歩いてきたんでしょう？少しは休んだらどうですか？\nあなたは疲れていなくても、部下の皆さんは疲れているんじゃありません？",
  ui_story_5071_50710401_21_dialog_content = "ハハハ、この辺りの者は気性が荒いと聞いていたが、\nお前は例外のようだ。",
  ui_story_5071_50710401_22_dialog_content = "では皆さん、お水を飲みたい方も、食事がしたい方も、\n私に付いてきてください。",
  ui_story_5071_50710401_23_dialog_content = "<color=#e8d9bb>シェオルは外した手袋を振りながら、\n懸命に周りの人々の注意を引き付ける。</color>",
  ui_story_5071_50710401_24_dialog_content = "<color=#e8d9bb>まぶしい日の光の下に、シェオルの腕にあるほんのりと赤くツヤのある細長い痕が映し出され、\nそれはまるで舌を出した小さなヘビのようだった</color>",
  ui_story_5071_50710401_25_dialog_content = "<color=#e8d9bb>それを見たイスタバンは声の源をたどり、\nつぶさにこの少女を観察した</color>",
  ui_story_5071_50710401_26_dialog_content = "おい、待て！お、お前はメリッサ…いや…",
  ui_story_5071_50710401_27_dialog_content = "シェオルか！？",
  ui_story_5071_50710401_28_dialog_content = "あら？自己紹介はしていなかったはずですけど。",
  ui_story_5071_50710401_29_dialog_content = "確かにこの辺りでは、それなりに名は知られていますが、\nなぜあなたが…",
  ui_story_5071_50710401_30_dialog_content = "やっと見つけたぞ！",
  ui_story_5071_50710401_31_dialog_content = "ハハハ、誓いは果たせないものとばかり思っていたが…",
  ui_story_5071_50710401_32_dialog_content = "さあ！一緒に影ノ街に戻るのだ。影ノ街こそお前の故郷だ！",
  ui_story_5071_50710401_33_dialog_content = "（…村人たちの言っていた通りだわ。\n影ノ街の人たちは情緒の起伏が激しくて、道理が通じないみたい）",
  ui_story_5071_50710401_34_dialog_content = "フフ、お客様。影ノ街に行ってみたいのは確かですが、\n今はお店も持っているので…",
  ui_story_5071_50710401_35_dialog_content = "あ、そう言えば、店番があるんです！",
  ui_story_5071_50710401_36_dialog_content = "誤解するな――",
  ui_story_5071_50710401_37_dialog_content = "来ないで！！",
  ui_story_5071_50710402_1_dialog_content = "ハハハ、さすがはメリッサの娘だな。\nきちんとした訓練は受けていないが、その戦闘能力はみくびれない。",
  ui_story_5071_50710402_2_dialog_content = "あなた…何をするつもり？私はただの商人よ。\n何の利用価値があるって言うの？",
  ui_story_5071_50710402_3_dialog_content = "すまない。説明が足りなかったようだが、\n俺は本当に友人の生き別れた娘を探しているだけだ。",
  ui_story_5071_50710402_4_dialog_content = "私は小さい頃から砂漠で暮らしているのよ。\n影ノ街と関係があるはずないわ。",
  ui_story_5071_50710402_5_dialog_content = "お前の腕にはヘビの印がある。そうだろう？",
  ui_story_5071_50710402_6_dialog_content = "今見たんでしょう？",
  ui_story_5071_50710402_7_dialog_content = "ああ…だがそれだけではない。お前が母親と別れた時に着ていた服には名前が書いてある。\n――「シェオル」、そうだな？",
  ui_story_5071_50710402_8_dialog_content = "今の反応を見たところ、シェオルで間違いないようだ。",
  ui_story_5071_50710402_9_dialog_content = "…私が…誰の娘ですって？",
  ui_story_5071_50710402_10_dialog_content = "俺の友人だ。お前はメリッサという夫人の娘だ。",
  ui_story_5071_50710402_11_dialog_content = "私がその人の娘だっていうなら、なぜ本人が会いに来ないの？",
  ui_story_5071_50710402_12_dialog_content = "本人は…すでに病死している。",
  ui_story_5071_50710402_13_dialog_content = "つまり、証拠はないってことね。",
  ui_story_5071_50710402_14_dialog_content = "…",
  ui_story_5071_50710402_15_dialog_content = "俺はずっとこれを持ち歩いていた。\nいつかこの手でお前に渡せる日が来ると思ってな。",
  ui_story_5071_50710402_16_dialog_content = "これって…純金？",
  ui_story_5071_50710402_17_dialog_content = "お前の母親が残した形見だ。\nお前は光力術を使える。使いこなせるはずだ。",
  ui_story_5071_50710402_18_dialog_content = "そんな簡単に私に渡していいの？",
  ui_story_5071_50710402_19_dialog_content = "考えがまとまったら、いつでも影ノ街まで俺を訪ねて来い。",
  ui_story_5071_50710402_20_dialog_content = "あなたもよく考えることね。物は受け取ってもいいけど、\nあなたを訪ねるとは限らないわ。",
  ui_story_5071_50710402_21_dialog_content = "いや、必ず訪ねてくる。",
  ui_story_5071_50710402_22_dialog_content = "…おかしな人。",
  ui_story_5071_50710402_23_dialog_content = "でも…タダほど高い買い物ってないって本当？",
  ui_story_5071_50710402_24_dialog_content = "<color=#e8d9bb>コンコンコンッ――</color>",
  ui_story_5071_50710402_25_dialog_content = "入れ。",
  ui_story_5071_50710402_26_dialog_content = "<color=#e8d9bb>タッタッタッ…</color>",
  ui_story_5071_50710402_27_dialog_content = "シェオルか？",
  ui_story_5071_50710402_28_dialog_content = "ハハハ、言っただろう？必ず俺を訪ねてくると。\n影ノ街に来てしばらく経つようだが、この街には慣れたか？",
  ui_story_5071_50710402_29_dialog_content = "<color=#e8d9bb>ポンッ――</color>",
  ui_story_5071_50710402_30_dialog_content = "先にこれを見てください。",
  ui_story_5071_50710402_31_dialog_content = "お？",
  ui_story_5071_50710402_32_dialog_content = "イスタバン組ともあろうものが、商売を始めたんですね。",
  ui_story_5071_50710402_33_dialog_content = "ただサプライヤーの選定がよいとは言えないようです。",
  ui_story_5071_50710402_34_dialog_content = "そちらに商品を卸しているフォックス商会ですが、白夜城の貴族をだますほど\n思いあがっているようですね…詳細はこの資料をご覧ください。",
  ui_story_5071_50710402_35_dialog_content = "私でさえ簡単に追跡できたんです。\n白夜城の衛兵もとうの昔に気づいているはずですよね？",
  ui_story_5071_50710402_36_dialog_content = "あなたの「信用する」サプライヤーが牢に送り込まれるのも、\nそう遠くないことでしょうね。",
  ui_story_5071_50710402_37_dialog_content = "フォックス商会が捕まれば、イスタバン組は商品の供給源を絶たれることになります。\nお客様にはどう説明するおつもりですか？",
  ui_story_5071_50710402_38_dialog_content = "俺を訪ねてきたのは、そのためか？",
  ui_story_5071_50710402_39_dialog_content = "シャドウマスター、急にそんな深刻な顔をしないでください。",
  ui_story_5071_50710402_40_dialog_content = "今日お訪ねしたのは、決して弱みに付け込むためではありません。\n手助けにきたんです。",
  ui_story_5071_50710402_41_dialog_content = "ビジネスに関しては、いくら闇組織の皆さんでも、\nその道の者の手助けが必要なんじゃありませんか？",
  ui_story_5071_50710402_42_dialog_content = "もちろん、シャドウマスターが相手ですから、\n優待価格でご提供しますよ。",
  ui_story_5071_50710402_43_dialog_content = "（なるほど、そういうことだったか。\n俺を頼らず、自身の力で影ノ街に小さな商会を興したのは…）",
  ui_story_5071_50710402_44_dialog_content = "（実力を低く見積もるなということか。こうして俺を助け、\n対等の協力関係を築くチャンスをうかがっていたわけだな？）",
  ui_story_5071_50710402_45_dialog_content = "ハハハ！いいだろう、ではシェオルの世話になるとしようか。\n商品の納入はお前に頼む。",
  ui_story_5071_50710402_46_dialog_content = "これで借りができた。何でも願いを言え。\nかならず応えてやろう。",
  ui_story_5071_50710402_47_dialog_content = "私は、自分の願いをかなえられるのは\n自分しかいないと思っています。",
  ui_story_5071_50710402_48_dialog_content = "構わん。願いは後々に取っておけ。\n必要な時が来たら、いつでも俺を訪ねてこい。",
  ui_story_5071_50710402_49_dialog_content = "ご好意に感謝いたします。\n一生その「願い」をかなえにお訪ねすることがないよう願っています。",
  ui_story_5071_50710402_50_dialog_content = "俺でさえ見間違えそうだ。\nお前は母親そっくりだ。顔だけではない…",
  ui_story_5071_50710402_51_dialog_content = "…母は…どんな人だったんでしょうか？",
  ui_story_5071_50710402_52_dialog_content = "お前の母親は商会のトップを務めていた。戦いの能力にも優れ、\nお前と同様、経営の才能にも恵まれていた。俺は尊敬していたんだよ。",
  ui_story_5071_50710402_53_dialog_content = "残念です。お話を聞いても、私には母の姿を思い描くことができません。\n面影さえ浮かんでこないんです…",
  ui_story_5071_50710402_54_dialog_content = "シャドウマスター様、分かりました！",
  ui_story_5071_50710402_55_dialog_content = "申し訳ございません。私どもが事前にしっかり調べていなかったばかりに…\nおっしゃる通り、フォックス商会は最初から商品を納入するつもりなどなかったんです！",
  ui_story_5071_50710402_56_dialog_content = "ただ残念ですが、手付金はおそらく戻らないでしょう…\nフォックス商会の会長はすでに白夜城に捕らえられてしまいました。",
  ui_story_5071_50710402_57_dialog_content = "他の者たちが緊急で商品を提供してくれる商会を見つけたのですが、\n今すぐ契約しますか？",
  ui_story_5071_50710402_58_dialog_content = "その必要はない。俺の方でよりふさわしい取引相手を見つけたからな。\nお前たちは連絡を待っていればいい。",
  ui_story_5071_50710402_59_dialog_content = "了解です！",
  ui_story_5071_50710402_60_dialog_content = "この案件は部下の方たちが担当していたんですね。でも…\nあなたはとうにフォックス商会が怪しいと分かっていたんですか？",
  ui_story_5071_50710402_61_dialog_content = "過ぎたことにこだわっても意味はない。\n今はこれから先の協力関係を祝うべきではないのか？",
  ui_story_5071_50710402_62_dialog_content = "部下の方がすでに他の商会を見つけたんですよね…？\nなぜ私を選ぶのですか？それは母のため――",
  ui_story_5071_50710402_63_dialog_content = "俺が選んだのはお前だ、シェオル。お前はいつも踏ん反りかえっている\n大商会の会長どもより、ずっと商売に長けている。",
  ui_story_5071_50710402_64_dialog_content = "お前のような才女と取引できて、うれしく思っているのさ。",
  ui_story_5071_50710402_65_dialog_content = "では、私たちの協力を祝しましょう。",
  ui_story_5071_50710402_66_dialog_content = "お前の商会は何というのだ？",
  ui_story_5071_50710402_67_dialog_content = "浮遊商会です。",
  ui_story_5071_50710402_68_dialog_content = "…どうやらお前も、あの空に浮かぶ島に憧れを抱いているようだな。",
  ui_story_5071_50710402_69_dialog_content = "白夜城のことですか？確かにあの島は魅力的です。\nでも、私が憧れているのは自由に空を移動する島です。",
  ui_story_5071_50710402_70_dialog_content = "自由に交易し、自由気ままに空を飛ぶ…あら？\n私の夢ときたら、何だか現実的じゃありませんね。",
  ui_story_5071_50710402_71_dialog_content = "いや、俺が言いたいのは――",
  ui_story_5071_50710402_72_dialog_content = "これから、よろしく。",
  ui_story_5071_50710402_73_dialog_content = "（シェオルさんがこんなふうに感情を表すのはめずらしいな。\nうっかり記憶の一部が見えちゃった…）",
  ui_story_5071_50710402_74_dialog_content = "PlayerName、なぜまだぼうっと突っ立っているの？",
  ui_story_5071_50710402_75_dialog_content = "それとも…",
  ui_story_5071_50710402_76_dialog_content = "私の過去に急に興味が湧いたのかしら？",
  ui_story_5071_50710402_77_dialog_content = "ええと、その…",
  ui_story_5071_50710402_78_dialog_content = "どうりでお兄ちゃんが何かおかしいと感じたわけだね。\nボクもシェオルさんがこんなふうに心から喜んでるところ、初めて見たよ。",
  ui_story_5071_50710402_79_dialog_content = "バージル、そんなにイヴォンさんの作品が好きなら…",
  ui_story_5071_50710402_80_dialog_content = "出版社に投資して、イヴォンさんにうちの専属作家になってもらう？",
  ui_story_5071_50710402_81_dialog_content = "え？い、いいの？",
  ui_story_5071_50710402_82_dialog_content = "条件はあなたがまず骨董に関する本を出版して、\nその出版社を支えることよ。どう？",
  ui_story_5071_50710402_83_dialog_content = "ボ、ボク…ずっとがんばってるよ…",
  ui_story_5071_50710402_84_dialog_content = "え？バージルって…",
  ui_story_5071_50710402_85_dialog_content = "フフ、子どもだからって見くびっちゃダメよ。\nバージルは正真正銘、骨董の専門家。何でも鑑定できるんだから。",
  ui_story_5071_50710402_86_dialog_content = "そ、それほどじゃないよ…",
  ui_story_5071_50710402_87_dialog_content = "だったらちょうどいいね！さっき途中で原稿を拾ったんだ。\n誰のものだか分かる？",
  ui_story_5071_50710402_88_dialog_content = "この原稿用紙は、今の時代よく使われるものだよ――",
  ui_story_5071_50710402_89_dialog_content = "え？待って！これは…",
  ui_story_5071_50710501_1_dialog_content = "本当にイヴォンさんの手書き原稿なの？",
  ui_story_5071_50710501_2_dialog_content = "うん。しかもボクの知ってるかぎり、\nこれはまだ出版されてない最新作の原稿だよ！",
  ui_story_5071_50710501_3_dialog_content = "でも、この原稿用紙はすでに年数が経ってるよね。\nどうしてまだ出版されてないんだろう？",
  ui_story_5071_50710501_4_dialog_content = "作家たちの作品っていうのは、時々いろんな理由ですぐには出版できないんだ。\nしかも見て。一番下の数枚はまだ新しい。",
  ui_story_5071_50710501_5_dialog_content = "もしかしたら最近また昔の作品の続きを書き始めたのかも。\nうわああ、読みたいなぁ…",
  ui_story_5071_50710501_6_dialog_content = "バージル、まずは原稿を持ち主に返した方がいいんじゃない？",
  ui_story_5071_50710501_7_dialog_content = "わああ…最初の一文を読んだだけで、感動しちゃった！\n前にイヴォンさんの作品を読んだ時、ボクの背はまだ龍州の椅子の高さにも届かなかったんだ。",
  ui_story_5071_50710501_8_dialog_content = "そんなに感動的な作品なの？どんな内容なんだろう…？",
  ui_story_5071_50710501_9_dialog_content = "青いレンガを敷き詰めた大通りを城外へと進み、白夜城の『止まり木』の入口の前まで来ると、\n空き地に白く輝く石の山が肉眼でも見えた。",
  ui_story_5071_50710501_10_dialog_content = "幼い子どもたちはその由来も知らずに、よく石の山の中でかくれんぼをしていた。\nそんな時はいつでも、お節介な大人が現れて、子どもたちをおどかしたものだ。",
  ui_story_5071_50710501_11_dialog_content = "「ガキどもよくそんな所で遊べるな。昔そこが何だったのか知ってるのか？」",
  ui_story_5071_50710501_12_dialog_content = "子どもたちは胸を張って見せ、何も恐れぬ様子で答える。\n「ヘカトン・レイクでしょ？」",
  ui_story_5071_50710501_13_dialog_content = "「ここはな、街でヘカトン・レイクだとか呼ばれてる闘技場とは違うんだ。\nここで何人死んだと思ってんだ？」",
  ui_story_5071_50710501_14_dialog_content = "子どもたちが急に静かになると、お節介な大人はますます興に乗って言う。\n「100人のうち、生きて出てきたのはたった1人だけだったんだぞ！」",
  ui_story_5071_50710501_15_dialog_content = "ウソではない。ヘカトン・レイクはそもそも\n貴族が人の命をもてあそび、楽しむ所だった。",
  ui_story_5071_50710501_16_dialog_content = "さまざまな犯罪者たちが動物のように重く頑丈な鎖をかけられ、\n「ジャラジャラ」と音を立てては放り込まれ、互いに殺し合う。",
  ui_story_5071_50710501_17_dialog_content = "もちろん中にはただ腹を満たすために、あるいは貴族からの褒美を目当てに、\n命も顧みず、自らヘカトン・レイクへ入る者もいた。",
  ui_story_5071_50710501_18_dialog_content = "しかし、時には騙され、送りこまれた者も…",
  ui_story_5071_50710501_19_dialog_content = "影ノ街の護衛官が闇組織と結託していたことを\n白夜城の裁判官が知れば…",
  ui_story_5071_50710501_20_dialog_content = "きっと影ノ街のために、カネのことしか頭にない、\n他人の命を顧みない無能なやつらを片付けてくれる！",
  ui_story_5071_50710501_21_dialog_content = "それにしても…裁判官が本当にこんな所にいるのか？",
  ui_story_5071_50710501_22_dialog_content = "や、やめてくれ――",
  ui_story_5071_50710501_23_dialog_content = "止まれ！！",
  ui_story_5071_50710501_24_dialog_content = "どいてくれ、通してくれ！",
  ui_story_5071_50710501_25_dialog_content = "衛兵に追われているということは、お前は犯罪者だろう？",
  ui_story_5071_50710501_26_dialog_content = "ぼ、僕は犯罪者じゃない。その格好は…\n影ノ街の人だね？お願いだ、助けてくれ！",
  ui_story_5071_50710501_27_dialog_content = "僕はただ白夜城の法廷に、貴族どもが影ノ街で働いている悪事を訴えに来たんだ。\nそれなのに、逆に衛兵に殴られたんだよ。",
  ui_story_5071_50710501_28_dialog_content = "牢に入れられただけならまだしも、やつらは僕を\nヘカトン・レイクに送り込もうと…僕を殺す気なんだ…",
  ui_story_5071_50710501_29_dialog_content = "俺より先に訴えたやつがいたのか！だが…法廷は信用ならないのか？\nそれとも、白夜城か…",
  ui_story_5071_50710501_30_dialog_content = "逃がすか！",
  ui_story_5071_50710501_31_dialog_content = "囲まれた！？どうやら、もう…詰みみたいだね。",
  ui_story_5071_50710501_32_dialog_content = "あきらめるのはまだ早い。",
  ui_story_5071_50710501_33_dialog_content = "おい、お前！どけ！",
  ui_story_5071_50710501_34_dialog_content = "この男は明らかに戦い方さえ分かっちゃいない。\nこいつがいったい何の罪を犯したっていうんだ？どこへ連れて行く？",
  ui_story_5071_50710501_35_dialog_content = "そいつでなくとも構わない。人数さえそろえばいいんだ。\nかばうくらいなら――お前が代わりに出場するか？",
  ui_story_5071_50710501_36_dialog_content = "そんな…ひどすぎる。\n僕を生かす気なんて端からなかったんだ…",
  ui_story_5071_50710501_37_dialog_content = "そうか、分かったよ。僕の人生はここまでなんだね…\nどうせ家では父さんに嫌われてるし、外では――",
  ui_story_5071_50710501_38_dialog_content = "代わりに行こう。",
  ui_story_5071_50710501_39_dialog_content = "な、何を言ってるんだ？\n見ず知らずの僕のために、死にに行くって言うのか？",
  ui_story_5071_50710501_40_dialog_content = "自分が何を言っているのか、よく分かっている。",
  ui_story_5071_50710501_41_dialog_content = "お前はきちんとした教育を受けたようだな？俺よりもずっと影ノ街の救い方を分かってるはずだ。\n約束してくれ。もし俺が出て来られなかった時には――",
  ui_story_5071_50710501_42_dialog_content = "お前が影ノ街を守ってくれ。",
  ui_story_5071_50710501_43_dialog_content = "…",
  ui_story_5071_50710501_44_dialog_content = "今日はなんと自ら声を上げ、この試合に参加した勇者がいます！",
  ui_story_5071_50710501_45_dialog_content = "今日の参加者は本当に運がいい！真っ先にその勇者を倒し、かつ生き残ったならば、\n伯爵から通常の2倍の賞金が与えられます！",
  ui_story_5071_50710501_46_dialog_content = "うおおおお――",
  ui_story_5071_50710501_47_dialog_content = "あの頭に角の生えたヤツだ！",
  ui_story_5071_50710501_48_dialog_content = "…",
  ui_story_5071_50710501_49_dialog_content = "殺せ――！",
  ui_story_5071_50710501_50_dialog_content = "ここに放り込まれた者は皆、\n理性も何もかも悪魔に捧げてしまうのか？",
  ui_story_5071_50710501_51_dialog_content = "いけ！のろまどもが！何をやっている！",
  ui_story_5071_50710501_52_dialog_content = "高みの見物を決め込んでいるあいつらに\n利用されているというのに…",
  ui_story_5071_50710501_53_dialog_content = "そいつを抑えろ！賞金は山分けだ！",
  ui_story_5071_50710501_54_dialog_content = "だが、生き残れるのは1人だけだろ？",
  ui_story_5071_50710501_55_dialog_content = "それは角の生えたヤツじゃないことだけは確かだ！",
  ui_story_5071_50710501_56_dialog_content = "だったら突っ立ってないで、かかってきたらどうだ？",
  ui_story_5071_50710502_1_dialog_content = "1人殴り飛ばされるたび、観客席から歓声が起こる。\nその歓声は数を増すごとに高まっていく。",
  ui_story_5071_50710502_2_dialog_content = "ある女性客はスカートのすそを上げ、最後列の席に隠れた。\nまるで次の瞬間、青い炎に包まれた拳が自分に向けられるのを恐れるかのように。",
  ui_story_5071_50710502_3_dialog_content = "野獣のようにたくましく、悪魔のように残忍な青年は最後の1人を倒し終えると、\nようやくその手を止め、観客もようやく息をついた。",
  ui_story_5071_50710502_4_dialog_content = "ヤツが勝ったぞ！全員で取り囲んで攻撃したというのに、\n本当に勝ったのか！？",
  ui_story_5071_50710502_5_dialog_content = "奴も重傷だ。他の奴らはみな武器を隠し持っていた。\nだいぶ斬りつけられているぞ…",
  ui_story_5071_50710502_6_dialog_content = "数えてみたが、1000回以上斬りつけられている！",
  ui_story_5071_50710502_7_dialog_content = "1000回以上だと！？",
  ui_story_5071_50710502_8_dialog_content = "…",
  ui_story_5071_50710502_9_dialog_content = "もう帰っていいだろう？",
  ui_story_5071_50710502_10_dialog_content = "お前がかばったヤツは帰っていい。\nだが、お前は――",
  ui_story_5071_50710502_11_dialog_content = "ねえ、あなたたち…",
  ui_story_5071_50710502_12_dialog_content = "聞こえてる？",
  ui_story_5071_50710502_13_dialog_content = "うひゃあ！？な、何…？",
  ui_story_5071_50710502_14_dialog_content = "2人とも夢中になっちゃって、私だけ置いてきぼりじゃない。",
  ui_story_5071_50710502_15_dialog_content = "私も仲間に入れてって言いたいところだけど、\nやらなきゃいけないことがあるの。",
  ui_story_5071_50710502_16_dialog_content = "いずれにせよ、その原稿は急いでイヴォンさんに返した方がいいわ。",
  ui_story_5071_50710502_17_dialog_content = "それからバージル。オークションの仕事を忘れちゃダメよ。",
  ui_story_5071_50710502_18_dialog_content = "わ、わかった！",
  ui_story_5071_50710502_19_dialog_content = "イヴォンさんは今、イスタバンさんと話してるんだよね？\nだったらイスタバンさんの所へ行こう。",
  ui_story_5071_50710502_20_dialog_content = "でも、このお話…ちょうどいいところだったよ…",
  ui_story_5071_50710502_21_dialog_content = "も、もうちょっとだけ…ダメかな？",
  ui_story_5071_50710502_22_dialog_content = "コホン。じゃ、じゃあ、もう少しだけ…読もうか？",
  ui_story_5071_50710502_23_dialog_content = "うん！もうちょっとだけ！",
  ui_story_5071_50710601_1_dialog_content = "<color=#e8d9bb>浮遊商会艇・豪華客室</color>",
  ui_story_5071_50710601_2_dialog_content = "シャドウマスター、会談の機会を与えてくださり感謝します。\n大陸商会を代表して、心からの敬意を表します。",
  ui_story_5071_50710601_3_dialog_content = "大陸商会の謎の会長ハンス女史がまさかお前だったとはな。\n確か姓はハンスではなかったはずだが？",
  ui_story_5071_50710601_4_dialog_content = "お互い様でしょう？",
  ui_story_5071_50710601_5_dialog_content = "…変わったな。",
  ui_story_5071_50710601_6_dialog_content = "そうでしょうか？ああ…足のことを言っているのですか？",
  ui_story_5071_50710601_7_dialog_content = "当時影ノ街が暗潮に包囲されそうになった時、私は大金をはたいて何とか逃げ出しましたが…\n結局、途中で暗鬼に出くわし…",
  ui_story_5071_50710601_8_dialog_content = "大したことではありませんよ。あんなことでもなければ、\n機械義肢がこれほど便利なものとは知らずにいたわけですから。",
  ui_story_5071_50710601_9_dialog_content = "ハハ、本当に変わったな。\n昔よりも強く、楽観的になったようだ。",
  ui_story_5071_50710601_10_dialog_content = "仕方ないでしょう？人は経験した分だけ成長するものです。",
  ui_story_5071_50710601_11_dialog_content = "お前の商会もなかなかじゃないか。\n総合商会の規定も顧みず、危険な投資をしているようだな。",
  ui_story_5071_50710601_12_dialog_content = "ふふ。やはり、影はいつも見ているようですね。",
  ui_story_5071_50710601_13_dialog_content = "それにしても、あなたという人は友人にも容赦ないのですね。\nせっかく会いに来たというのに、いくらも言葉を交わさぬうちに面子を潰すとは。",
  ui_story_5071_50710601_14_dialog_content = "古い友人だからこそ、うまくやってほしいだけさ。",
  ui_story_5071_50710601_15_dialog_content = "ただ…<color=#FFB400>あなたの影ノ街</color>は自由で、包容性のある街だったのでは？\nそれなのに、理解できませんね。",
  ui_story_5071_50710601_16_dialog_content = "大型カジノは影ノ街にさらなる利益をもたらす――さらには、\n白夜城に立派な「税」を納められるというのに、なぜ拒むのです？",
  ui_story_5071_50710601_17_dialog_content = "お前は金になど興味はなかったはずだ。\n昔は芸術や文学を好み、いつでも絵筆を執っていた――",
  ui_story_5071_50710601_18_dialog_content = "変わったのは私だけではないでしょう？",
  ui_story_5071_50710601_19_dialog_content = "あの時の貧しい少年が今や一変してケーンを手にし、\n名実ともに<color=#FFB400>イスタバン</color>となったのですから。",
  ui_story_5071_50710601_20_dialog_content = "…",
  ui_story_5071_50710601_21_dialog_content = "その通りだ。この世に永久に変わらんものなどない。\n影ノ街も変わっている。",
  ui_story_5071_50710601_22_dialog_content = "影ノ街はお前のものでもなければ、俺のものでもない。",
  ui_story_5071_50710601_23_dialog_content = "影ノ街では自由に商いができる。だが闇産業には決して手を出してはならない――\nそれは<color=#FFB400>バロン</color>の夢でもあった。",
  ui_story_5071_50710601_24_dialog_content = "クッ…",
  ui_story_5071_50710601_25_dialog_content = "なんでこうなるの？こんなの、主人公があまりにもかわいそうだよ…",
  ui_story_5071_50710601_26_dialog_content = "白夜城の城主に謁見できたのに、\n結局貴族にはめられて、牢に入れられちゃうなんて。",
  ui_story_5071_50710601_27_dialog_content = "城主は主人公の影ノ街に対する考え方を聞く気なんてなかったんだね。\n影ノ街は城主にとって闘犬も同じ…自分の役に立たないと分かって、興味が失せたんだ。",
  ui_story_5071_50710601_28_dialog_content = "今回の作品は今までのものよりもずっと複雑なお話だな…\nでも、やっぱり主人公のその後が気になる。",
  ui_story_5071_50710601_29_dialog_content = "もう少しだけ…読もうか？",
  ui_story_5071_50710601_30_dialog_content = "うん、もうちょっとだけ！",
  ui_story_5071_50710601_31_dialog_content = "墓地に漂う空気は市街地よりもずっと冷たかった。\nあるいは、長い間立ちつくしていたせいなのだろうか。",
  ui_story_5071_50710601_32_dialog_content = "家を離れる時、両親には「行ってきます」と一言声を掛けただけだった。\nまたたく間に数年が過ぎ、今や「ただいま」と声を掛ける相手もいない。",
  ui_story_5071_50710601_33_dialog_content = "背後から足音が近づいてくる。\n彼は振り返ることなく、ただ冷やかに「目的を言え」と言った。",
  ui_story_5071_50710601_34_dialog_content = "背後の者は「カイド…やっと帰ってきたんだね」と答えた。",
  ui_story_5071_50710601_35_dialog_content = "振り返ると、そこにはどこかで見たような人影があった。\n「知り合いだったか？」",
  ui_story_5071_50710601_36_dialog_content = "昔、ヘカトン・レイクで人を救ったことがあっただろう…？\nあの時の男は僕だよ。",
  ui_story_5071_50710601_37_dialog_content = "僕のせいで、君は何年も苦しい思いをしてきた。\n見て見ぬふりはできない。",
  ui_story_5071_50710601_38_dialog_content = "今の君には帰る家もないんだろう…？僕の家に来ないか？\n兄弟として暮らそう。",
  ui_story_5071_50710601_39_dialog_content = "俺はお前の名も知らない…",
  ui_story_5071_50710601_40_dialog_content = "バロンだ。僕はバロンって言うんだ。",
  ui_story_5071_50710601_41_dialog_content = "2人の青年はすぐに共通の趣味を見つけた…",
  ui_story_5071_50710601_42_dialog_content = "…ヘカトン・レイクから戻って、ずっと練習してたんだ。",
  ui_story_5071_50710601_43_dialog_content = "チェスをか？",
  ui_story_5071_50710601_44_dialog_content = "いいや、光力術だよ。僕もいつか君みたいに、\nその場にいる全員を圧倒できるようになりたくて。",
  ui_story_5071_50710601_45_dialog_content = "それをいうなら俺も、\nお前のように圧倒的なチェスの腕がほしいものだな。",
  ui_story_5071_50710601_46_dialog_content = "あはは。まさか君もチェスが好きだとは思わなかったな。\n誰に習ったんだい？",
  ui_story_5071_50710601_47_dialog_content = "父親だ…",
  ui_story_5071_50710601_48_dialog_content = "ごめん、この話題には触れるべきじゃかったね…\nこれからは、僕の父さんが君の父さんだ！",
  ui_story_5071_50710601_49_dialog_content = "父さんは君をすごく気に入ってるから、養子にしてもらえるように頼もう！\nそうすれば、僕らは本当の兄弟になれるよ！",
  ui_story_5071_50710601_50_dialog_content = "…",
  ui_story_5071_50710601_51_dialog_content = "お願いだから、断らないでくれ。\nあの時、僕は君が死の闘技場へ行くのを止められなかった…",
  ui_story_5071_50710601_52_dialog_content = "俺はただ、こうして戻ってきた後も影ノ街が以前のまま、\n何も変わらないんじゃないかと心配してるだけだ。",
  ui_story_5071_50710601_53_dialog_content = "…僕も考えてたんだ。\n白夜城に期待してちゃ、影ノ街は永遠に変われない。",
  ui_story_5071_50710601_54_dialog_content = "自分たちの力で、暗闇に隠れ、\n影ノ街の髄を吸いつくそうとする害虫を排除しなきゃいけない。",
  ui_story_5071_50710601_55_dialog_content = "影ノ街って名前だからって、誰かの影でいなきゃいけないのか？\n僕らには僕らの未来があっていいはずだ！",
  ui_story_5071_50710601_56_dialog_content = "未来…そう、未来だよ。この街は自由で、まとまった…\n誰の支配も受けない街になるんだ！",
  ui_story_5071_50710601_57_dialog_content = "ああ、そうだな。俺もそう望んでいる。\nだが、過去の闇から完全に抜け出すのは、そう簡単なことじゃない…",
  ui_story_5071_50710601_58_dialog_content = "しばらくの間は、その害虫どもと共存し、\nひいてはやつらの仲間にならなきゃいけないかもしれない…",
  ui_story_5071_50710601_59_dialog_content = "いや。毒を絶つなら、徹底的に素早く絶たなきゃダメだ！\n妥協はいけないよ！",
  ui_story_5071_50710601_60_dialog_content = "ん…？",
  ui_story_5071_50710601_61_dialog_content = "どうしたんだい？",
  ui_story_5071_50710601_62_dialog_content = "ドアの向こうで聞き耳を立てているやつがいる…\n問題ないのか？",
  ui_story_5071_50710601_63_dialog_content = "あ…きっと<color=#FFB400>エヴァ</color>だよ。\n父さんの友だちのお嬢さんなんだ。友だちだ、大丈夫だよ。",
  ui_story_5071_50710601_64_dialog_content = "ただの友だちじゃないわ！",
  ui_story_5071_50710601_65_dialog_content = "カイドはバロンの行動力に感服していた。\nバロンは商会の会長である父親の支持を得ようとしたのだが…",
  ui_story_5071_50710601_66_dialog_content = "許さん！",
  ui_story_5071_50710601_67_dialog_content = "なぜですか？影ノ街のためになることです！",
  ui_story_5071_50710601_68_dialog_content = "人の生き血を吸って生きている闇組織も、\n闇組織同然の商会も…全部毒なんです！",
  ui_story_5071_50710601_69_dialog_content = "素早く動きさえすれば、必ずすべて根こそぎ排除できるはずです！",
  ui_story_5071_50710601_70_dialog_content = "それができるなら、とうの昔にやっている。\n影ノ街は混沌とした街だが、決して倒れぬ均衡を保ち続けている。",
  ui_story_5071_50710601_71_dialog_content = "何度言ったら分かるんだ？真面目すぎるのはかえって仇になる。\nこの間のことで十分思い知ったろう？",
  ui_story_5071_50710601_72_dialog_content = "あの時は運よくカイドに出会えたからよかったものの、\n次も無事だと保証できるか？",
  ui_story_5071_50710601_73_dialog_content = "お前やカイドだけじゃない。\n家族全員が巻き添えを食うんだぞ！",
  ui_story_5071_50710601_74_dialog_content = "父さん！！",
  ui_story_5071_50710601_75_dialog_content = "バロンはもとから父親とそりが合わなかった。\nしかし、今彼にはカイドという気のおけぬ話相手がいた…",
  ui_story_5071_50710601_76_dialog_content = "父さんは、僕の思い描く影ノ街の未来像にさえ\n聞く耳を持たない…",
  ui_story_5071_50710601_77_dialog_content = "俺が聞いている。",
  ui_story_5071_50710601_78_dialog_content = "コホン。商会はなぜ闇組織に犯されていると思う？\nとどのつまり、各商会が好き勝手にやってるからなんだ。",
  ui_story_5071_50710601_79_dialog_content = "すべての商会が一つにまとまるべきだ。\n共通の利益を目指す共同体を立てて――",
  ui_story_5071_50710601_80_dialog_content = "総合商会と名付けるか？",
  ui_story_5071_50710601_81_dialog_content = "そうだ、総合商会って名前がいい！全員の利益が互いに絡み合えば、\n助け合えるし、団結して敵に立ち向かうこともできる！",
  ui_story_5071_50710601_82_dialog_content = "闇組織や闇組織と結託する商会、\n悪事を働く傭兵団、それから…白夜城にも立ち向かえるんだ！",
  ui_story_5071_50710601_83_dialog_content = "影ノ街をむしばむ毒を排除すれば、\n影ノ街はきっと純粋な商業の聖地になれるはずだよ。",
  ui_story_5071_50710601_84_dialog_content = "それから…僕は自分で設立した大きな商会を引き連れて、\n遠くへ行く！",
  ui_story_5071_50710601_85_dialog_content = "どうやって？",
  ui_story_5071_50710601_86_dialog_content = "車…そうだ、天空ノ谷に行って巨像を買おう！\n巨像の中に商会を立てるんだよ！",
  ui_story_5071_50710601_87_dialog_content = "そよ風と太陽に包まれながら、商会ごと空を飛んで、\n各大陸間を自由に行き来しながら、すべての人と平等に交易するんだ！",
  ui_story_5071_50710601_88_dialog_content = "出身や貧富を問わず、すべての人を受け入れ、\n努力さえすれば、きちんと報酬を受けられる――そんな商会をつくるんだよ！",
  ui_story_5071_50710601_89_dialog_content = "…",
  ui_story_5071_50710601_90_dialog_content = "カイド、どうしたんだい？ヘンなこと言ったかな？",
  ui_story_5071_50710601_91_dialog_content = "いや、素晴らしい。素晴らしい夢だ。影から脱する方法は…\n確かに空を飛ぶことかもしれないな。",
  ui_story_5071_50710601_92_dialog_content = "その夢のためなら、俺はすべてを捧げる。",
  ui_story_5071_50710601_93_dialog_content = "私もよ！",
  ui_story_5071_50710601_94_dialog_content = "エヴァは商売が嫌いじゃないのかい？",
  ui_story_5071_50710601_95_dialog_content = "ええ…でも、絵を描けるわ。\n素敵な巨像をデザインしてあげる！",
  ui_story_5071_50710601_96_dialog_content = "あはは。巨像はデザインする必要ないんだよ。",
  ui_story_5071_50710601_97_dialog_content = "だが、夢を思い描き、語り合う楽しい時間は、\nそう長くは続かなかった…",
  ui_story_5071_50710601_98_dialog_content = "何かおもしろくないことでもあったか？",
  ui_story_5071_50710601_99_dialog_content = "父さんが僕を取引相手に会わせるって言うんだ。",
  ui_story_5071_50710601_100_dialog_content = "よかったじゃないか。ようやく商売の仕方を教える気になってくれたんだな。\n俺たちの夢も実現に近づくぞ。",
  ui_story_5071_50710601_101_dialog_content = "いや、違うんだよ…父さんが僕に会わせようとしてるのは…",
  ui_story_5071_50710601_102_dialog_content = "毒薬の販売を手掛ける商人なんだ。\nそれが取引相手ってことは、つまり――",
  ui_story_5071_50710601_103_dialog_content = "うちも汚い商売に手を染めてたってことだ。\nどうりで僕を止めようとしたわけだね。",
  ui_story_5071_50710601_104_dialog_content = "この先どんな顔をして接すればいいんだ…\nこれから、僕はどうしたら…",
  ui_story_5071_50710601_X104_dialog_content = "夢の実現のために、父親のもっているものも利用すればいいだろう？",
  ui_story_5071_50710601_105_dialog_content = "その資源を利用して…いや、冗談だろう？カイド…",
  ui_story_5071_50710601_106_dialog_content = "…君がどう思うか分からないけど――",
  ui_story_5071_50710601_107_dialog_content = "どんなことがあっても、君は僕の味方だよね？",
  ui_story_5071_50710601_108_dialog_content = "…",
  ui_story_5071_50710601_109_dialog_content = "チェスを続けよう。今度はお前が白、俺が黒だ。",
  ui_story_5071_50710601_110_dialog_content = "バロンは知らなかった。自分よりも先にカイドが動いたことを。",
  ui_story_5071_50710601_111_dialog_content = "毒薬をすべて燃やせ！",
  ui_story_5071_50710601_112_dialog_content = "了解です！",
  ui_story_5071_50710601_113_dialog_content = "うわっ――",
  ui_story_5071_50710601_114_dialog_content = "動くな！",
  ui_story_5071_50710601_115_dialog_content = "俺がお前に何をしたっていうんだ？\nどうして俺を襲う？",
  ui_story_5071_50710601_116_dialog_content = "この毒薬を売れば、どれだけの人間や家族を\n害することになるのか分かっているのか？",
  ui_story_5071_50710601_117_dialog_content = "フン。白夜城の法廷だって放任してるってのに――",
  ui_story_5071_50710601_118_dialog_content = "…お前は何者だ？",
  ui_story_5071_50710601_119_dialog_content = "俺か？俺はただ…この街をうろつく影にすぎんさ。",
  ui_story_5071_50710601_120_dialog_content = "その後しばらくしないうちに、バロンの父親はカイドを養子にすると申し出た。\nだが、その儀式の席にバロンの姿はなかった。",
  ui_story_5071_50710601_121_dialog_content = "それでもカイドは案ずる気持ちを表に出すことなく、堂々と胸を張った。\n黒々とした2本の角は鋭い光を放ち、その口からは高らかな誓いの言葉が響く――",
  ui_story_5071_50710601_122_dialog_content = "「…決して家族同士で争うことなく」",
  ui_story_5071_50710601_123_dialog_content = "「決して家族の利益を損ねないと誓う…」",
  ui_story_5071_50710701_1_dialog_content = "「バロン」の夢ですって？\nよくもそんなことを口にできたものですね！",
  ui_story_5071_50710701_2_dialog_content = "あなたがすべてを灰にしたというのに――",
  ui_story_5071_50710701_3_dialog_content = "すまなかった。ハンス…",
  ui_story_5071_50710701_4_dialog_content = "だが、忠告はさせてもらう…お前の選んだ取引相手のことだ。",
  ui_story_5071_50710701_5_dialog_content = "商売に関しては、俺も素人だ。",
  ui_story_5071_50710701_6_dialog_content = "だが、影ノ街で合法に合理的に稼ぐ気持ちがあるのなら、\nシェオルに相談するがいい。",
  ui_story_5071_50710701_7_dialog_content = "約束しよう。俺にできることなら、手助けは惜しまない――",
  ui_story_5071_50710701_8_dialog_content = "あなたの「約束」など必要ありません。\nしらじらしい真似はよしてください、シャドウマスター。",
  ui_story_5071_50710701_9_dialog_content = "どうやら、深い誤解があるようだが――",
  ui_story_5071_50710701_10_dialog_content = "また日を改めて、昔話をしたいものだ。",
  ui_story_5071_50710701_11_dialog_content = "シャドウマスター、次のお客様との会談のお時間です…",
  ui_story_5071_50710701_12_dialog_content = "分かった。",
  ui_story_5071_50710701_13_dialog_content = "ハンス、今日はお前と再会できてよかった。",
  ui_story_5071_50710701_14_dialog_content = "影の中の存在と接触する時には気を付けるんだ。\n余計な面倒を起こすと厄介だ。",
  ui_story_5071_50710701_15_dialog_content = "ふふ。ご忠告に感謝します、シャドウマスター。\nですが私は、自分が何をしているのかよく分かっています。",
  ui_story_5071_50710701_16_dialog_content = "どこかの誰かのように、古い友人の「夢」を覚えてるなどと\nデマカセは言いませんから。",
  ui_story_5071_50710701_17_dialog_content = "ただ、考えたことはありますか…？",
  ui_story_5071_50710701_18_dialog_content = "その誰かは本当に友人の夢のために、\n何かしたのでしょうか？",
  ui_story_5071_50710701_19_dialog_content = "…",
  ui_story_5071_50710701_20_dialog_content = "おかしいですね…原稿をどこへやったのかしら…",
  ui_story_5071_50710701_21_dialog_content = "まさか、部屋に忘れてきたのかしら！？",
  ui_story_5071_50710701_22_dialog_content = "イヴォンさん、やっと順番が回ってきたよ！",
  ui_story_5071_50710701_23_dialog_content = "ハンスさん、どうぞ。",
  ui_story_5071_50710701_24_dialog_content = "あ…すぐに参ります…あら？",
  ui_story_5071_50710701_25_dialog_content = "あなた…まだお若いというのに、\n瞳に辛酸の影がちらついていますね。",
  ui_story_5071_50710701_26_dialog_content = "その足は…あら、申し訳ありません。また職業病が出てしまいました。\nお気に障ったのなら申し訳ありません。",
  ui_story_5071_50710701_27_dialog_content = "いいえ、とんでもありません。",
  ui_story_5071_50710701_28_dialog_content = "物語の香りがしたもので、つい惹きつけられてしまいました。",
  ui_story_5071_50710701_29_dialog_content = "しかも…百合の花の香がします――",
  ui_story_5071_50710701_30_dialog_content = "古い友人を思い出しました。\nその方も魅惑的な百合の花の香りのする女性でした。",
  ui_story_5071_50710701_31_dialog_content = "ふふ。そのように言っていただけてうれしいです。\n赤水銀の夫人は私のあこがれなのです。",
  ui_story_5071_50710701_32_dialog_content = "あなたのお書きになった赤水銀の夫人が大好きなのです。\n神秘的で強く、何事にも縛られない――",
  ui_story_5071_50710701_33_dialog_content = "彼女の沈黙の見守りがあったからこそ、私も百合の花が好きになったのです。",
  ui_story_5071_50710701_34_dialog_content = "消えることのない思い出、偉大な愛と心からの祝福――\nそれが百合の花言葉でしたよね？",
  ui_story_5071_50710701_35_dialog_content = "ただ、続編はどうしても好きになれません。\n彼女にはもっと素晴らしい結末があっていいはずです。",
  ui_story_5071_50710701_36_dialog_content = "…以前、お会いしたことがありましたか？",
  ui_story_5071_50710701_37_dialog_content = "いいえ、ないと思います。",
  ui_story_5071_50710701_38_dialog_content = "イヴォンさん――",
  ui_story_5071_50710701_39_dialog_content = "あら、どなたかしら？",
  ui_story_5071_50710701_40_dialog_content = "イヴォンさん、恐縮ですが、シャドウマスターがお待ちです。",
  ui_story_5071_50710701_41_dialog_content = "あら、申し訳ございません。今参ります。",
  ui_story_5071_50710701_42_dialog_content = "…一歩遅かったね。原稿を返しそびれちゃった。",
  ui_story_5071_50710701_43_dialog_content = "門番のワンコだよ！",
  ui_story_5071_50710701_44_dialog_content = "盗み聞きはダメだよ！",
  ui_story_5071_50710701_45_dialog_content = "イヴォンさんに原稿を返してもらえるかな？",
  ui_story_5071_50710701_46_dialog_content = "ワンコはシャドウマスターの邪魔しないの！",
  ui_story_5071_50710701_47_dialog_content = "石頭だね…",
  ui_story_5071_50710701_48_dialog_content = "仕方ない。入口で待ってよう。",
  ui_story_5071_50710701_49_dialog_content = "お兄ちゃん、だったら…",
  ui_story_5071_50710701_X49_dialog_content = "続きをもう少し読んでみようか？",
  ui_story_5071_50710701_50_dialog_content = "…",
  ui_story_5071_50710701_51_dialog_content = "男たちの対局はきな臭さを漂わせ、激しい攻防は血なまぐささえ感じさせる。",
  ui_story_5071_50710701_52_dialog_content = "バロンは自信満々にコマを進める――「チェックメイト」。\n勝負は決まった。",
  ui_story_5071_50710701_53_dialog_content = "「また君の負けだよ」――あえて一言添えるバロンをよそに、\n向かい側のカイドは黙々とコマを片付けていた。",
  ui_story_5071_50710701_54_dialog_content = "カイドが持っていた百合の花に気づいたバロンはちょうどいい機会だとカイドに訪ねる。\n「君の影の帝国はまた人を吸収したそうだね」。",
  ui_story_5071_50710701_55_dialog_content = "メリッサ夫人が亡くなって、その部下たちが行き場を失っていたからね。\nうちで引き取ったんだ。",
  ui_story_5071_50710701_56_dialog_content = "その話は初めて聞いたな。",
  ui_story_5071_50710701_57_dialog_content = "お前は興味ないだろうと思ってな。",
  ui_story_5071_50710701_58_dialog_content = "角の生えた青年はチェスを並べ直し、\nバロンは顔に浮かんだ寂しさを隠した。",
  ui_story_5071_50710701_59_dialog_content = "2人は息の合った様子でコマを取る。\n和やかな空気が流れている。",
  ui_story_5071_50710701_60_dialog_content = "近況をまだ報告してなかったね。\n家を出てだいぶ経つけど、ようやく成果が見えてきたんだ。",
  ui_story_5071_50710701_61_dialog_content = "周辺に散在していた小さな勢力をまとめたんだ。\n貧民たちも僕らを支持してくれている。この調子なら大商会になる日も遠くないよ。",
  ui_story_5071_50710701_62_dialog_content = "それはおめでとう。",
  ui_story_5071_50710701_63_dialog_content = "…父さんはどうしてる？",
  ui_story_5071_50710701_64_dialog_content = "悪くない…ただ、お前に会いたがっている。",
  ui_story_5071_50710701_65_dialog_content = "あはは。君に父さんのことを訪ねるなんてヘンな感じだな。\n君の方がよっぽどイスタバンの息子みたいだ。",
  ui_story_5071_50710701_66_dialog_content = "…",
  ui_story_5071_50710701_67_dialog_content = "僕もようやく分かってきたんだ。自分で道を切り開くのは本当に大変だ…\nカイド、僕はやはり父さんから「ケーン」を受け継ぎたい。",
  ui_story_5071_50710701_68_dialog_content = "あのケーンは我が家に代々伝わる主の印だ。\nケーンがあれば、一族のもつ資源を思うままに動かせる。",
  ui_story_5071_50710701_69_dialog_content = "そうすれば、各勢力を統合して、影ノ街で頭を張る者たちを全員集結させ…\nすべて消すことができるんだ。",
  ui_story_5071_50710701_70_dialog_content = "青い髪の青年はコマを指し、穏やかな声で言った――「チェックメイト」。",
  ui_story_5071_50710701_71_dialog_content = "カイドは詰みとなった盤上のコマを見つめていた視線を上げ、\n「お前の考えは過激すぎる」と言った。",
  ui_story_5071_50710701_72_dialog_content = "影ノ街を変えるためには、弱者を守るためには、妥協できないんだよ。\n汚れは1ミリとも残すわけにはいかない。",
  ui_story_5071_50710701_73_dialog_content = "それは、他のやつらにとって不公平だ。",
  ui_story_5071_50710701_74_dialog_content = "僕が聞きたいのは約束だよ、カイド。",
  ui_story_5071_50710701_75_dialog_content = "どんなことがあっても、君は僕を裏切らない。そうだろう？\nずっと僕の味方だ。僕のやることすべてを応援してくれる。そうだよね？",
  ui_story_5071_50710701_76_dialog_content = "角の生えた青年はかすかに迷いの表情を浮かべた。その時風の音が騒がしくなったかと思うと、\n2人の沈黙の合間を縫って、クーリエが不安な知らせをもたらした。",
  ui_story_5071_50710701_77_dialog_content = "「大量の暗鬼が集結し、今影ノ街に向かって進軍している」と。",
  ui_story_5071_50710701_78_dialog_content = "白夜城でも動いているようです。影ノ街に応援を送るか話し合っているようですが――\nこの機に影ノ街を完全に併合しようと主張する者もいるようです。",
  ui_story_5071_50710701_79_dialog_content = "棋士たちがまた動き出したか…それもそうだな。\n僕らは白夜城の影だ。しがらみから逃れられるはずもない。",
  ui_story_5071_50710701_80_dialog_content = "何事にも活路はある…やつらに話し合う気があるなら、\nこちらも応じるべきだ。",
  ui_story_5071_50710701_81_dialog_content = "俺はルークとしてお前の進む道を拓き続ける。\n自信をもて、キング。",
  ui_story_5071_50710701_X81_dialog_content = "「カチッ」という音と共に、盤上に新たな戦局が生み出される――",
  ui_story_5071_50710701_X82_dialog_content = "黒のルークが、白のキングのために出陣したのだ。",
  ui_story_5071_50710701_82_dialog_content = "グフッ――ゴルディの部屋はこっちだったよな――",
  ui_story_5071_50710701_83_dialog_content = "ゴルディ～、サインしてくれよ～。",
  ui_story_5071_50710701_84_dialog_content = "門番のワンコだよ！",
  ui_story_5071_50710701_85_dialog_content = "攻撃準備！",
  ui_story_5071_50710701_86_dialog_content = "ま、待って！ここは僕に任せて…",
  ui_story_5071_50710701_87_dialog_content = "また騒ぎを起こしたら、大変だよ…",
  ui_story_5071_50710701_88_dialog_content = "誰だ～？お前～…",
  ui_story_5071_50710701_89_dialog_content = "俺はゴルディに会いにきたんだ！ゴルディを出せ！",
  ui_story_5071_50710702_1_dialog_content = "しつこい人だな…警備の仕事って本当に大変だな…",
  ui_story_5071_50710702_2_dialog_content = "人が多すぎるんだよ。そんなことより――続きを読もうよ！",
  ui_story_5071_50710702_3_dialog_content = "何年も経ち、私はついに再び筆を執り、この物語をつづることにした。",
  ui_story_5071_50710702_4_dialog_content = "これまでに書いたものは、あまりにも奇をてらい、あるいは「真相」とは程遠い…私はそう思っていた。\n加えて前作の失敗が何年もの間、筆を執る勇気を奪っていた。",
  ui_story_5071_50710702_5_dialog_content = "しかし、友人の語る過去を聞き、私は再びあふれる着想に浸った。\n「赤水銀の夫人」の虚構の続編が好評を得られなかったのならば、真実を書けばよいのだ。",
  ui_story_5071_50710702_6_dialog_content = "その結末は読者の想像するものとは異なるかもしれない。\nしかし、人々の嗚咽を誘う真相はここに記すに値する――",
  ui_story_5071_50710702_7_dialog_content = "これって『赤水銀の夫人』のモデルになった話なの？",
  ui_story_5071_50710702_8_dialog_content = "ますます楽しみになってきちゃった！！",
  ui_story_5071_50710702_9_dialog_content = "美しいメリッサの剣は鋭く、目の前の角の生えた青年を圧倒した。",
  ui_story_5071_50710702_10_dialog_content = "「投稿しなさい」。彼女は冷たく、そう言い放つ。\n「あなたが影ノ街にのさばる影であることは知っているわ」。",
  ui_story_5071_50710702_11_dialog_content = "多くの子どもたちをさらった罪は許されない！",
  ui_story_5071_50710702_12_dialog_content = "メリッサは娘を深く愛していた。\nそして、それは彼女の長年の執念を支えていた。",
  ui_story_5071_50710702_13_dialog_content = "相手は黙ったまま雨のように注がれる剣を受け続ける。\nその者にも執着する何かがあるかのように。",
  ui_story_5071_50710702_14_dialog_content = "娘をさらった相手でなくとも、彼女は卑劣な「誘拐犯」を許せなかった。",
  ui_story_5071_50710702_15_dialog_content = "刃が激しく火花を散らす中、青年は部屋の隅まで追い詰められる。\nその時、突然ざわざわと声が響いてきたのである。",
  ui_story_5071_50710702_16_dialog_content = "お父さん――",
  ui_story_5071_50710702_17_dialog_content = "気をつけて！",
  ui_story_5071_50710702_18_dialog_content = "子どもたちがあちこちで心配する声をあげ、\nあまりの驚きにメリッサの剣を振る手も自然と遅くなった。",
  ui_story_5071_50710702_19_dialog_content = "メリッサはその時悟った。情報が間違っていたのだ。\n剣を下ろした彼女の顔には失意が浮かんでいた。",
  ui_story_5071_50710702_20_dialog_content = "「娘さんを探してやろう」。\nマーキュリーの話を聞き、カイドという名の青年はそう言った。",
  ui_story_5071_50710702_21_dialog_content = "ただし、俺のやることには手を出すな。\n闇組織を潰す邪魔立てはしないでもらいたい。",
  ui_story_5071_50710702_22_dialog_content = "この街に堕落していない者などいやしないわ。\nやるだけ無駄よ。",
  ui_story_5071_50710702_23_dialog_content = "お前が守ってやれない時、\nお前の娘が無事に育つためにも必要なことだ。",
  ui_story_5071_50710702_24_dialog_content = "これって…シェオルさんのお母さんの話みたいだね。",
  ui_story_5071_50710702_25_dialog_content = "フィクションかな？それとも…とにかく先を読もうよ。",
  ui_story_5071_50710702_26_dialog_content = "カイドが最後に会った時には、\nメリッサの病はすでに手の施しようがなかった。",
  ui_story_5071_50710702_27_dialog_content = "病はかつての美しさを奪い、\n長年の苦労と悲しみに彼女は憔悴しきっていた。",
  ui_story_5071_50710702_28_dialog_content = "カイドが視界に入ると、あれほど強かったマーキュリーも、\n弱々しい表情を浮かべた。",
  ui_story_5071_50710702_29_dialog_content = "「娘を見つけてちょうだい。」",
  ui_story_5071_50710702_30_dialog_content = "それが彼女のたった一つの願いだった。\nその対価として、マーキュリーは闇産業に関わるすべての事業から手を引いていた。",
  ui_story_5071_50710702_31_dialog_content = "必ず約束を守ってくれると信じているわ。",
  ui_story_5071_50710702_32_dialog_content = "しかし、目の前のカイドは沈黙したままだった。\n背に回した手の中には、鋭い光を放つ短剣が握られている。",
  ui_story_5071_50710702_33_dialog_content = "安心しろ。必ずかなえてやる。",
  ui_story_5071_50710702_34_dialog_content = "メリッサは深く息をついた。\nすべての心残りがこの瞬間に消え去ったのだ。",
  ui_story_5071_50710702_35_dialog_content = "「そうだわ。」突然何か思い出したように彼女は言った。\n「後ろに何を隠しているの？」",
  ui_story_5071_50710702_36_dialog_content = "「何も。」カイドが一歩一歩近づき、その顔は影の中に紛れていく。\n「ただの贈り物だ。」",
  ui_story_5071_50710702_37_dialog_content = "<color=#e8d9bb>原稿はそこで突然終わっていた。インクはまだ新しく、どうやら最近書き上げたばかりのようだ</color>",
  ui_story_5071_50710702_38_dialog_content = "ええ！？そんなことって…？",
  ui_story_5071_50710702_39_dialog_content = "ええっ…",
  ui_story_5071_50710702_40_dialog_content = "そこのお子様2人、どうしたのかしら？",
  ui_story_5071_50710702_41_dialog_content = "そろそろオークションの時間よ。それからPlayerName――\nあなたも少しは見て行って。",
  ui_story_5071_50710702_42_dialog_content = "今回のオークションは今までの影ノ街のものとは違うのよ。\n透明性の高い公開オークションだから、見てみる価値はあると思うわ！",
  ui_story_5071_50710702_43_dialog_content = "シャドウマスターと協力して、ようやく実現した自由な取り引きなの。",
  ui_story_5071_50710702_44_dialog_content = "来なかったら、いい物も全部他の人に取られちゃうわ。",
  ui_story_5071_50710702_45_dialog_content = "僕のお小遣いじゃ無理ですよ…あ！それより、シェオルさん！\nこれを見てください！",
  ui_story_5071_50710702_46_dialog_content = "イヴォンさんの書きかけの作品に\nシェオルさんのお母さんの名前が…",
  ui_story_5071_50710702_47_dialog_content = "え！？見せてちょうだい…でも、イヴォンさんはずっと\n影ノ街を題材に作品を書いてきたのよ。それくらい当然じゃない？",
  ui_story_5071_50710702_48_dialog_content = "他殺だったというの…でも、文学作品はたいてい半分は虚構よ。\n作り話があったっておかしくないわ。",
  ui_story_5071_50710702_49_dialog_content = "でも、どうして実名を…",
  ui_story_5071_50710702_50_dialog_content = "そう気にすることないわ。オークションが終わった後で、\nイヴォンさんに聞けばいいだけのことでしょう？",
  ui_story_5071_50710702_51_dialog_content = "今の最優先事項はオークションよ。もうすぐ始まるわ。\n2人ともここにいてはダメよ…",
  ui_story_5071_50710702_52_dialog_content = "少なくともバージルはダメね。\n鑑定をしてもらわなきゃいけないんだから！",
  ui_story_5071_50710702_53_dialog_content = "掘り出し物が手に入るかもしれないの…",
  ui_story_5071_50710702_54_dialog_content = "ちょっと待ってください！シェオルさん！",
  ui_story_5071_50710801_1_dialog_content = "シャドウマスター、他に何も望みません。\n私はただあなたに関する伝記小説を出版させていただきたいのです。",
  ui_story_5071_50710801_2_dialog_content = "それしきのこと、わざわざ許可を取る必要はない。",
  ui_story_5071_50710801_3_dialog_content = "影ノ街は創作の自由を尊重する。",
  ui_story_5071_50710801_4_dialog_content = "はい…そのようにおっしゃっていただいて安心いたしました。\nただ、当時のことについて、少々取材させていただきたく…",
  ui_story_5071_50710801_5_dialog_content = "<color=#e8d9bb>浮遊商会艇、オークション会場</color>",
  ui_story_5071_50710801_6_dialog_content = "コホン…今回オレたちが出品するのは『R・W砂漠の一角』だ。\n巨匠ヴィンチが旅の途中で描いたって言われるモンだな。",
  ui_story_5071_50710801_7_dialog_content = "巨匠ヴィンチは著名な旅の画家だ。\n生涯数多くの作品を描き、これはそのうちでも名品の一つ。",
  ui_story_5071_50710801_8_dialog_content = "その独特の技法で、ギラつく太陽の下、\n変化に富む砂漠地形の様相をロマンチックに描き出してる。",
  ui_story_5071_50710801_9_dialog_content = "青のハイライトで砂の輪郭を描くっつう意外な手法で、\n砂漠の輝きがさながら海の波のようだ。",
  ui_story_5071_50710801_10_dialog_content = "あれ？てっきり浮遊商会が主催するものとばかり思ってました。",
  ui_story_5071_50710801_11_dialog_content = "私たちのモットーは自由で公正、透明な取り引きよ。\n商会が提供するのは場所だけ、その他のことは皆自分たちでやってもらうの。",
  ui_story_5071_50710801_12_dialog_content = "これまで影ノ街は「地下オークション」を数多く開いてきたけど、\n出品物の出処はあやしいものばかりで、価格も不合理だったでしょ。",
  ui_story_5071_50710801_13_dialog_content = "でも、このオークションは違うわ――ここでは互いに顔を合わせながら安心して取引できるし、\n無料で鑑定までサービスしているの。",
  ui_story_5071_50710801_14_dialog_content = "あの、これは贋作だよ…\n本物として出品するのは詐欺になるよ。",
  ui_story_5071_50710801_15_dialog_content = "（バージルは専門のこととなると、まるで人が変わったみたいだ）",
  ui_story_5071_50710801_16_dialog_content = "（ざわざわ――）",
  ui_story_5071_50710801_17_dialog_content = "おい、静かにしてくれ！贋作だって言うからには、\n証拠があるんだろうな？",
  ui_story_5071_50710801_18_dialog_content = "そうだ、証拠を出せ。\nおめえみてえなガキの鼻がオレたちより利くってのか？",
  ui_story_5071_50710801_19_dialog_content = "それって…自分から白状してるみたいなものじゃないの…？",
  ui_story_5071_50710801_20_dialog_content = "ヴィンチが有名になったのは、大陸中を旅行して、\n各地の風土風情を絵に描き留めたから…",
  ui_story_5071_50710801_21_dialog_content = "だから…その土地その土地で入手した顔料で絵を描いてるんだ。",
  ui_story_5071_50710801_22_dialog_content = "この絵に使われている色は確かに荒々しく力強いけど――",
  ui_story_5071_50710801_23_dialog_content = "『R・W砂漠の一角』の砂のハイライト部分は、\nR・W砂漠の地層下部で獲れる明るい青色の顔料で描かれてるはず――",
  ui_story_5071_50710801_24_dialog_content = "でも、この絵に使われているのは宝石の粉末だ。\nR・W砂漠では、あまりにも「ゼイタク」すぎる顔料だよ。",
  ui_story_5071_50710801_25_dialog_content = "この贋作を描いた人はきっと、砂地の下層深くに\n顔料になる材料があるとは知らなかったんだろうね…",
  ui_story_5071_50710801_26_dialog_content = "それに本物の砂の部分の色はもっと浅いんだ。\n作者はきっと、より海の波に近づけたかったんだろうね。",
  ui_story_5071_50710801_27_dialog_content = "でも、この贋作は砂漠で描いたっていう感じを出そうとして、\nうっかり色を深くしちゃってる…",
  ui_story_5071_50710801_28_dialog_content = "おめえのせいだ！\nだから言ったじゃねえか、ハデな技法はバレるってよ…",
  ui_story_5071_50710801_29_dialog_content = "偉そうな口きくんじゃねーぞ！\nオレがいなきゃ、こんなデキのいいもん作れねーくせによ！",
  ui_story_5071_50710801_30_dialog_content = "こちらのお客様2人を外へお願い…\nあ、それから、絵も忘れずに持って行ってもらってちょうだい。",
  ui_story_5071_50710801_31_dialog_content = "バージル…すごいね！",
  ui_story_5071_50710801_32_dialog_content = "そうかな？ボクはただ芸術品が好きなだけなんだけど…",
  ui_story_5071_50710801_33_dialog_content = "当たり前でしょ？\nうちの可愛い従業員は間違いなくトップレベルだもの。",
  ui_story_5071_50710801_34_dialog_content = "その辺の子どもと一緒にしてもらっちゃ困るわね。",
  ui_story_5071_50710801_35_dialog_content = "うっ…",
  ui_story_5071_50710801_36_dialog_content = "ご来場の皆様、続いては私が出品いたします。",
  ui_story_5071_50710801_37_dialog_content = "こちらは匿名の依頼人の命を受け、出品させていただく油絵ですが、\nなんと作者名も同様に不明です。",
  ui_story_5071_50710801_38_dialog_content = "ですが、技法から見る限り、巨匠の作品と言ってよいでしょう。\n皆様のお目にかなえば幸いです。",
  ui_story_5071_50710801_39_dialog_content = "題名は――『夫人の死』！",
  ui_story_5071_50710801_40_dialog_content = "こちらの作品の価値はまだ確定していないので、\nスタート価格50万とさせていただきます。",
  ui_story_5071_50710801_41_dialog_content = "あの絵は…赤水銀の夫人じゃないのか？\nとなりに立ってる男…なんだか…",
  ui_story_5071_50710801_42_dialog_content = "いいえ、あれはメリッサ夫人ですね…",
  ui_story_5071_50710801_43_dialog_content = "どういうこと？殺し屋の後姿…\nシャドウマスターにそっくりじゃない…",
  ui_story_5071_50710801_44_dialog_content = "どういうこと…？あの絵は…",
  ui_story_5071_50710801_45_dialog_content = "PlayerName、代わりにあの絵を落としてもらえるかしら？",
  ui_story_5071_50710801_46_dialog_content = "誰が出品を依頼したのか分からないけど…主催者側の私には落とせないのよ。\nお願い、値段を叫ぶだけでいいの。",
  ui_story_5071_50710801_47_dialog_content = "60万だそう。",
  ui_story_5071_50710801_48_dialog_content = "100万。",
  ui_story_5071_50710801_49_dialog_content = "早く叫んで！",
  ui_story_5071_50710801_50_dialog_content = "1、120万！",
  ui_story_5071_50710801_51_dialog_content = "140万。",
  ui_story_5071_50710801_52_dialog_content = "（ざわざわ――）",
  ui_story_5071_50710801_53_dialog_content = "ええっ…",
  ui_story_5071_50710801_54_dialog_content = "（僕のお小遣いの…何年分なんだろう…？）",
  ui_story_5071_50710801_55_dialog_content = "ぼうっとしてないで！もっと高い値段をつけるのよ！\nいくらでもいいわ！！",
  ui_story_5071_50710801_56_dialog_content = "2…200万。",
  ui_story_5071_50710801_57_dialog_content = "（突然会場が静まりかえる――）",
  ui_story_5071_50710801_58_dialog_content = "200万1回。他にどなたかいらっしゃいませんか？200万2回！",
  ui_story_5071_50710801_59_dialog_content = "…200万3回！おめでとうございます。空の末裔さん、落札です！",
  ui_story_5071_50710801_60_dialog_content = "まさか無名の作品をこれ程の高額で落札とは！\n空の末裔さんの素晴らしい目利きに拍手を送りましょう。",
  ui_story_5071_50710801_61_dialog_content = "シェオルさん、さすがいい目利きをなさいますね。",
  ui_story_5071_50710801_62_dialog_content = "この絵をそこまでお気に召すとは思いませんでした。\nしかもルールを無視し、代理を立ててまで落札するとは。",
  ui_story_5071_50710801_63_dialog_content = "私たちの間には何か通じ合うものがあるのかもしれません――\nどうりでシャドウマスターが私にあなたに商売の道を学ぶように言うわけです。",
  ui_story_5071_50710801_64_dialog_content = "とんでもありません。影ノ街外のアストラ中をまたにかける\n大商会を率いているあなたこそ素晴らしい才能をお持ちでしょう？",
  ui_story_5071_50710801_65_dialog_content = "どうやらシャドウマスターともゆかりがあるようですね。\n私の方こそ色々とご教示をいただきたいものです。",
  ui_story_5071_50710801_66_dialog_content = "…あなたになら、この絵を譲っても惜しくはありません。",
  ui_story_5071_50710801_67_dialog_content = "それは、どうもありがとうございます。",
  ui_story_5071_50710801_68_dialog_content = "コホン…シェオルさん。\nあの…支払いをして、絵を受け取らないと…",
  ui_story_5071_50710801_69_dialog_content = "あら、PlayerNameったら。まるで私がだまそうとしたみたいじゃない…\n行きましょう。絵をじっくり鑑賞しなきゃね。",
  ui_story_5071_50710801_70_dialog_content = "シェオルさん、私もご一緒してもよろしいですか？",
  ui_story_5071_50710801_71_dialog_content = "もちろん構いませんよ。",
  ui_story_5071_50710801_72_dialog_content = "あれ！？くんくん…この――",
  ui_story_5071_50710801_73_dialog_content = "かすかな香りは…",
  ui_story_5071_50710801_74_dialog_content = "シェオルさん、これって…\nボクの大好きな贋作の巨匠A氏の作品だよ。",
  ui_story_5071_50710801_75_dialog_content = "いろんな絵を見て来たけど、\nオリジナル作品を見るは初めてだ！",
  ui_story_5071_50710801_76_dialog_content = "あら、そうなの？今回招いたオークション業者も、\n専門性ではあなたにかなわないみたいね。",
  ui_story_5071_50710801_77_dialog_content = "ボクちゃん、この作品の作者は分かっていないはずです。\nなぜ、あなたには分かるのですか？",
  ui_story_5071_50710801_78_dialog_content = "うーん…ボクは贋作に触れることも多いから、\n腕のいい贋作者をたくさん知ってるんだ。",
  ui_story_5071_50710801_79_dialog_content = "なかでも、A氏の技術は最高レベルなんだよ。",
  ui_story_5071_50710801_80_dialog_content = "それにA氏の贋作には特徴があって、\nわかりにくい隅っことかに小さな「A」の文字を入れるんだ。",
  ui_story_5071_50710801_81_dialog_content = "描かれた人物の髪の毛の間とか、瞳孔の中とか…\nこの作品の場合、襟もとのシワの中に書かれてるよ。",
  ui_story_5071_50710801_82_dialog_content = "…そんな規則性まで見つけたのですか？\n本当にA氏のことが好きなのですね。",
  ui_story_5071_50710801_83_dialog_content = "うん、すごく好きだよ。でも、A氏ってきっとナルシストなんだろうなぁ。\nでなきゃ、贋作の中に自分の「印」なんて残さないと思うよ。",
  ui_story_5071_50710801_84_dialog_content = "そうだな…目的を果たすまで、絶対にあきらめないような人だろうね。",
  ui_story_5071_50710801_85_dialog_content = "あら？そうですか…面白いですね。",
  ui_story_5071_50710801_86_dialog_content = "…えっ？",
  ui_story_5071_50710801_87_dialog_content = "あ、あああ…し、知らない人…",
  ui_story_5071_50710801_88_dialog_content = "今さら僕の後ろに隠れて、どうするの…",
  ui_story_5071_50710801_89_dialog_content = "怖がらないでください。\nボクちゃんの才能は素晴らしいですね。",
  ui_story_5071_50710801_90_dialog_content = "あなたの才能はまだまだ伸びるでしょう。\nどうですか？私と一緒に仕事をする気はありませんか？",
  ui_story_5071_50710801_91_dialog_content = "ごめんなさい、ハンスさん。この子は…うちの従業員なんです。",
  ui_story_5071_50710801_92_dialog_content = "あら、それは本当に残念ですね。どうやら私の好きなものはすべて、\nシェオルさんが先に手に入れてしまっているようです…",
  ui_story_5071_50710801_93_dialog_content = "そんなことはないでしょう。お詫びにこういうのはどうですか？\n私個人のコレクションの中から、作品1点を選んでいただければ、プレゼントします。",
  ui_story_5071_50710801_94_dialog_content = "その必要はありません。\n他人の愛するものを奪う趣味はありませんから――",
  ui_story_5071_50710801_95_dialog_content = "それはそうと、この絵の本当の作者が誰かご存じないのに、\nなぜ、そこまで気に入ったんですか？",
  ui_story_5071_50710801_96_dialog_content = "世に知られていない絵に高い額を付けるなんて、\nこの絵に相当動かされるものがあったわけですよね？",
  ui_story_5071_50710801_97_dialog_content = "それは…私はただ、古い友人のためにやったまでです。",
  ui_story_5071_50710801_98_dialog_content = "この絵に描かれている事件が影ノ街に広まりでもすれば、\nその人が苦労して築き上げてきた名声も大きく傷つくでしょうから。",
  ui_story_5071_50710801_99_dialog_content = "ですが、あなたが落札したなら、\n私がこれ以上手助けする必要はありません。",
  ui_story_5071_50710801_100_dialog_content = "それでは、また。",
  ui_story_5071_50710801_101_dialog_content = "ハンスさん、お待ちください。\n一つお聞きしたいことがあります。",
  ui_story_5071_50710801_102_dialog_content = "あなたは…以前からシャドウマスターをご存じなんですか？",
  ui_story_5071_50710801_103_dialog_content = "ふふ…あの男の正体を知った時期のことですか？\nそれなら、あなたの思うよりもずっと前から知っていますよ。",
  ui_story_5071_50710801_104_dialog_content = "う～ん…",
  ui_story_5071_50710801_105_dialog_content = "どうしたの？じっとハンスさんを見つめちゃって、\nまさか彼女の提案に心を動かされたのかしら？",
  ui_story_5071_50710801_106_dialog_content = "ち、ちちち、違うよ！ただ…",
  ui_story_5071_50710801_107_dialog_content = "おかしいな…バージル、偶然すぎると思わない？",
  ui_story_5071_50710801_108_dialog_content = "この絵に描かれている情景、\nさっき僕たちが読んだ手書きの原稿の内容そのものじゃ…",
  ui_story_5071_50710801_109_dialog_content = "まさか、イヴォンさんの言ってた画家の友人って、\n贋作の巨匠A氏なのかな？",
  ui_story_5071_50710801_110_dialog_content = "イヴォンさんが確か言ってたよね。\nその画家の友人のおかげで、新作を書く気になったって…",
  ui_story_5071_50710801_111_dialog_content = "そうね。何もかも偶然すぎるわ。",
  ui_story_5071_50710801_112_dialog_content = "わざわざ私たちに何かを見せようとしているみたい。",
  ui_story_5071_50710801_113_dialog_content = "でも、僕には分かりません…そんなことして、何になるんですか？",
  ui_story_5071_50710801_114_dialog_content = "色々なものが次々と目の前に現れてくる。\n目的として可能性があるのは2つだけ――",
  ui_story_5071_50710801_115_dialog_content = "「真相」を告げようとしているわけじゃないなら、\n可能性は…",
  ui_story_5071_50710801_116_dialog_content = "PlayerName、原稿の話の続きはどうなっているの？",
  ui_story_5071_50710801_117_dialog_content = "急いで続きを読んでちょうだい！",
  ui_story_5071_50710901_1_dialog_content = "金のケーンを手にした角の生えた男がヘカトン・レイクの中央に立っている。\nしかし、その彼を囲むのはかつての友人を頭とする人々――",
  ui_story_5071_50710901_2_dialog_content = "「裏切者め！！」彼らは男をそう呼んだ。\n「どうして白夜城の軍隊を影ノ街に引き込みやがった！？」",
  ui_story_5071_50710901_3_dialog_content = "角の生えた男は沈黙を守ったまま、鋭利な刃物のようなまなざしを友人の顔に注いでいる――\n青い髪の青年バロンの表情は苦痛に満ち、その目には憂いが満ちていた。",
  ui_story_5071_50710901_4_dialog_content = "しばらくして、バロンはようやく口を開いた。\n「カイド…なぜだ？なぜ父さんを殺してまで、ケーンを奪った！？」",
  ui_story_5071_50710901_5_dialog_content = "僕らの理想はどうしたんだよ！？\nなぜ白夜城の言いなりになるんだ？",
  ui_story_5071_50710901_6_dialog_content = "ヘカトン・レイク…あの時俺はお前の代わりに戦い、生き残った。\nこの程度の人数で、俺を止められると思ったか？",
  ui_story_5071_50710901_7_dialog_content = "その言葉を聞いた人々は背に悪寒が走るのを感じた。",
  ui_story_5071_50710901_8_dialog_content = "えっ…2人は親友じゃなかったの？",
  ui_story_5071_50710901_9_dialog_content = "…続きを読みましょう。",
  ui_story_5071_50710901_10_dialog_content = "「お前は弱すぎる！俺がお前の位置を奪った理由はそれだけだ！」",
  ui_story_5071_50710901_11_dialog_content = "カイドはそう叫びながら、ケーンで友人の胸を貫いた。\nその狂気にくらんだ目では、かつての友人も見分けることができない。",
  ui_story_5071_50710901_12_dialog_content = "な、なぜだ…",
  ui_story_5071_50710901_13_dialog_content = "俺は誰かの影であり続けるつもりはない。",
  ui_story_5071_50710901_14_dialog_content = "青い髪の青年は愕然として倒れた。\n周りの者たちも悲痛に打ちひしがれる。",
  ui_story_5071_50710901_15_dialog_content = "そして、怒りと悲しみの中、一斉に相手に飛び掛かった――",
  ui_story_5071_50710901_16_dialog_content = "は、早く続きを読もうよ。",
  ui_story_5071_50710901_17_dialog_content = "カイドはついに内に秘めた凶悪な炎を露わにし、\n己の障害となる影ノ街の者をすべて残酷に片づけていった。",
  ui_story_5071_50710901_18_dialog_content = "異議を唱える者をすべて排除する。\n青い炎が影ノ街の隅々にまで燃え上り、誰一人として逃れることはできなかった。",
  ui_story_5071_50710901_19_dialog_content = "こうして彼はついに覇権を手に入れたのである。",
  ui_story_5071_50710901_20_dialog_content = "理想を捨て、影ノ街を売り、白夜城に膝をついて屈したのもすべて、\n己の影ノ街に対する支配権を手に入れるため。",
  ui_story_5071_50710901_21_dialog_content = "兄弟の命とその姓を奪い、\n本来自分のものではなかった名家の流れを奪い去ったのだ。",
  ui_story_5071_50710901_22_dialog_content = "邪悪の道を究め、王としての地位を確立した時、\n男は己の過去も、昔日の友「バロン」の存在も消し去った。",
  ui_story_5071_50710901_23_dialog_content = "影の王座に登りつめた彼の、残酷でみじめな過去を知る者はもういない。",
  ui_story_5071_50710901_24_dialog_content = "人々の目に映るのは、血に染まったケーンを手に、\n闇の組織に号令する――",
  ui_story_5071_50710901_25_dialog_content = "シャドウマスター、イスタバンだけだった。",
  ui_story_5071_50710901_26_dialog_content = "な、なんだって！？",
  ui_story_5071_50710901_27_dialog_content = "主人公のカイドは…イスタバンさんだったの？",
  ui_story_5071_50710901_28_dialog_content = "こんなのあり得ないよ！\nシャドウマスターが影ノ街を売るはずないでしょ！？",
  ui_story_5071_50710901_29_dialog_content = "（イスタバンさんの奥底には危険なものが隠されてることは知ってたけど…\nこれはあまりにも…）",
  ui_story_5071_50710901_30_dialog_content = "…",
  ui_story_5071_50710901_31_dialog_content = "シェオルさん、シャドウマスターは…",
  ui_story_5071_50710901_32_dialog_content = "人は誰しも複雑なものよ。\n一方の話だけを聞いて信じてはいけないわ――",
  ui_story_5071_50710901_33_dialog_content = "<color=#e8d9bb>ボンッ――</color>",
  ui_story_5071_50710901_34_dialog_content = "どうしたの？どこかで爆発でも起こったのかしら？",
  ui_story_5071_50710901_35_dialog_content = "シェオルさん！なぜか分かりませんが、\n飛空艇上で、白夜城の衛兵が突然僕たちに攻撃を仕掛けてきました！",
  ui_story_5071_50710901_36_dialog_content = "白夜城の衛兵がなぜ私を狙うのかしら？",
  ui_story_5071_50710901_37_dialog_content = "私が何をしたっていうの？",
  ui_story_5071_50710901_38_dialog_content = "やめて！何してるの！？ここはシェオルさんの飛空艇だよ！",
  ui_story_5071_50710901_39_dialog_content = "飛空艇はまだ飛行中なんだ。\n攻撃をつづければ、乗船してる全員が危ない――",
  ui_story_5071_50710901_40_dialog_content = "身の程知らずめ！思い知らせてやれ！",
  ui_story_5071_50710901_41_dialog_content = "やめてよ！ダメだよ…",
  ui_story_5071_50710901_42_dialog_content = "このままじゃ全員が危険にさらされるよ！",
  ui_story_5071_50710901_43_dialog_content = "私の飛空艇で勝手はさせないわ！！",
  ui_story_5071_50710901_X43_dialog_content = "えっ！？",
  ui_story_5071_50710901_X44_dialog_content = "まったく、身の程知らずはどっちかしら…",
  ui_story_5071_50710901_X45_dialog_content = "私の浮遊商会艇を壊そうとするなんて。",
  ui_story_5071_50710901_X46_dialog_content = "うひゃあ――",
  ui_story_5071_50710901_X47_dialog_content = "か、カッコいい、飛び蹴りだ！",
  ui_story_5071_50710901_X48_dialog_content = "これがボクのボスなの！？",
  ui_story_5071_50710901_X49_dialog_content = "シェオルさんが戦ってるの…は、初めて見たよ！",
  ui_story_5071_50710901_44_dialog_content = "と、飛び蹴り…か、カッコいい！",
  ui_story_5071_50710901_45_dialog_content = "シェオルさん…",
  ui_story_5071_50710901_46_dialog_content = "シャドウマスター、外が何やら騒がしいようです。\n何者かが紛れ込んだようですね。",
  ui_story_5071_50710901_47_dialog_content = "ほう？",
  ui_story_5071_50710901_48_dialog_content = "どうやら、せっかちな「客人」のようだな…面白い。",
  ui_story_5071_50710901_49_dialog_content = "…？",
  ui_story_5071_50711001_1_dialog_content = "何があった？",
  ui_story_5071_50711001_2_dialog_content = "シャドウマスター！お待ちしておりました――",
  ui_story_5071_50711001_3_dialog_content = "シャドウマスター、どういうことです？\nあなたの命令ではないのですか！？",
  ui_story_5071_50711001_4_dialog_content = "あなたが邪魔者を排除するように言ったのでしょう？\nそれを、どうして…",
  ui_story_5071_50711001_5_dialog_content = "！？",
  ui_story_5071_50711001_6_dialog_content = "シャドウマスターの命令だって？",
  ui_story_5071_50711001_7_dialog_content = "どうりで白夜城の衛兵なわけだな…",
  ui_story_5071_50711001_8_dialog_content = "でも、どうして俺たちを…",
  ui_story_5071_50711001_9_dialog_content = "静かにしてください。まだ事の次第は分かっていない…",
  ui_story_5071_50711001_10_dialog_content = "<color=#e8d9bb>その時突然無数の手書きの原稿が雪のように宙に舞った――</color>",
  ui_story_5071_50711001_11_dialog_content = "イヴォンさんの原稿…？",
  ui_story_5071_50711001_12_dialog_content = "なんで急にそこらじゅうに原稿が？いったい誰が…",
  ui_story_5071_50711001_13_dialog_content = "どの原稿にも同じ内容が書かれてるよ。ほら、見てごらん。",
  ui_story_5071_50711001_14_dialog_content = "長い年月が経ち、私はついにこの地へ戻ってきた。今やイスタバンは影ノ街の王となり、\nバロンの夢であった総合商会も彼が権力をふるう道具と化してしまった。",
  ui_story_5071_50711001_15_dialog_content = "私は「真相」を暴くため、筆を執るべきなのだろうか？\nそれとも過去は胸の奥にしまっておくべきなのだろうか？",
  ui_story_5071_50711001_16_dialog_content = "私はこれまで、どんな間違いが起ころうと傍観し続け、良心が痛み続けてきた。\nもうそんなことにも慣れてしまったと一度は思った。",
  ui_story_5071_50711001_17_dialog_content = "もし彼の次なる欲望を知ることがなければ、\nおそらく傍観を続けていただろう――",
  ui_story_5071_50711001_18_dialog_content = "だが、私は偶然彼の手下の口から聞いてしまった。\nすでに高みに上り詰めたイスタバンの欲望は止むことを知らないと。",
  ui_story_5071_50711001_19_dialog_content = "表向きには寛大であるが、\n裏では、中立の組織や商会に対して不満を持っていた。",
  ui_story_5071_50711001_20_dialog_content = "総合商会の統率を受けない者たちの存在は苦痛でしかない…\nそのような反逆を彼は許せないのだ。",
  ui_story_5071_50711001_21_dialog_content = "そこで、浮遊商会が商業界の大物たちを集める機会を狙い、\nそうした存在を一網打尽にし、影ノ街を完全に掌握しようと企てた。",
  ui_story_5071_50711001_22_dialog_content = "そして私も、自身の命の最後の瞬間を使って、\n忘れ去られた正義を遂行しようと決心した。",
  ui_story_5071_50711001_23_dialog_content = "――イヴォン",
  ui_story_5071_50711001_24_dialog_content = "これは本当の話なのか？",
  ui_story_5071_50711001_25_dialog_content = "イヴォンさんはさっきシャドウマスターに会いに行ったんじゃないのか？",
  ui_story_5071_50711001_26_dialog_content = "落ち着いてください！おかしいと思いませんか！？",
  ui_story_5071_50711001_27_dialog_content = "シャドウマスターがここにいるってことは、\nイヴォンさんは…",
  ui_story_5071_50711001_28_dialog_content = "こんなの、一方的な主張だよ…",
  ui_story_5071_50711001_29_dialog_content = "俺たちも消されるのか？",
  ui_story_5071_50711001_30_dialog_content = "他にもまだあるのか？原稿を見せろ！",
  ui_story_5071_50711001_31_dialog_content = "ちょ、ちょっと…と、とらないで！",
  ui_story_5071_50711001_32_dialog_content = "皆さん、そのような行動は品位を欠くと思いますよ。",
  ui_story_5071_50711001_33_dialog_content = "で、でも、この話は…",
  ui_story_5071_50711001_34_dialog_content = "本当の話なのか？ここに書かれてることは、\n本当にシャドウマスターのことなのか？",
  ui_story_5071_50711001_35_dialog_content = "はぁ…まったく他人の話を聞いていないわ…",
  ui_story_5071_50711001_36_dialog_content = "ウワサは本当だったってことか？\nいよいよ俺たちにもその刃が向けられた…",
  ui_story_5071_50711001_37_dialog_content = "おい、落ち着け。たかが小説だろう？\n本気で信じてるのか？",
  ui_story_5071_50711001_38_dialog_content = "だが、例のウワサとまったく同じ内容だぞ…",
  ui_story_5071_50711001_39_dialog_content = "ウワサだって分かってるなら、どうして信じる？",
  ui_story_5071_50711001_40_dialog_content = "でも、総合商会は実際俺たちの販路を握ってるだろ？\nヤツの欲望のために利用されてるわけじゃないって、どうして言い切れる？",
  ui_story_5071_50711001_41_dialog_content = "資金だって全部、総合商会に預けてあるんだ…\n俺たちを殺せば、その資金も全部…",
  ui_story_5071_50711001_42_dialog_content = "おバカさんの商人、悪い商人ばっかりだね！\n他人の話を全部鵜呑みにしてるよ！",
  ui_story_5071_50711001_43_dialog_content = "ボスはそんなやつじゃねえ！",
  ui_story_5071_50711001_44_dialog_content = "小説の題材にされただけだろうが！",
  ui_story_5071_50711001_45_dialog_content = "シャドウマスター、何か言うことはないのかしら？",
  ui_story_5071_50711001_46_dialog_content = "（イスタバンさん…？）",
  ui_story_5071_50711001_47_dialog_content = "（あの人たちを…観察してるのかな？）",
  ui_story_5071_50711001_48_dialog_content = "赤豹商会に…ペアレット商会の頭も話を合わせているか…",
  ui_story_5071_50711001_49_dialog_content = "（いや…違う…）",
  ui_story_5071_50711001_50_dialog_content = "そういうことか。錆鉄隼組も…",
  ui_story_5071_50711001_51_dialog_content = "（獲物を見定めてるんだ）",
  ui_story_5071_50711001_52_dialog_content = "ご報告します！シェオル会長、大変です！",
  ui_story_5071_50711001_53_dialog_content = "イヴォン女史が…",
  ui_story_5071_50711001_54_dialog_content = "<size=45>イヴォン女史が臨時応接室で死んでいるのが見つかりました！</size>",
  ui_story_5071_50711101_1_dialog_content = "発見したのは「臨時応接室」を担当していた清掃員です。",
  ui_story_5071_50711101_2_dialog_content = "現場は非常にきれいな状態で、\n被害者が犯人と争った形跡はありません。",
  ui_story_5071_50711101_3_dialog_content = "唯一の手掛かりは、イヴォン女史の倒れていたじゅうたんに\n残されていた毛髪です。",
  ui_story_5071_50711101_4_dialog_content = "ただ、通常の光霊のものではなく、猛獣類の毛のようなのですが、\nずいぶんと手入れが整っているようで…",
  ui_story_5071_50711101_5_dialog_content = "この部屋はシャドウマスターがお借りになった「臨時応接室」ですよね…？",
  ui_story_5071_50711101_6_dialog_content = "事件のあった時、どこにいらしたんですか？",
  ui_story_5071_50711101_7_dialog_content = "おい、言葉に気を付けろ！ボスを疑うつもりか？",
  ui_story_5071_50711101_8_dialog_content = "セレウコス。",
  ui_story_5071_50711101_9_dialog_content = "でもよ、ボス…",
  ui_story_5071_50711101_10_dialog_content = "推測にしても慎重を期すべきでは？\n軽々しく「犯人を決めつける」のは慎むべきことです。",
  ui_story_5071_50711101_11_dialog_content = "ついさきほどまで彼女と作品について話していた。",
  ui_story_5071_50711101_12_dialog_content = "騒ぎが起こったようだったので、様子を見に出てきた。",
  ui_story_5071_50711101_13_dialog_content = "だが、彼女はインスピレーションが下りて来たと、\nとても興奮していてな。",
  ui_story_5071_50711101_14_dialog_content = "邪魔をしないよう、俺だけで部屋を出た。",
  ui_story_5071_50711101_15_dialog_content = "その後別の誰かにやられたと言うことですか？\nそんな偶然があるでしょうか？",
  ui_story_5071_50711101_16_dialog_content = "イヴォン女史はシャドウマスターの過去を知っていたんですよね…",
  ui_story_5071_50711101_17_dialog_content = "その彼女が亡くなるなんて、おかしいでしょう…",
  ui_story_5071_50711101_18_dialog_content = "皆様、人の集まる場で、\n他の方を動揺させるような発言は慎んでくださいませ。",
  ui_story_5071_50711101_19_dialog_content = "誰だ！？好き勝手を言いやがったのは！前に出ろ！",
  ui_story_5071_50711101_20_dialog_content = "俺たちも彼女のように\n影に飲み込まれちまうのか？",
  ui_story_5071_50711101_21_dialog_content = "お客様でございますか？<color=#FFB400>言いたいこと</color>があるのは。\nでしたら、前に出て話したらいかがです？",
  ui_story_5071_50711101_22_dialog_content = "クレーケン、よせ。",
  ui_story_5071_50711101_23_dialog_content = "今日はシェオルの大切な日だ。",
  ui_story_5071_50711101_24_dialog_content = "どうして、そんな…",
  ui_story_5071_50711101_25_dialog_content = "イヴォンさん…",
  ui_story_5071_50711101_26_dialog_content = "まるで眠ってるみたいだ…\n微笑んだまま、とても穏やかな顔をしてる…",
  ui_story_5071_50711101_27_dialog_content = "外傷はないし、襲われたというわけじゃなさそうだね…",
  ui_story_5071_50711101_28_dialog_content = "もしかして…毒？",
  ui_story_5071_50711101_29_dialog_content = "<color=#e8d9bb>ガタン――</color>",
  ui_story_5071_50711101_30_dialog_content = "飛空艇が、飛空艇が揺れてるぞ――",
  ui_story_5071_50711101_31_dialog_content = "おそらく今の攻撃のせいでしょう…皆様、ご心配には及びません。",
  ui_story_5071_50711101_32_dialog_content = "この飛空艇は非常に頑丈ですから、ご安心を――",
  ui_story_5071_50711101_33_dialog_content = "<color=#e8d9bb>ボンッ――</color>",
  ui_story_5071_50711101_34_dialog_content = "…整備担当者に連絡して、状況確認を。",
  ui_story_5071_50711101_35_dialog_content = "了解です！",
  ui_story_5071_50711101_36_dialog_content = "まずは落ち着いて、少し話を聞いてくれ。",
  ui_story_5071_50711101_37_dialog_content = "今日は俺の友人にとって大切な日だ。\nそいつが夢をかなえたことを祝うために、俺は今日ここへ来た。",
  ui_story_5071_50711101_38_dialog_content = "この喜ばしい日を台無しにはさせない。\n俺にも、他の誰にもな。",
  ui_story_5071_50711101_39_dialog_content = "着陸した後、自警団に調査させよう。",
  ui_story_5071_50711101_40_dialog_content = "当然、俺も調査に協力する。\n俺が事件と関係があるいうのなら、謹んで制裁を受けよう。",
  ui_story_5071_50711101_41_dialog_content = "とはいっても、自警団は…\n総合商会が主導して組織されていますよね？",
  ui_story_5071_50711101_42_dialog_content = "しかも隊員はすべてイスタバン組出身です。",
  ui_story_5071_50711101_43_dialog_content = "総合商会の責任者も、あなたの義娘さんでしょう？",
  ui_story_5071_50711101_44_dialog_content = "見たことのない顔だが、\n俺にずいぶんと言いたいことがあるようだな。",
  ui_story_5071_50711101_45_dialog_content = "それは脅しですか？",
  ui_story_5071_50711101_46_dialog_content = "疑問に思うのも当然だと思いますが、シャドウマスター。\nあなたが大人しく裁きを受けると言うのですか？",
  ui_story_5071_50711101_47_dialog_content = "「影ノ街治安条例」なるものも公布されたばかりです。\nあなたの約束は空言と言っても過言ではないと思いますが。",
  ui_story_5071_50711101_48_dialog_content = "イヴォンさんが亡くなってしまうとは、本当に残念です…",
  ui_story_5071_50711101_49_dialog_content = "古い友人として、あなたも少しは変わったものと信じていましたが…",
  ui_story_5071_50711101_50_dialog_content = "いくら月日が経とうと、あなたも、影ノ街も、\nかつての傷を忘れられないようですね。",
  ui_story_5071_50711101_51_dialog_content = "イスタバン…いいえ、「<color=#FFB400>カイド</color>」。\n本当に私たちを見逃してくれるのですか？",
  ui_story_5071_50711101_52_dialog_content = "それとも、あの時のように…",
  ui_story_5071_50711101_53_dialog_content = "服従しない者はすべて、消し去りますか？",
  ui_story_5071_50711101_54_dialog_content = "…",
  ui_story_5071_50711101_55_dialog_content = "（ひそひそ……）",
  ui_story_5071_50711101_56_dialog_content = "聞いたことがある…シャドウマスターは昔、\n自分に反対する者を全員始末して、今の地位に…",
  ui_story_5071_50711101_57_dialog_content = "あの原稿に書かれていた「ヘカトン・レイク」のことか？",
  ui_story_5071_50711101_58_dialog_content = "「暗潮の危機」の前に影ノ街を牛耳っていたボスたちを集めて、\nシャドウマスター1人で100人を相手にしたって話だろ？",
  ui_story_5071_50711101_59_dialog_content = "ああ。その100人っていうのは、今の俺たちと同じで、\n影ノ街で名の売れたリーダーだったんだ…",
  ui_story_5071_50711101_60_dialog_content = "なんて力だ。だから今、影の主になってるってわけか。",
  ui_story_5071_50711101_61_dialog_content = "<color=#FFB400>「カイド」</color>、聞こえましたか？\n過去を完全に隠すことは出来ないようです。",
  ui_story_5071_50711101_62_dialog_content = "あなたが友人を殺し、「養父」を陥れたことを知る者は、\n私のほかにもいるのです！",
  ui_story_5071_50711101_63_dialog_content = "あの手書きのメモに書かれていたことが、\nまさか全部本当だったとは…",
  ui_story_5071_50711101_64_dialog_content = "おそらく真相はもっと残酷なんだろうな。\nきっと卑劣な汚い手を使ったから、今のシャドウマスターがあるんだ。",
  ui_story_5071_50711101_65_dialog_content = "卑劣なことぐらい、ヤツなら平気でするさ！",
  ui_story_5071_50711101_66_dialog_content = "もともと行き過ぎたやり方で、我慢ならなかったんだ。\nそれでも、やつを信じろというのか？",
  ui_story_5071_50711101_67_dialog_content = "前々からウワサがあったじゃないか。自分の友人を売って、\n白夜城に媚びたから、今の地位に就けたんだって…",
  ui_story_5071_50711101_68_dialog_content = "伝説の「悪魔の子」だな…",
  ui_story_5071_50711101_69_dialog_content = "「改革」なんて言葉を盾にして、\n俺たちの利益をないがしろにしてきたのも、目的は結局…",
  ui_story_5071_50711101_70_dialog_content = "本当に俺たちを排除する気なのか？",
  ui_story_5071_50711101_71_dialog_content = "今日はお前と再会できて、本当にうれしかったが…<color=#FFB400>「エヴァ」</color>。",
  ui_story_5071_50711101_72_dialog_content = "だが、なぜお前が「今この時」に現れたのか、\n不思議でならなかった…",
  ui_story_5071_50711101_73_dialog_content = "あいつの夢の実現を祝いに来てくれたものと、\n一瞬幻想を抱いたが…",
  ui_story_5071_50711101_74_dialog_content = "お前のやりたかったことは、これだったのだな。",
  ui_story_5071_50711101_75_dialog_content = "あなたと一緒にしないでほしいものですね。\n私こそ真に彼の夢を知る者です。",
  ui_story_5071_50711101_76_dialog_content = "シェオル、点検が終わり次第、着陸するんだ。",
  ui_story_5071_50711101_77_dialog_content = "自警団が向かっているはずだ。この先は彼らに任せよう。",
  ui_story_5071_50711101_78_dialog_content = "この下は一面の荒野ですよ。",
  ui_story_5071_50711101_79_dialog_content = "しかも、暗鬼の出没する危険区域に近い場所です。",
  ui_story_5071_50711101_80_dialog_content = "あいつ…俺たちをこのまま帰すつもりはないってことか？",
  ui_story_5071_50711101_81_dialog_content = "もしかして、改革とやらのために、全員まとめて…",
  ui_story_5071_50711101_82_dialog_content = "皆さん、ご心配なく。",
  ui_story_5071_50711101_83_dialog_content = "うちの商会の小型飛空艇がこの近くにあります。\n私を信じていただけるなら、皆さんを影ノ街までお送りしましょう。",
  ui_story_5071_50711101_84_dialog_content = "連れて行ってくれ！俺はあんたに付いて行く！",
  ui_story_5071_50711101_85_dialog_content = "今はこれだけ人の目があるから、おかしなことはできないだろうが、\nこのまま飛空艇に残れば、どうなるか…",
  ui_story_5071_50711101_86_dialog_content = "俺には家族がいるんだ。まだ死にたくない！",
  ui_story_5071_50711101_87_dialog_content = "（ひそひそ……）",
  ui_story_5071_50711101_88_dialog_content = "お、俺も行く！",
  ui_story_5071_50711101_89_dialog_content = "俺もだ！",
  ui_story_5071_50711101_90_dialog_content = "急ごう。ここに残っていては危険だ。",
  ui_story_5071_50711101_91_dialog_content = "なんだってんだ？簡単に乗せられやがって。\n俺たちは悪人かってんだ。",
  ui_story_5071_50711101_92_dialog_content = "ずっと友達ぶってたのに、ヤなやつら～。",
  ui_story_5071_50711101_93_dialog_content = "おい、その女に付いてったら、\nそれこそどうなるか知らねぇぞ。",
  ui_story_5071_50711101_94_dialog_content = "ここに残れば、僕たちが何をするか分かりませんからね。",
  ui_story_5071_50711101_95_dialog_content = "急いで逃げろ――",
  ui_story_5071_50711101_96_dialog_content = "好きにさせておけ。",
  ui_story_5071_50711101_97_dialog_content = "ハンスにはハンスの「計画」があるらしい。",
  ui_story_5071_50711101_98_dialog_content = "計画が実現するまでは、\n大事な「観客」を傷つけることはしないだろう。",
  ui_story_5071_50711101_99_dialog_content = "あいつら戻ったらきっと、\n有ること無いこと言いふらしますぜ。",
  ui_story_5071_50711101_100_dialog_content = "お前たちも小型飛空艇で追跡しろ。",
  ui_story_5071_50711101_101_dialog_content = "ただし、全員の安全確保が第一だ。\n距離を保って飛べ。",
  ui_story_5071_50711101_102_dialog_content = "<color=#e8d9bb>ボンッ――</color>",
  ui_story_5071_50711101_103_dialog_content = "この飛空艇は本当にもう危ないようですね。\nあなたたちも――",
  ui_story_5071_50711101_104_dialog_content = "このままその男の側にいたら、危険ですよ。",
  ui_story_5071_50711101_105_dialog_content = "イスタバンさんは何もしてないのに、\nそんなふうに言うのはおかしいでしょう？",
  ui_story_5071_50711101_106_dialog_content = "その男は本当の自分を影の中に隠してきただけ。\n私はその正体を知っているのです。",
  ui_story_5071_50711101_107_dialog_content = "兄弟と呼び合った友を自ら手にかけ、養父からすべてを奪い、\nそして彼らを誰も知ることのない影の中に埋もれさせました。",
  ui_story_5071_50711101_108_dialog_content = "利益を得るためなら、自身の名を捨てることさえいとわない――",
  ui_story_5071_50711101_109_dialog_content = "王座に座るためなら、誰であろうと踏みつぶして進む、\nただの「悪魔」にすぎないのです。",
  ui_story_5071_50711101_X109_dialog_content = "「カイド」、あなたにその<color=#FFB400>ケーン</color>を持つ資格はありません！",
  ui_story_5071_50711101_110_dialog_content = "…",
  ui_story_5071_50711101_111_dialog_content = "…あなたが何と言おうと、\n僕は自分の知っているイスタバンさんを信じます。",
  ui_story_5071_50711101_112_dialog_content = "よく言ったわ。ハンスさん、申し訳ないけど、\nここから出て行ってもらえるかしら。",
  ui_story_5071_50711101_113_dialog_content = "ごめんなさい。私はここに残るわ。",
  ui_story_5071_50711101_114_dialog_content = "スクープの香りがしますね。私もここに残ります。",
  ui_story_5071_50711101_115_dialog_content = "…",
  ui_story_5071_50711101_116_dialog_content = "後悔しますよ。",
  ui_story_5071_50711101_117_dialog_content = "あなたたちもその男の本性をよく知っているはずです。\nなぜ、危険だと思わないのですか？",
  ui_story_5071_50711101_118_dialog_content = "かわいそうな方々ですね…同情します。",
  ui_story_5071_50711101_119_dialog_content = "では、またな。「ハンス」。",
  ui_story_5071_50711101_120_dialog_content = "では、お前たちも…",
  ui_story_5071_50711101_121_dialog_content = "敵の気配です！",
  ui_story_5071_50711101_122_dialog_content = "シェオル会長、お気を付けください！その衛兵は――",
  ui_story_5071_50711101_123_dialog_content = "やつらには仲間がいます。そいつらは――",
  ui_story_5071_50711101_124_dialog_content = "黙れ！",
  ui_story_5071_50711101_125_dialog_content = "「ボス」の命令だ。1人残らず始末しろ。",
  ui_story_5071_50711101_126_dialog_content = "大変だ、<size=45>皆、戦闘準備を！</size>",
  ui_story_5071_50711102_1_dialog_content = "商会の警備員まで…",
  ui_story_5071_50711102_2_dialog_content = "全員やられてしまったようですね…はぁ…",
  ui_story_5071_50711102_3_dialog_content = "よかった、こっちにいて…",
  ui_story_5071_50711102_4_dialog_content = "ボス！無事ですか？窓の外、こっちですよ！",
  ui_story_5071_50711102_5_dialog_content = "皆の安全を守れと言ったはずだ。なぜ戻ってきた？",
  ui_story_5071_50711102_6_dialog_content = "この先で怪しい動きをしてるやつらを見かけたんで、\nボスのことが心配になって戻ってきたんですよ。",
  ui_story_5071_50711102_7_dialog_content = "で、どうしました？もう片付けちまいましたか？",
  ui_story_5071_50711102_8_dialog_content = "…ひとまず、客人らを迎えに来い。",
  ui_story_5071_50711102_9_dialog_content = "PlayerNameはともかく、なぜバージルまで残ったの？",
  ui_story_5071_50711102_10_dialog_content = "え？だって、これはシェオルさんの飛空艇でしょ？",
  ui_story_5071_50711102_11_dialog_content = "まだ勤務時間中だし、\n勝手にどっか行っちゃいけないよね？",
  ui_story_5071_50711102_12_dialog_content = "…",
  ui_story_5071_50711102_13_dialog_content = "イスタバンさん、さっき僕も読んだんです。",
  ui_story_5071_50711102_14_dialog_content = "そこにはイスタバンさんのことらしき物語が書かれていたけど…\nでも、僕には信じられません。",
  ui_story_5071_50711102_15_dialog_content = "だから、教えてください。本当にあんなことを？\nメリッサ夫人は――",
  ui_story_5071_50711102_16_dialog_content = "PlayerName！",
  ui_story_5071_50711102_17_dialog_content = "ホストの私を挟まずに、勝手に質問をするのはマナー違反よ。",
  ui_story_5071_50711102_18_dialog_content = "ご、ごめんなさい…",
  ui_story_5071_50711102_19_dialog_content = "それに今は、そんなことを話している場合じゃないわ。",
  ui_story_5071_50711102_20_dialog_content = "私たちの乗っているこの飛空艇を\n復旧させることの方が先よ。",
  ui_story_5071_50711102_21_dialog_content = "それが終わったら、下手人にはこの借りを\n利子も含めてきっちり返してもらうわ。",
  ui_story_5071_50711102_22_dialog_content = "では、俺はそれを待つか。",
  ui_story_5071_50711102_23_dialog_content = "それはそうと、シャドウマスターも人が良すぎるわね。",
  ui_story_5071_50711102_24_dialog_content = "あの人たちには色々と力を貸して、\n助けてあげてたっていうのに――",
  ui_story_5071_50711102_25_dialog_content = "あんなに簡単にそそのかされて、逃げだすなんて。",
  ui_story_5071_50711102_26_dialog_content = "おい！シェオル、あんたまでなんでイヤミを言いやがる。",
  ui_story_5071_50711102_27_dialog_content = "こんな時に、内輪もめはよくないわ。\n助け合わなきゃいけない時でしょ？",
  ui_story_5071_50711102_28_dialog_content = "シャドウマスターにはぜひとも取材をお願いしたいですが…\nこのタイミングは良くないですよね…",
  ui_story_5071_50711102_29_dialog_content = "シャドウマスター様、私たちはどうすれば？",
  ui_story_5071_50711102_30_dialog_content = "俺を信用し、ここに残ってくれたことに心から感謝する。",
  ui_story_5071_50711102_31_dialog_content = "部下に地上まで送らせよう。",
  ui_story_5071_50711102_32_dialog_content = "セレウコス、飛空艇を準備して、お客人たちを地上へ。",
  ui_story_5071_50711102_33_dialog_content = "過去の影の狙いは俺だ。",
  ui_story_5071_50711102_34_dialog_content = "お前たちは客人を無事に地上へ送り届けろ。",
  ui_story_5071_50711102_35_dialog_content = "ボス…",
  ui_story_5071_50711102_36_dialog_content = "これは命令だ。",
  ui_story_5071_50711102_37_dialog_content = "はい…",
  ui_story_5071_50711102_38_dialog_content = "こちらベセル、応答してください。",
  ui_story_5071_50711102_39_dialog_content = "お父様、双閣港に通じる輸送路に、\n不審な者たちが現れました。",
  ui_story_5071_50711102_40_dialog_content = "その者たちは影ノ街に向けて、武器と傭兵を送り込もうとしており、\nすでにその場で捕らえています。",
  ui_story_5071_50711102_41_dialog_content = "そちらの状況は？\nシェオルさんの飛空艇の初飛行記念式典は順調ですか？",
  ui_story_5071_50711102_42_dialog_content = "何も問題ない。心配するな。",
  ui_story_5071_50711102_43_dialog_content = "ベセル、騒ぎたてることが大好きな「お客人たち」が、\n我が家に訪ねて来るかもしれん。",
  ui_story_5071_50711102_44_dialog_content = "お前は主として、しっかりと「おもてなし」して差し上げろ。",
  ui_story_5071_50711102_45_dialog_content = "分かりました。お父様も十分お気をつけて。",
  ui_story_5071_50711102_46_dialog_content = "<color=#e8d9bb>ボンッ――</color>",
  ui_story_5071_50711102_47_dialog_content = "大変だ…飛空艇がバランスを失ったまま回復してない…",
  ui_story_5071_50711102_48_dialog_content = "しかも、今は揺れというより震動になってる…\n動力が止まりかけてるんだ…",
  ui_story_5071_50711102_49_dialog_content = "PlayerName、巨像を操縦してるあなたにそんなこと言われたら、\n怖くなっちゃうじゃない。",
  ui_story_5071_50711102_50_dialog_content = "修理がうまくいったなら、こんなふうにはならないはずです。",
  ui_story_5071_50711102_51_dialog_content = "飛空艇の故障がこのままなら、まっすぐ下降して…\n影ノ街の中心部に墜落します！",
  ui_story_5071_50711102_52_dialog_content = "シェオル会長！大変です――",
  ui_story_5071_50711102_53_dialog_content = "下で修理を担当してた者たちが、全員…",
  ui_story_5071_50711102_54_dialog_content = "何ですって！？",
  ui_story_5071_50711201_1_dialog_content = "大変だわ。急いで制御室に向かいましょう。",
  ui_story_5071_50711201_2_dialog_content = "機関士たちがまだ中にいるのよ！",
  ui_story_5071_50711201_3_dialog_content = "これは――",
  ui_story_5071_50711201_4_dialog_content = "遅かったわ…機関士も…\n制御装置まで破壊されているわね。",
  ui_story_5071_50711201_5_dialog_content = "こんなの、ひどすぎる…",
  ui_story_5071_50711201_6_dialog_content = "何とかして飛空艇の方向を変えないと…",
  ui_story_5071_50711201_7_dialog_content = "また一歩遅かった…",
  ui_story_5071_50711201_8_dialog_content = "…",
  ui_story_5071_50711201_9_dialog_content = "待ってください！これは…",
  ui_story_5071_50711201_10_dialog_content = "本当にソラヴァンを真似て造ったんですか！？",
  ui_story_5071_50711201_11_dialog_content = "ただの冗談かと思ってました…",
  ui_story_5071_50711201_12_dialog_content = "式典に参加してくれるなら、お礼として…",
  ui_story_5071_50711201_13_dialog_content = "制御室を巨像とそっくりに仕立てるっていうのはどう？",
  ui_story_5071_50711201_14_dialog_content = "だから、来てもらえないかしら？",
  ui_story_5071_50711201_X11_dialog_content = "フフ。それくらい私には簡単なことだもの。",
  ui_story_5071_50711201_15_dialog_content = "あなたが特別ゲストとして参加してくれれば、\nいい「宣伝」になるのよ。",
  ui_story_5071_50711201_16_dialog_content = "でも、これなら…操縦できるかもしれません。",
  ui_story_5071_50711201_17_dialog_content = "そうよね！巨像のナビゲーターだもの、試してみる価値はあるわ！",
  ui_story_5071_50711201_18_dialog_content = "「演奏」すれば、いつかみたいに――",
  ui_story_5071_50711201_19_dialog_content = "うーん…",
  ui_story_5071_50711201_20_dialog_content = "反応がない…",
  ui_story_5071_50711201_21_dialog_content = "ソラヴァンのシステムとはまったく違うみたいだ。",
  ui_story_5071_50711201_X21_dialog_content = "修理の仕方は…僕じゃ分からないし…",
  ui_story_5071_50711201_X22_dialog_content = "それはそうよね…この制御装置はそもそも\n空の末裔のものじゃなく、普通の骨董品だもの。",
  ui_story_5071_50711201_22_dialog_content = "そもそも故障してるんだし…",
  ui_story_5071_50711201_23_dialog_content = "まねたのは見た目だけだから…まぁ、やっぱり無理よね。",
  ui_story_5071_50711201_24_dialog_content = "どうすれば…",
  ui_story_5071_50711201_25_dialog_content = "あの…今、骨董って言った？",
  ui_story_5071_50711201_26_dialog_content = "お兄ちゃん、シェオルさん。\nボク、こういう古い制御装置を見たことあるよ。",
  ui_story_5071_50711201_27_dialog_content = "制御装置の構造を知っているの？\n修理はできそうかしら？",
  ui_story_5071_50711201_28_dialog_content = "ちょっと時間をくれれば、「復元」できるかも。",
  ui_story_5071_50711201_29_dialog_content = "間に合うのか？",
  ui_story_5071_50711201_30_dialog_content = "飛空艇の高度低下が早くなっているぞ。",
  ui_story_5071_50711201_31_dialog_content = "待ってください…もしこの飛空艇の構造が…\n本当に巨像をまねたものだとしたら…",
  ui_story_5071_50711201_32_dialog_content = "僕に考えがあります！",
  ui_story_5071_50711201_33_dialog_content = "外からの力で「翼」の方向を変えれば、下降速度を緩めて、\n不時着できるかもしれません。",
  ui_story_5071_50711201_34_dialog_content = "どうやるんだ？",
  ui_story_5071_50711201_35_dialog_content = "付いてきてください。",
  ui_story_5071_50711201_36_dialog_content = "PlayerName、これを見るといいわ。",
  ui_story_5071_50711201_37_dialog_content = "飛空艇のハンドブックよ。\n構造を理解するのに役立つはずだわ。",
  ui_story_5071_50711201_38_dialog_content = "私はここでバージルを護衛するわ。\n飛空艇はあなたたちに任せたわよ。",
  ui_story_5071_50711201_39_dialog_content = "行くぞ。",
  ui_story_5071_50711201_40_dialog_content = "待ってください…まだ問題があります。\n翼部は外側からしかいじれないので、小型飛空艇が必要です！",
  ui_story_5071_50711201_41_dialog_content = "――甲板に行ってみよう。",
  ui_story_5071_50711201_42_dialog_content = "PlayerName、シャドウマスター、必ず…",
  ui_story_5071_50711201_X42_dialog_content = "よかった…！まだ1隻小型飛空艇が残ってました！",
  ui_story_5071_50711201_44_dialog_content = "セレウコスたちが残していったようだな。",
  ui_story_5071_50711201_45_dialog_content = "乗れ。何をすればいい？",
  ui_story_5071_50711201_46_dialog_content = "まずはハンドブックで具体的な構造を調べてみます…\nあ、ありました！",
  ui_story_5071_50711201_47_dialog_content = "この飛空艇は巨像と同じように翼があります。\n構造はまったく同じじゃありませんが、原理は一緒です。",
  ui_story_5071_50711201_48_dialog_content = "翼の後部へ行って、関節の方向を調整すれば、\n翼の方向が変わって、飛空艇も方向転換できます。",
  ui_story_5071_50711201_49_dialog_content = "しっかり掴まっていろ！",
  ui_story_5071_50711201_50_dialog_content = "うわあ――",
  ui_story_5071_50711201_51_dialog_content = "お前の言っていた「翼」はこれか？",
  ui_story_5071_50711201_52_dialog_content = "ハハハ。実に大きな翼だ。",
  ui_story_5071_50711201_53_dialog_content = "この翼の関節を本当に動かせるのか？",
  ui_story_5071_50711201_54_dialog_content = "イスタバンさん、もう少し近づけますか？\n細かい構造を見てみたいんです。",
  ui_story_5071_50711201_55_dialog_content = "これは――",
  ui_story_5071_50711201_56_dialog_content = "ダメです。この翼は巨像よりもずっと粗雑にできています。",
  ui_story_5071_50711201_57_dialog_content = "普通の動力で翼が動くようにするために、無理な設計になってる…\nこれじゃ手動で調整するのは無理だ…",
  ui_story_5071_50711201_58_dialog_content = "ハハハ。細かいことにこだわらず、ロマンを追い求める。\nそれこそ若者の<color=#FFB400>夢</color>というものだ！",
  ui_story_5071_50711201_59_dialog_content = "仕方ないな――",
  ui_story_5071_50711201_60_dialog_content = "空を飛ぶことを夢見た翼は、\nそう簡単に現実に屈したりしないものだ！",
  ui_story_5071_50711201_61_dialog_content = "イスタバンさん、これ以上近づいたら、\n巻き込まれます――",
  ui_story_5071_50711201_62_dialog_content = "近づかずに、どう方向を調整すると言うんだ？",
  ui_story_5071_50711201_63_dialog_content = "イスタバンさん！？",
  ui_story_5071_50711201_64_dialog_content = "飛空艇の操縦は任せたぞ！",
  ui_story_5071_50711201_65_dialog_content = "うおおおお――！",
  ui_story_5071_50711201_66_dialog_content = "ムチャです！こんな巨大な﻿可動部に手をかけたら…",
  ui_story_5071_50711201_67_dialog_content = "PlayerName！どちらに回すんだ？",
  ui_story_5071_50711201_68_dialog_content = "そんな――",
  ui_story_5071_50711201_69_dialog_content = "<color=#e8d9bb>ミシッ――</color>",
  ui_story_5071_50711201_70_dialog_content = "（信じられない！イスタバンさん、\nこんな大きな翼の重量に耐えてる…）",
  ui_story_5071_50711201_71_dialog_content = "向かって左です！その部品を力いっぱい回せば、\n翼全体が動くはずです！",
  ui_story_5071_50711201_72_dialog_content = "はぁああっ――",
  ui_story_5071_50711201_73_dialog_content = "そう急いで落ちるな――！",
  ui_story_5071_50711201_74_dialog_content = "ガタン――ガタン――",
  ui_story_5071_50711201_75_dialog_content = "（翼が…動いた…こんな大きな翼が！？）",
  ui_story_5071_50711201_76_dialog_content = "向きが変わりました、成功です！",
  ui_story_5071_50711201_77_dialog_content = "まだだ――",
  ui_story_5071_50711201_78_dialog_content = "影ノ街から、もっと離す――",
  ui_story_5071_50711201_79_dialog_content = "動け――！！",
  ui_story_5071_50711201_80_dialog_content = "ドカン――",
  ui_story_5071_50711201_81_dialog_content = "大変です！後部エンジンが爆発しました！",
  ui_story_5071_50711201_82_dialog_content = "（このままじゃ、方向転換する前に墜落しちゃう…）",
  ui_story_5071_50711201_83_dialog_content = "このままでは、影ノ街の境界付近に落ちる…まだまだだ…",
  ui_story_5071_50711201_84_dialog_content = "早く戻ってきてください！\nこのままだとイスタバンさんまで――",
  ui_story_5071_50711201_85_dialog_content = "風を受けて、舞い上がれ！！",
  ui_story_5071_50711201_86_dialog_content = "<color=#e8d9bb>ドォォン――！</color>",
  ui_story_5071_50711201_87_dialog_content = "は、花火！？",
  ui_story_5071_50711201_88_dialog_content = "どういうこと？こんな時に急に花火なんて…",
  ui_story_5071_50711201_89_dialog_content = "おお！見ろ！",
  ui_story_5071_50711201_90_dialog_content = "浮遊商会の飛空艇が来たぞ！",
  ui_story_5071_50711201_91_dialog_content = "初飛行記念式典のイベントだろうな…\nそれにしても、ずいぶん近いな！",
  ui_story_5071_50711201_92_dialog_content = "なんてきれいな花火なんだ！\n浮遊商会の飛空艇もたいしたもんだな！",
  ui_story_5071_50711201_93_dialog_content = "きっとシェオル会長が俺たちのために盛り上げてくれてるんだ！",
  ui_story_5071_50711201_94_dialog_content = "ちょっと！おバカさんたち、見物してる場合じゃないよ！",
  ui_story_5071_50711201_95_dialog_content = "さっさと避難して！飛空艇が落ちるの！",
  ui_story_5071_50711201_96_dialog_content = "イスタバン組のやつら、何を大騒ぎしてるんだ？",
  ui_story_5071_50711201_97_dialog_content = "早く逃げろ！シャドウマスターが浮遊商会艇の客を皆殺しにしたらしい――",
  ui_story_5071_50711201_98_dialog_content = "それだけじゃ飽き足らず、あの艇でスラム街を潰す気だ！",
  ui_story_5071_50711201_99_dialog_content = "私たちに付いてきて！急いで街の外に逃げるんだよ――",
  ui_story_5071_50711201_100_dialog_content = "来るな！俺たちが何をしたって言うんだ！",
  ui_story_5071_50711201_101_dialog_content = "それ以上近づけば、攻撃する！",
  ui_story_5071_50711201_102_dialog_content = "なんだって俺たちを警戒しやがんだ！？\nクソッ、石投げんじゃねえ！",
  ui_story_5071_50711201_103_dialog_content = "イスタバン組が一般人を攻撃したぞ！！",
  ui_story_5071_50711201_104_dialog_content = "<size=45>おいっ！！</size>",
  ui_story_5071_50711201_105_dialog_content = "まあ、みんな落ち着いて…\nこれ以上攻撃されたら、僕たちも反撃せざるを得なくなるよ。",
  ui_story_5071_50711201_106_dialog_content = "なんなの！？あいつら、なんで急に…",
  ui_story_5071_50711201_107_dialog_content = "飛空艇で好き勝手いいやがった野郎だ！\nまた、てめえか！",
  ui_story_5071_50711201_108_dialog_content = "待てっ！",
  ui_story_5071_50711201_109_dialog_content = "おやおや、頭に血がのぼってるね。\nこうなると少々厄介だよ。",
  ui_story_5071_50711201_110_dialog_content = "これは――",
  ui_story_5071_50711201_111_dialog_content = "飛行艇の向きが変わった…？",
  ui_story_5071_50711201_112_dialog_content = "どうやら、制御装置を修理できたようだな。",
  ui_story_5071_50711201_113_dialog_content = "戻るぞ。",
  ui_story_5071_50711201_114_dialog_content = "しっかり乗っていろ。",
  ui_story_5071_50711201_115_dialog_content = "こっちは花火のボタンで、こっちは放送用のボタン、\nそれから、こっちが…",
  ui_story_5071_50711201_116_dialog_content = "バージル、制御装置を直せたの？",
  ui_story_5071_50711201_117_dialog_content = "いや、ダメだよ。方向は制御できるけど、\n上昇できないんだ。",
  ui_story_5071_50711201_118_dialog_content = "うーん…きっとエンジンがやられたせいだね…",
  ui_story_5071_50711201_119_dialog_content = "やはり墜落は免れないの…？",
  ui_story_5071_50711201_120_dialog_content = "ちゃんと方向を制御して、ゴールド・リバーに不時着できれば、\n機体は残せるかもしれないよ？",
  ui_story_5071_50711201_121_dialog_content = "シェオルさん、川の方に飛ばす？",
  ui_story_5071_50711201_122_dialog_content = "…そんなことをすれば、川の両岸の住民に被害が及ぶわ。",
  ui_story_5071_50711201_123_dialog_content = "峡谷の方にしましょう。\nあそこなら人がいないわ。",
  ui_story_5071_50711201_124_dialog_content = "でも、そうしたら、この飛空艇はバラバラになっちゃうよ？",
  ui_story_5071_50711201_125_dialog_content = "俺の責任だ。お前の飛空艇を…",
  ui_story_5071_50711201_126_dialog_content = "何を言うのよ、シャドウマスター。\nまるで自分が犯人みたいな言い方じゃない。",
  ui_story_5071_50711201_127_dialog_content = "…",
  ui_story_5071_50711201_128_dialog_content = "飛空艇の制御方法を教えてちょうだい。\nその後あなたたちは避難して。",
  ui_story_5071_50711201_129_dialog_content = "シェオルさん？",
  ui_story_5071_50711201_130_dialog_content = "不時着するにしたって操縦者は必要でしょ？\nこれは私の飛空艇なのよ？",
  ui_story_5071_50711201_131_dialog_content = "だから、あなたたちは――",
  ui_story_5071_50711201_132_dialog_content = "お前たちは先に行け。俺が操縦する。",
  ui_story_5071_50711201_133_dialog_content = "イスタバンさん！？",
  ui_story_5071_50711201_134_dialog_content = "そんなこと――",
  ui_story_5071_50711201_135_dialog_content = "シェオル、他人の仕事は奪うものじゃない。",
  ui_story_5071_50711201_136_dialog_content = "それに、俺はこういうことには慣れている。",
  ui_story_5071_50711201_137_dialog_content = "行け。空へ飛び立つことを望んだ者の夢を、\n空で終わらせることはない。",
  ui_story_5071_50711201_138_dialog_content = "イスタバンさん…",
  ui_story_5071_50711201_139_dialog_content = "子ども2人を連れて、必ず無事に避難するんだ。",
  ui_story_5071_50711201_140_dialog_content = "…覚えているかしら？私に借りがあること。",
  ui_story_5071_50711201_141_dialog_content = "俺は誓ったことは決して忘れない。",
  ui_story_5071_50711201_142_dialog_content = "それならいいわ。この子たちは私が守る。",
  ui_story_5071_50711201_143_dialog_content = "ただし、交換条件があるわ――\n約束通り、私の願いをかなえてちょうだい。",
  ui_story_5071_50711201_144_dialog_content = "私の願いは…生きて戻ってくること。",
  ui_story_5071_50711201_145_dialog_content = "…確かに聞き届けた。",
  ui_story_5071_50711201_146_dialog_content = "さあ、時間がない。行け！",
  ui_story_5071_50711201_147_dialog_content = "影がお前たちを守ってくれる。",
  ui_story_5071_50711201_148_dialog_content = "<color=#FFB400>「バロン」</color>…我が友よ。\nお前の夢はもっと確かなもののはずだ…",
  ui_story_5071_50711202_1_dialog_content = "ブリッジマン会長、ようやくお戻りになりましたか。",
  ui_story_5071_50711202_2_dialog_content = "自己紹介は必要ありませんね？",
  ui_story_5071_50711202_3_dialog_content = "ベ、ベセル殿？これはまた、突然どうしました…",
  ui_story_5071_50711202_4_dialog_content = "なぜご連絡をくださらなかったのです…？",
  ui_story_5071_50711202_5_dialog_content = "街の外で傭兵一味を捕らえました。\n武装して影ノ街に入ろうとしていたのです。",
  ui_story_5071_50711202_6_dialog_content = "彼らの使用していた輸送器具や協力していた人員、\nおよび供述から…",
  ui_story_5071_50711202_7_dialog_content = "貴方の「赤豹商会」とお仲間の「ペアレット商会」、\nおよび「錆鉄隼組」…",
  ui_story_5071_50711202_8_dialog_content = "少なくとも、この三者がこの件に関与していたと見られています。",
  ui_story_5071_50711202_9_dialog_content = "あなたが規則に反し、\n武器を密輸していた証拠写真も確保しました。",
  ui_story_5071_50711202_10_dialog_content = "「影ノ街治安条例」に従い、ご同行いただけますか？",
  ui_story_5071_50711202_11_dialog_content = "お、お待ちください。きっと何かの間違いです。",
  ui_story_5071_50711202_12_dialog_content = "こんなことをしてタダで済むと思っているのですか！",
  ui_story_5071_50711202_13_dialog_content = "あと1時間…いや、数十分もすれば…",
  ui_story_5071_50711202_14_dialog_content = "何が言いたいのです？",
  ui_story_5071_50711202_15_dialog_content = "何か企みがあるようですね…",
  ui_story_5071_50711202_16_dialog_content = "<size=45>きゃあ―――！！</size>",
  ui_story_5071_50711202_17_dialog_content = "何の騒ぎです！？",
  ui_story_5071_50711202_18_dialog_content = "どうしたのですか！？\nなぜ大混乱になっているのです？",
  ui_story_5071_50711202_19_dialog_content = "その人は押送してください。",
  ui_story_5071_50711202_20_dialog_content = "了解です！",
  ui_story_5071_50711202_21_dialog_content = "こちら総合商会、ベセルです。\n何が起こったのですか？",
  ui_story_5071_50711202_22_dialog_content = "ベセル様！お戻りでしたか？",
  ui_story_5071_50711202_23_dialog_content = "シャドウマスター様が…",
  ui_story_5071_50711202_24_dialog_content = "落ち着いて話してください。お父様がどうされたのです？",
  ui_story_5071_50711202_25_dialog_content = "シャドウマスター様とシェオル会長の乗った飛空艇が\n墜落しつつあります！",
  ui_story_5071_50711202_26_dialog_content = "何ですって！？",
  ui_story_5071_50711202_27_dialog_content = "<color=#e8d9bb>ドカーン…！！！</color>",
  ui_story_5071_50711202_28_dialog_content = "い、今のは…飛空艇が墜落したのですか…？",
  ui_story_5071_50711202_29_dialog_content = "ベセル様、どうしましょう？",
  ui_story_5071_50711202_30_dialog_content = "飛空艇からの落下物が、街に落ちたようです。",
  ui_story_5071_50711202_31_dialog_content = "今、街には住民の中に紛れて騒ぎを扇動する者がいるようで、\n街の外では、あちこちに傭兵が…",
  ui_story_5071_50711202_32_dialog_content = "セレウコス様にシャドウマスター様を助けに行くよう言われたのですが、\nべセル様の許可なく動くわけには…",
  ui_story_5071_50711202_33_dialog_content = "お父様…",
  ui_story_5071_50711202_34_dialog_content = "そういうことだったのですね――",
  ui_story_5071_50711202_35_dialog_content = "私を敢えて同行させなかったのは、\n危険を察しておいでだったからですか…？",
  ui_story_5071_50711202_36_dialog_content = "ベセル様？",
  ui_story_5071_50711202_37_dialog_content = "落ち着いてください。シャドウマスターはきっとご無事です。",
  ui_story_5071_50711202_38_dialog_content = "それから、総合商会の全員に私の命令を伝えてください。",
  ui_story_5071_50711202_39_dialog_content = "はっ、はい！！",
  ui_story_5071_50711202_40_dialog_content = "今、何者かが影ノ街を狙っています。\n足並みを乱して、相手に付け込む隙を与えてはなりません。",
  ui_story_5071_50711202_41_dialog_content = "私が名簿と証拠を自警団に渡します。\nクレーケンには、自警団本部に合流し――",
  ui_story_5071_50711202_42_dialog_content = "彼らと協力して名簿の者たちを捕らえるように伝達を。\n混乱に乗じて逃走や抵抗をはかる者が出るかもしれません。油断しないように。",
  ui_story_5071_50711202_43_dialog_content = "了解です！",
  ui_story_5071_50711202_44_dialog_content = "セレウコスは自警団から戦闘員を集め、\n人員の半分を街の外に派遣し、警備の強化を。",
  ui_story_5071_50711202_45_dialog_content = "パテとパシには、私について街の混乱の鎮静化をはかるよう伝えて下さい。",
  ui_story_5071_50711202_46_dialog_content = "そのほか、救助隊の主力は私と一緒に住民の救助にあたり、\n別途2隊を組織して、シャドウマスターの捜索を。",
  ui_story_5071_50711202_47_dialog_content = "決して足並みを乱してはなりません。\nシャドウマスターがお帰りになるまで、街を守るのです。分かりましたか？",
  ui_story_5071_50711202_48_dialog_content = "はい！べセル様！",
  ui_story_5071_50711202_49_dialog_content = "お父様…信じています。ですから必ず、あの時のように…",
  ui_story_5071_50711202_50_dialog_content = "もう一度<color=#FFB400>「英雄」</color>になってください。",
  ui_story_5071_50711301_1_dialog_content = "飛空艇が…あんなにきれいだった飛空艇が、なくなっちゃった…",
  ui_story_5071_50711301_2_dialog_content = "イスタバンさん、成功したんですね。\n人のいない郊外に墜落させたんですね――",
  ui_story_5071_50711301_3_dialog_content = "もう少し近くに着陸してちょうだい。",
  ui_story_5071_50711301_4_dialog_content = "さっきまで空を飛んでたのに…今は…",
  ui_story_5071_50711301_5_dialog_content = "仕方ないわ。影ノ街に住む者の夢は、\nいつだって長くは続かないのよ。",
  ui_story_5071_50711301_6_dialog_content = "わあ…すごい火だ…焼け焦げた残骸だらけだよ…",
  ui_story_5071_50711301_7_dialog_content = "飛空艇に乗せてた芸術品も全部…\nシェオルさん、ど、どうしよう？",
  ui_story_5071_50711301_8_dialog_content = "私のコレクションは二の次よ。何よりもお客様が持ち込んだ作品の中には、\n二つとない逸品もあった…私が弁償するしかないわね。",
  ui_story_5071_50711301_9_dialog_content = "シェオルさん…",
  ui_story_5071_50711301_10_dialog_content = "大丈夫、心配しないで。商売には儲けも損もつきものなの。\nとうの昔に慣れっこよ。",
  ui_story_5071_50711301_11_dialog_content = "今はまだ弁償で破産する程じゃないわ。\nだから、まずはシャドウマスターを探しましょ。",
  ui_story_5071_50711301_12_dialog_content = "あ、あちちっ…シャドウマスター、\nこんな所で「無事」でいられるかな？",
  ui_story_5071_50711301_13_dialog_content = "影っていうのは見えない隅で生きることを最も得意としているのよ。\n必ず生きているわ。",
  ui_story_5071_50711301_14_dialog_content = "あぶない！そっちは火が激しいよ。",
  ui_story_5071_50711301_15_dialog_content = "（感知できない…イスタバンさんを…感知できない…）",
  ui_story_5071_50711301_16_dialog_content = "シャドウマスター？シャドウマスター！",
  ui_story_5071_50711301_17_dialog_content = "年を取って、耳が遠くなったのかしら？\nかくれんぼなんて歳でもないでしょう？",
  ui_story_5071_50711301_18_dialog_content = "（ベセルはどうなるの…？影ノ街はこれからどうなるの…？\nどうやって伝えればいいんだろう…）",
  ui_story_5071_50711301_19_dialog_content = "シェオルさん、ダメだよ！早く戻ってきて！\nここはすぐに完全に燃えちゃう…",
  ui_story_5071_50711301_20_dialog_content = "まだ支払いが済んでない取引があるのよ。\n踏み倒してもらっちゃ、シャドウマスターの信用が傷つくわ！",
  ui_story_5071_50711301_21_dialog_content = "でも…",
  ui_story_5071_50711301_22_dialog_content = "ボク…わからなくなっちゃった…\nシャドウマスターはいい人なの？それとも悪い人？",
  ui_story_5071_50711301_23_dialog_content = "…バージル。",
  ui_story_5071_50711301_24_dialog_content = "大人の世界にはね、いい人も悪い人もないのよ。",
  ui_story_5071_50711301_25_dialog_content = "でも、シャドウマスターは自身の命も顧みず、\n私たちを助けてくれた。それは間違いのない事実でしょ。",
  ui_story_5071_50711301_26_dialog_content = "火の勢いが強いわ…急いで人を呼んで、消火しなきゃいけないわ。",
  ui_story_5071_50711301_27_dialog_content = "ベセルには伝えますか？",
  ui_story_5071_50711301_28_dialog_content = "…はぁ…ベセルには伝えないとね。",
  ui_story_5071_50711301_29_dialog_content = "今回の事件には「陰謀」の匂いがぷんぷんしているわ。",
  ui_story_5071_50711301_30_dialog_content = "イヴォンさんは毒殺されたみたいだし、\n飛空艇では、白夜城の衛兵が私たちを攻撃してきた――",
  ui_story_5071_50711301_31_dialog_content = "この計画を企んだやつの狙いは私ではなさそうね。目標はおそらく「影ノ街」…\nあるいは、シャドウマスターと言った方がいいわね。",
  ui_story_5071_50711301_32_dialog_content = "イスタバンさんも「過去の影」がどうのと言ってましたよね？\nもしかしたら、相手が誰か分かってたんじゃないですか？",
  ui_story_5071_50711301_33_dialog_content = "過去の影？だったら、「ハンス」がよく知っているはずよ。",
  ui_story_5071_50711301_34_dialog_content = "あ、誰か来ました！",
  ui_story_5071_50711301_35_dialog_content = "ホーッ、ホーッ――",
  ui_story_5071_50711301_36_dialog_content = "今のは…フクロウの鳴き声？",
  ui_story_5071_50711301_37_dialog_content = "見つけましたか。戻ってきなさい。",
  ui_story_5071_50711301_38_dialog_content = "ホーッ、ホーッ――",
  ui_story_5071_50711301_39_dialog_content = "あなたは…「ハンス」さん？",
  ui_story_5071_50711301_40_dialog_content = "（フクロウ…この感じ、前にも…）",
  ui_story_5071_50711301_41_dialog_content = "まさか、ここに墜落するとは…\n何年も前ここには人々に恐れられた「ヘカトン・レイク」がありました。",
  ui_story_5071_50711301_42_dialog_content = "あの「裏切者」が自分の兄弟を殺した場所です。",
  ui_story_5071_50711301_43_dialog_content = "！？",
  ui_story_5071_50711301_44_dialog_content = "これこそ運命でしょうか？\n「バロン」、戻ってきましたわ。",
  ui_story_5071_50711301_45_dialog_content = "「裏切者」もここに墜落したのです！",
  ui_story_5071_50711301_46_dialog_content = "影ノ街であろうと、神の目はやはり届いていたのですね！\nあいつはついに報いを受けました！",
  ui_story_5071_50711301_47_dialog_content = "私の手をこれ以上汚さずに済みました…",
  ui_story_5071_50711301_48_dialog_content = "ふふっ…ふふふ。",
  ui_story_5071_50711301_49_dialog_content = "シャドウマスターの「過去の影」とは、\nやはりあなただったのね？「ハンス」さん。",
  ui_story_5071_50711301_50_dialog_content = "昔、何があったんですか？ここはいったい…",
  ui_story_5071_50711301_51_dialog_content = "あの作家がはっきりと書いていたでしょう？",
  ui_story_5071_50711301_52_dialog_content = "「裏切者カイド」がその手で兄弟の「バロン」を殺し、\nそのすべてを奪い、影ノ街を売った所ですよ。",
  ui_story_5071_50711301_53_dialog_content = "そして、この私こそ彼が消し去ろうとしていた「過去」…\n影ノ街の外を放浪し続けた「過去」です。",
  ui_story_5071_50711301_54_dialog_content = "ずっと屈辱に耐え、苦労を重ねて商会を経営してきたのも、\nいつの日か必ず「故郷」に戻り…",
  ui_story_5071_50711301_55_dialog_content = "「裏切者」が丹精込めて作り上げた仮面を\nこの手ではぎ取ってやるためです！",
  ui_story_5071_50711301_56_dialog_content = "あの男にはイスタバンを名乗る資格などありません。\nイスタバンの姓は「バロン」のものです！",
  ui_story_5071_50711301_57_dialog_content = "ごめんなさい、聞きたいことがあって…",
  ui_story_5071_50711301_58_dialog_content = "さっきまで緊急事態だったから、\nずっと聞けずにいたんだけど…",
  ui_story_5071_50711301_59_dialog_content = "ボクたちが最後に見た手書きの原稿は、\n本当にイヴォンさん自身が書いたものなの？",
  ui_story_5071_50711301_60_dialog_content = "バージル、何が言いたいの？",
  ui_story_5071_50711301_61_dialog_content = "イヴォンさんは原稿を書く時、ものすごく入り込むから、\n手書きの原稿はいつだって勢いのある走り書きで、見た目はあまり気にしないんだ。",
  ui_story_5071_50711301_62_dialog_content = "でも、あの最後の原稿は字画がしっかり書かれてた。\n筆跡が深いだけじゃなく、伝わってくる「感じ」も違った。",
  ui_story_5071_50711301_63_dialog_content = "「職人」っぽい…字だったんだよ。",
  ui_story_5071_50711301_64_dialog_content = "しかも、かすかな香りが漂ってた。",
  ui_story_5071_50711301_65_dialog_content = "…それは、贋作の巨匠A氏の特徴なんだ。",
  ui_story_5071_50711301_66_dialog_content = "香り…",
  ui_story_5071_50711301_67_dialog_content = "<color=#FFB400>百合の花</color>だね！",
  ui_story_5071_50711301_68_dialog_content = "「あなたのお書きになった赤水銀の夫人が大好きなのです。\n神秘的で強く、何事にも縛られない――」",
  ui_story_5071_50711301_69_dialog_content = "「彼女の沈黙の見守りがあったからこそ、私も百合の花が好きになったのです。」",
  ui_story_5071_50711301_70_dialog_content = "「消えることのない思い出、偉大な愛と心からの祝福――\nそれが百合の花言葉でしたよね。」",
  ui_story_5071_50711301_71_dialog_content = "「ハンス」さん…",
  ui_story_5071_50711301_72_dialog_content = "<color=#e8d9bb>ハンスは微笑むだけで、否定も肯定もしなかった</color>",
  ui_story_5071_50711301_73_dialog_content = "<color=#e8d9bb>真相は文字となり暴かれた。\nそれを書いたものがイヴォンか、ハンスかは重要なのだろうか？</color>",
  ui_story_5071_50711301_74_dialog_content = "誰しもいくつもの顔を持っているものです。\n私が贋作師のAかどうかは、結末に何の影響も及ぼしませんよ。",
  ui_story_5071_50711301_75_dialog_content = "ううっ…なんで、こんなことしたの…？\nボク、ずっと、憧れてたのに…",
  ui_story_5071_50711301_76_dialog_content = "そういえば、イヴォンさんが言ってたわ。\n「画家の友人」からインスピレーションを得たって。",
  ui_story_5071_50711301_77_dialog_content = "あなたのことだったのね。",
  ui_story_5071_50711301_78_dialog_content = "ずいぶんと精が出るのね。\n過去のために自ら駆け回るなんて…",
  ui_story_5071_50711301_79_dialog_content = "私はあなたの復讐に巻き込まれたってわけね。\n加害者として、飛空艇とそのほかもろもろの損失を補償する気はないかしら？",
  ui_story_5071_50711301_80_dialog_content = "「他人から盗んだ夢」など、壊れて当然です。",
  ui_story_5071_50711301_81_dialog_content = "ハンスさん。あれは正真正銘、私自身の夢よ。",
  ui_story_5071_50711301_82_dialog_content = "あなたの滅茶苦茶な作り話とは違うのよ。",
  ui_story_5071_50711301_83_dialog_content = "私の母のあたりから、あなた、必要のない創作をしたわね？",
  ui_story_5071_50711301_84_dialog_content = "真実かもしれないし――",
  ui_story_5071_50711301_85_dialog_content = "だたのウワサかもしれません。",
  ui_story_5071_50711301_86_dialog_content = "ですが、火のない所に煙は立たないものですよ。",
  ui_story_5071_50711301_87_dialog_content = "いずれにせよ、メリッサ夫人に関する「真相」に関心も興味もありません。\n私の計画に役立てば、それでいいのです。",
  ui_story_5071_50711301_88_dialog_content = "これであなたたちも、\n「カイドの正体」がはっきり分かったでしょう？",
  ui_story_5071_50711301_89_dialog_content = "おかしい――",
  ui_story_5071_50711301_90_dialog_content = "それは…おかしいです！",
  ui_story_5071_50711301_91_dialog_content = "あら、ボクちゃん。何か分かったのですか？",
  ui_story_5071_50711301_92_dialog_content = "当時の真相を暴くと言いながら、\n他人の過去はどうでもいいんですか？",
  ui_story_5071_50711301_93_dialog_content = "シェオルさんにとって、お母さんの過去はとても大切な事なんです…",
  ui_story_5071_50711301_94_dialog_content = "それなのに、あなたは役に立てば、真相はどうでもいいと言う…\n事実かどうかも分からない話で人を傷つけるなんて――",
  ui_story_5071_50711301_95_dialog_content = "自分勝手にも程があります！",
  ui_story_5071_50711301_96_dialog_content = "PlayerName…",
  ui_story_5071_50711301_97_dialog_content = "分かったようなことを言わないで！",
  ui_story_5071_50711301_98_dialog_content = "贋作を描きながら、自分の印を残さずにはいられない――",
  ui_story_5071_50711301_99_dialog_content = "復讐のためなら、卑劣で残忍な手を使うこともいとわない――",
  ui_story_5071_50711301_100_dialog_content = "イスタバンさんのやったことを暴くと言いながら、\n自分のやっていることは、何ひとつとして「真実」じゃないでしょう！？",
  ui_story_5071_50711301_101_dialog_content = "あなたはとんでもない自惚れ屋で、自分勝手な利己主義者です。\nイスタバンさんを貶めたのも、ただの私欲に違いありません…",
  ui_story_5071_50711301_102_dialog_content = "分かったようなことを言わないでと言ったでしょう？\nこのクソガキ！",
  ui_story_5071_50711301_103_dialog_content = "あらあら、ハンスさんったら、ずいぶん汚い言葉を使うのね。",
  ui_story_5071_50711301_104_dialog_content = "うちのバージルが怖がっているじゃない。",
  ui_story_5071_50711301_105_dialog_content = "イヴァンさんは毒殺されました。",
  ui_story_5071_50711301_106_dialog_content = "僕は似たような毒を知っているんです…",
  ui_story_5071_50711301_107_dialog_content = "うるさい…うるさい、うるさい！黙りなさい！",
  ui_story_5071_50711301_108_dialog_content = "どうやら過ちを認めず、あくまで自分たちが正しいと言いたいようですね。",
  ui_story_5071_50711301_109_dialog_content = "仕方ありませんね――「バロン」に「カイド」のイヌを\n副葬品としてプレゼントしてあげましょう。",
  ui_story_5071_50711301_110_dialog_content = "出てきなさい！",
  ui_story_5071_50711301_111_dialog_content = "いよいよ正体を現したわね？",
  ui_story_5071_50711301_112_dialog_content = "僕たち、取り囲まれちゃったんですか…？",
  ui_story_5071_50711301_113_dialog_content = "PlayerName、ようやくあなたの出番が回ってきたわね。",
  ui_story_5071_50711301_114_dialog_content = "今までは見ているだけだったけど、\n今日こそ、あなたの指揮の腕を見せてもらおうじゃないの――",
  ui_story_5071_50711301_115_dialog_content = "バージルと一緒に私の後ろへ！",
  ui_story_5071_50711301_116_dialog_content = "大切なお客様と従業員を失うわけにはいかないわ！",
  ui_story_5071_50711302_1_dialog_content = "次々と増援が来るわね。キリがないわ。",
  ui_story_5071_50711302_2_dialog_content = "あなたの指揮があっても、このままじゃらちが明かない。",
  ui_story_5071_50711302_3_dialog_content = "これだけの騒ぎなら、ベセルたちもきっと気づいて、\n駆け付けてくれるはずです…",
  ui_story_5071_50711302_4_dialog_content = "それまで持たないでしょうね。",
  ui_story_5071_50711302_5_dialog_content = "私はただの商人よ。戦いは得意じゃないの。\nでも、こうなったら仕方がないわよね…",
  ui_story_5071_50711302_6_dialog_content = "PlayerName、バージル。2人はシャドウマスターを探しに行ってちょうだい。\nこっちは私に任せて。",
  ui_story_5071_50711302_7_dialog_content = "でも――",
  ui_story_5071_50711302_8_dialog_content = "信じるのよ！長年商売をやってるけど、\nあの人ほど信用できる人はいないわ。",
  ui_story_5071_50711302_9_dialog_content = "PlayerName、シャドウマスターを信じて。\n自分を信じるのよ。",
  ui_story_5071_50711302_10_dialog_content = "この混乱状態の中、シャドウマスターを探し出せるのはあなただけよ！\n絶対にあきらめちゃダメ！",
  ui_story_5071_50711302_11_dialog_content = "…分かりました。",
  ui_story_5071_50711302_12_dialog_content = "行こう、バージル。",
  ui_story_5071_50711302_13_dialog_content = "あら、あっさり立ち去るのですね。",
  ui_story_5071_50711302_14_dialog_content = "ハンスさん、そう急ぐことないでしょう？\nこっちの支払いは終わってないわよ。",
  ui_story_5071_50711302_15_dialog_content = "他人の母親を使って勝手な作り話をするなんて、\n品位に欠けるんじゃない？",
  ui_story_5071_50711302_16_dialog_content = "さすがは「赤水銀の夫人」の娘さんですね。\n性格までそっくりです。",
  ui_story_5071_50711302_17_dialog_content = "「赤水銀の夫人」のことは大好きですが、\nあなたのことはどうも最初から好きになれません。",
  ui_story_5071_50711302_18_dialog_content = "あら、私ったら何かしてしまったかしら？\nお詫びした方がいい？",
  ui_story_5071_50711302_19_dialog_content = "本当に身の程知らずですね。",
  ui_story_5071_50711302_20_dialog_content = "商売の才能はあるようですが、目利きは良くないようです。",
  ui_story_5071_50711302_21_dialog_content = "前回もずいぶんと熱心に邪魔をしてくれましたね。",
  ui_story_5071_50711302_22_dialog_content = "「前回」？あら、分からないわ。\nいつのことかしら？",
  ui_story_5071_50711302_23_dialog_content = "…それは大して重要ではありません。\nただ、あなたはそれだけでは飽き足らず、他人の夢を奪いました。",
  ui_story_5071_50711302_24_dialog_content = "「バロン」の夢を引き継ぐことができるのは、私だけです！",
  ui_story_5071_50711302_25_dialog_content = "あなたにその資格はありません！",
  ui_story_5071_50711302_26_dialog_content = "PlayerNameの言った通りね。商会の会長ともあろう人が、\nその辺のどんな子どもよりもわがままだわ。",
  ui_story_5071_50711302_27_dialog_content = "あなたは「カイド」とそっくりですね。\nそうとなれば、あなたの母親のメンツも何もどうでもいい――",
  ui_story_5071_50711302_28_dialog_content = "あなたも「カイド」も、「浮遊商会」も、\n恥知らずは皆、一緒に破滅させてあげます！",
  ui_story_5071_50711302_29_dialog_content = "この<color=#FFB400>「大陸」</color>の塵芥と消えなさい！",
  ui_story_5071_50711302_30_dialog_content = "仕方ないわね…罵るだけ罵られたことだし、\nちょっとイメージ崩しても構わないわよね？",
  ui_story_5071_50711302_31_dialog_content = "（イスタバンさん…本当にまだ生きてるんですか？どこにいるんですか？）",
  ui_story_5071_50711302_32_dialog_content = "（それとも、シェオルさんはただ僕たちを先に逃がそうとして…）",
  ui_story_5071_50711302_33_dialog_content = "（早く答えてください…でないと――）",
  ui_story_5071_50711302_34_dialog_content = "お兄ちゃん…ゴホゴホッ…け、けむい…",
  ui_story_5071_50711302_35_dialog_content = "ごめん、バージル…僕はイスタバンさんを探さなきゃならないんだ。\n君は急いで影ノ街に戻って、救援を呼んできて。",
  ui_story_5071_50711302_36_dialog_content = "ダメだよ。シェオルさんに2人で探すように言われたんだから。",
  ui_story_5071_50711302_37_dialog_content = "シャドウマスターは約束を守る人だって言ってた。\nだからボクもシャドウマスターを信じるよ。",
  ui_story_5071_50711302_38_dialog_content = "バージル…あれ！？",
  ui_story_5071_50711302_39_dialog_content = "（すごく…混乱した感情が伝わってくる…火の奥の方かな？）",
  ui_story_5071_50711302_40_dialog_content = "バージル、ここの火を抜けて行こう――",
  ui_story_5071_50711302_41_dialog_content = "あちっ――ま、待ってよ！",
  ui_story_5071_50711302_42_dialog_content = "（イスタバンさん…答えてください――）",
  ui_story_5071_50711302_43_dialog_content = "シャドウマスター…シャドウマスター！",
  ui_story_5071_50711302_44_dialog_content = "イスタバンさん――",
  ui_story_5071_50711302_45_dialog_content = "PlayerName？",
  ui_story_5071_50711302_46_dialog_content = "イスタバンさん！本当に…え！？",
  ui_story_5071_50711302_47_dialog_content = "危ない！後ろに敵がいます！",
  ui_story_5071_50711302_48_dialog_content = "いや――",
  ui_story_5071_50711302_49_dialog_content = "心配いらん。すでに片付いている。",
  ui_story_5071_50711302_50_dialog_content = "この人たち、本当に執念深いですね。\n下で待ち伏せしてたんですか？",
  ui_story_5071_50711302_51_dialog_content = "ボクたちより先に見つけてたんだね。",
  ui_story_5071_50711302_52_dialog_content = "ハンスさんの徹底した復讐の執念は、\n本当に恐ろしいです。",
  ui_story_5071_50711302_53_dialog_content = "好きにさせておこう…",
  ui_story_5071_50711302_54_dialog_content = "イスタバンさん？",
  ui_story_5071_50711302_55_dialog_content = "少し…疲れたな…",
  ui_story_5071_50711302_56_dialog_content = "辛そうですが、ケガしたんですか？",
  ui_story_5071_50711302_57_dialog_content = "ゴホッ、ゴホゴホ――",
  ui_story_5071_50711302_58_dialog_content = "僕たちと一緒に来てください。ここは煙が濃すぎます。",
  ui_story_5071_50711302_59_dialog_content = "煙ではない。",
  ui_story_5071_50711302_60_dialog_content = "煙じゃない？だったら、この黒いものは何なの？",
  ui_story_5071_50711302_61_dialog_content = "（あ、待って…この黒い霧は――あの時の…<color=#FFB400>アルトの毒</color>？）",
  ui_story_5071_50711302_62_dialog_content = "フフ、やっと気づきましたか？",
  ui_story_5071_50711302_63_dialog_content = "お前たちの命を絶たなかったのは、罪を告白させるためだ。",
  ui_story_5071_50711302_64_dialog_content = "余計なことはしない方が身のためだぞ。",
  ui_story_5071_50711302_65_dialog_content = "これは…ハンスさんからのちょっとした挨拶です。",
  ui_story_5071_50711302_66_dialog_content = "私たちと戦い始めた時から、この黒い霧はずっと空気中に漂っていたんですよ。",
  ui_story_5071_50711302_67_dialog_content = "懸命に戦えば戦うほど、それだけ多くの毒を吸い込む――",
  ui_story_5071_50711302_68_dialog_content = "今はもう完全に燃やし尽くされてしまいましたが、\nかなりの量を吸い込んだんじゃありませんか？",
  ui_story_5071_50711302_69_dialog_content = "解毒剤を渡して！",
  ui_story_5071_50711302_70_dialog_content = "「ブラックウルフ」は全滅したんじゃないの？\nどうして、その「毒」をまだ持ってるの？",
  ui_story_5071_50711302_71_dialog_content = "「毒」？ハハハ、何か誤解していませんか？",
  ui_story_5071_50711302_72_dialog_content = "それにブラックウルフのメンバーは\nイヌだけじゃありませんよ。",
  ui_story_5071_50711302_73_dialog_content = "君たちはブラックウルフといったいどんな関係が？\nアルトとハンスはいったい…",
  ui_story_5071_50711302_74_dialog_content = "いや、それはどうでもいいから、解毒剤を渡して！",
  ui_story_5071_50711302_75_dialog_content = "PlayerName、慌てるな…やつらも「黒霧」を吸っている。",
  ui_story_5071_50711302_76_dialog_content = "もし毒だというなら、弱っているやつらのほうが先に倒れる。",
  ui_story_5071_50711302_77_dialog_content = "さすがはシャドウマスター、\nこの状況でよく落ち着いていられますね。",
  ui_story_5071_50711302_78_dialog_content = "そろそろ計画を明かすタイミングじゃないのか？",
  ui_story_5071_50711302_79_dialog_content = "間抜けな道化め。おしゃべりのチャンスを逃す手はないぞ。",
  ui_story_5071_50711302_80_dialog_content = "ふん。ハンスさんに言われてやっていることです。\n私たちには共通の願いがあるんですよ。",
  ui_story_5071_50711302_81_dialog_content = "感じるでしょう？心の奥深くに眠る「興奮」、\nもしくは――「残忍」さを。",
  ui_story_5071_50711302_82_dialog_content = "改良した「黒霧」です。殺傷力こそありませんが、\nあなたの中の「興奮」を掻き立て、「野性」を呼び覚ますことができるんです。",
  ui_story_5071_50711302_83_dialog_content = "こういう時、人は誰しも自身の中に眠る、本物の自分を抑えきれなくなるものなんです。",
  ui_story_5071_50711302_84_dialog_content = "まさか、君たちの目的は――",
  ui_story_5071_50711302_85_dialog_content = "ええ、その通り！我々の目的は、その男の――\n「イスタバン」の仮面の下に眠る野獣を解き放つことです！",
  ui_story_5071_50711302_86_dialog_content = "<size=50>ヘカトン・レイクの悪魔――カイドをね！</size>",
  ui_story_5071_50711302_87_dialog_content = "あなたの奥底に眠る野獣を解き放ってあげましょう！",
  ui_story_5071_50711302_88_dialog_content = "救援に駆け付けたお仲間たちに見せてあげるんです。\n本当のあなたはどんな姿かを！",
  ui_story_5071_50711302_89_dialog_content = "あなたが愛しているふりをしてきた人たちの前で、\nもう一度その醜い狂気をさらしてみるがいい！",
  ui_story_5071_50711302_90_dialog_content = "狂ってるのは…君たちの方だよ！",
  ui_story_5071_50711302_91_dialog_content = "早く解毒剤を渡して――いや、いいよ。自分で探す…",
  ui_story_5071_50711302_92_dialog_content = "僕は光霊の精神を強制感知できるんだ。\n君たちがもし解毒剤を持ってるなら――",
  ui_story_5071_50711302_93_dialog_content = "え！？",
  ui_story_5071_50711302_94_dialog_content = "（そ、「存在」が…完全に消えた？）",
  ui_story_5071_50711302_95_dialog_content = "ちょっと！しっかりして！ねえ…",
  ui_story_5071_50711302_96_dialog_content = "…",
  ui_story_5071_50711302_97_dialog_content = "無駄だ、PlayerName――",
  ui_story_5071_50711302_98_dialog_content = "自死したんだ。",
  ui_story_5071_50711302_99_dialog_content = "おそらく十分な覚悟のうえで、ここに現れたんだろう。\n解毒剤など持っていないどころか、生きて帰るつもりもなかったはずだ。",
  ui_story_5071_50711302_100_dialog_content = "他にもいます！急いで、残りの人たちの自死も止めないと…",
  ui_story_5071_50711302_101_dialog_content = "（ど、どういうこと…？周りの火はまだ盛んに燃えてるのに、\nここにあった…生命の炎は…次々と消えていってる…）",
  ui_story_5071_50711302_102_dialog_content = "やめて！そんなことしちゃダメだよ。君たちの命も――",
  ui_story_5071_50711302_103_dialog_content = "ううっ――",
  ui_story_5071_50711302_104_dialog_content = "PlayerName、俺はうれしいぞ。",
  ui_story_5071_50711302_105_dialog_content = "お前のような若者が敵の命を惜しみ、\nその死を悲しんでいることが。",
  ui_story_5071_50711302_106_dialog_content = "だが、すまない…おそらくここにいた者はすべて…",
  ui_story_5071_50711302_107_dialog_content = "どうして…どうしてですか？自分の命を犠牲にしてまで、\nやりたいことって…",
  ui_story_5071_50711302_108_dialog_content = "もう答えは分かっているんだろう？",
  ui_story_5071_50711302_109_dialog_content = "これは…",
  ui_story_5071_50711302_110_dialog_content = "昔年の…「キャンピ家」の一族の印だ…",
  ui_story_5071_50711302_111_dialog_content = "俺が滅ぼした一族だよ。",
  ui_story_5071_50711302_112_dialog_content = "この人たち…同じようなものを持ってますね。",
  ui_story_5071_50711302_113_dialog_content = "それは「コロト家」のもの、こっちのは「ルーカス家」…\nそれから、これは「ボナー家」の印だ…",
  ui_story_5071_50711302_114_dialog_content = "なるほどな。ヘカトン・レイクで破れた頭たちも皆、\n影を残していたか――",
  ui_story_5071_50711302_115_dialog_content = "過去の影がついに暴れ出したわけだな。",
  ui_story_5071_50711302_116_dialog_content = "うっ…胸が燃えるようだ…",
  ui_story_5071_50711302_117_dialog_content = "何もかも…燃やし尽くしたい衝動が…こみあげてくる…",
  ui_story_5071_50711302_118_dialog_content = "イスタバンさん、顔が…",
  ui_story_5071_50711302_119_dialog_content = "顔が変わったか？おそらくひどいものだろうな。\n――どうだ？残忍か？",
  ui_story_5071_50711302_120_dialog_content = "（ものすごく凶悪な表情だ…血管がはっきり浮き出てるし、\n今までのイスタバンさんとはまったく…）",
  ui_story_5071_50711302_121_dialog_content = "行きましょう、イスタバンさん――",
  ui_story_5071_50711302_122_dialog_content = "解毒剤がなくても、影ノ街に戻れば、きっと…",
  ui_story_5071_50711302_123_dialog_content = "とにかく、まずは火から離れましょう！",
  ui_story_5071_50711302_124_dialog_content = "そうだな。だが…ううっ――",
  ui_story_5071_50711302_125_dialog_content = "僕が支えます！行きましょう！",
  ui_story_5071_50711302_126_dialog_content = "俺の体内に燃える炎は、ここの火よりも強烈だ。",
  ui_story_5071_50711302_127_dialog_content = "すぐに…抑えきれなくなる。",
  ui_story_5071_50711302_128_dialog_content = "ここは宿命の地だ。まるで過去が俺を追いかけてくるようだな――",
  ui_story_5071_50711302_129_dialog_content = "急いで戻れ。俺のことは放っておけ。\nお前たちを傷つけるわけにはいかない…",
  ui_story_5071_50711302_130_dialog_content = "何を言ってるんですか？",
  ui_story_5071_50711302_131_dialog_content = "そうだよ。シェオルさんのこと、助けてもらわなきゃ。",
  ui_story_5071_50711302_132_dialog_content = "約束は守りたいところだが…ううっ…",
  ui_story_5071_50711302_133_dialog_content = "やつらの言った通りだ。\n俺は今、何かを破壊したくてたまらない…",
  ui_story_5071_50711302_134_dialog_content = "急ぐんだ！これは冗談で言ってるんじゃない。俺は…",
  ui_story_5071_50711302_135_dialog_content = "ダメです！置いていけません。絶対に何か方法が――",
  ui_story_5071_50711302_136_dialog_content = "行けと言ったら行け！聞こえないのか！？",
  ui_story_5071_50711302_137_dialog_content = "俺から離れろ！",
  ui_story_5071_50711302_138_dialog_content = "うっ――もう、どうにもならない…\nそれは自分がよく分かっている。",
  ui_story_5071_50711302_139_dialog_content = "そんなことありません…",
  ui_story_5071_50711302_140_dialog_content = "どうしようもないなんてこと、ありません。",
  ui_story_5071_50711302_141_dialog_content = "（きっと何かいい方法があるはずだ。たとえ――）",
  ui_story_5071_50711302_142_dialog_content = "すみません。怒られても構いません。\n今はこれしかないんです。",
  ui_story_5071_50711302_143_dialog_content = "PlayerName、お前…",
  ui_story_5071_50711302_144_dialog_content = "バージル、僕たちのこと、ちゃんと見ててね！",
  ui_story_5071_50711302_145_option_content = "強制感知！",
  ui_story_5071_50711401_1_dialog_content = "ここがイスタバンさんの心の中？たくさんの感情が入り乱れてる…\nどうして、こんなにごちゃごちゃなんだろう…",
  ui_story_5071_50711401_2_dialog_content = "覚えている…ここは――",
  ui_story_5071_50711401_3_dialog_content = "イスタバンさんの声…？",
  ui_story_5071_50711401_4_dialog_content = "「暗潮の危機」が訪れる前、俺は「父」に代わって他の商会と連合を組み、\n白夜城の援軍と協力協定を結びに行こうとしていた。それから…",
  ui_story_5071_50711401_5_dialog_content = "イスタバンさん、どこにいるんですか？",
  ui_story_5071_50711401_6_dialog_content = "まさか…この場面をもう一度見ることになるとはな。",
  ui_story_5071_50711401_7_dialog_content = "僕の声が聞こえないのかな…？だったら、イスタバンさんを呼び覚ますことはできない。\n感情の「ほころび」を見つけるしかない。",
  ui_story_5071_50711401_8_dialog_content = "でも、イスタバンさんはどこに行ったんだろう…？",
  ui_story_5071_50711401_9_dialog_content = "ここって…闘技場かな？",
  ui_story_5071_50711401_10_dialog_content = "…すごい数だな。",
  ui_story_5071_50711401_11_dialog_content = "俺も驚いたぜ――これだけ大勢の頭が集まったのはいつ以来だ？",
  ui_story_5071_50711401_12_dialog_content = "この人たち…皆闇組織の人たちなの？",
  ui_story_5071_50711401_13_dialog_content = "これだけの人数が話し合いに応じたんだ。\nみんなの意見を聞かせてもらおうじゃないか。",
  ui_story_5071_50711401_14_dialog_content = "「老いぼれイスタバン」がいくつかの商会と手を結んで影ノ街を売ったそうじゃないか。\n<color=#FFB400>ヤツの養子が約束の証としてのケーンを渡しにここを通るらしい</color>。",
  ui_story_5071_50711401_15_dialog_content = "あのケーンを手に入れれば、連合を結んだ商会に物資を提供するよう号令して、\n武装を固めて暗鬼に抵抗できる。",
  ui_story_5071_50711401_16_dialog_content = "街の外にいる白夜城の「旦那」はヤツらが呼んだのか？\nこんな緊急時に武装して街外周に駐屯するなんて、俺たちを閉じ込める気だろう。",
  ui_story_5071_50711401_17_dialog_content = "白夜城の奴らはずっと影ノ街を占領する機会を狙ってたんだ。\nだったら、くれてやろうじゃないか！俺たちはこんな所、出て行ってやる！",
  ui_story_5071_50711401_18_dialog_content = "ここは俺たちの土地だぞ！",
  ui_story_5071_50711401_19_dialog_content = "いい加減にしろよ。俺はこんな所ごめんだ。",
  ui_story_5071_50711401_20_dialog_content = "お前、この「ヘカトン・レイク」で俺とやり合いたいのか？",
  ui_story_5071_50711401_21_dialog_content = "俺も白夜城の奴らが街に入ってくるのはごめんだ！\n暗鬼の大軍にビビッて影ノ街の資産はあきらめたんだろう？なんだってまた戻ってきたんだ？",
  ui_story_5071_50711401_22_dialog_content = "旦那どもをようやく追い払ったってのに、奴らの軍隊を駐屯させるなんて、\n自分の首を自分で締めるようなもんだろ！？",
  ui_story_5071_50711401_23_dialog_content = "それ以上言い争ったってムダだ。俺から言わせりゃ、今は手を結んで稼ごうって話だよ。\n街の貧乏人どもなんざどうでもいい。とことん搾り取って、あとは白夜城に都合つけてもらえばいいんだ！",
  ui_story_5071_50711401_24_dialog_content = "その通りだ。いずれにせよ、こっちは頭数足りてんだ。\nなんだったら、このまま連合商会を襲おうじゃねえか――",
  ui_story_5071_50711401_25_dialog_content = "おい、中には俺の金づるがいるんだぜ！",
  ui_story_5071_50711401_26_dialog_content = "ここは「ヘカトン・レイク」だ。こういうのはどうだ？\n最も原始的な方法でケーンの所有者を決めるってのは？",
  ui_story_5071_50711401_27_dialog_content = "協力しねえのかよ！？\nケーンを護送してる奴らが何人いるか分かんねえんだぞ。",
  ui_story_5071_50711401_28_dialog_content = "最後に残ったヤツが全員を率いてケーンを奪う。\n簡単なことじゃねえか。",
  ui_story_5071_50711401_29_dialog_content = "お前たちにとって、ケーンは影ノ街よりも重要だっていうのか？",
  ui_story_5071_50711401_30_dialog_content = "あの「ケーン」は「イスタバン」家の証だぞ。\n今や連合商会の証でもあるんだ…",
  ui_story_5071_50711401_31_dialog_content = "<size=45>いい加減にしろ！！</size>",
  ui_story_5071_50711401_32_dialog_content = "今の最優先事項は「カイド」の野郎とケーンがどこかってことだ。\nずいぶん待ってるが、一向に姿を現さねえ。",
  ui_story_5071_50711401_33_dialog_content = "この人たちって…当時の影ノ街の「リーダー」たちなの？\nなんて堕落した人たちなんだ…",
  ui_story_5071_50711401_34_dialog_content = "急いでイスタバンさんを見つけないと…\nもっと頑張って感知するんだ…",
  ui_story_5071_50711401_35_dialog_content = "「イスタバン」の実の息子の「バロン」はなかなかうまくやってるって話だぞ。\nすでにいくつもの商会を牛耳ってるらしい。",
  ui_story_5071_50711401_36_dialog_content = "俺たちにもうまい汁を吸わせてくれるしな。\nあいつは暗鬼の襲撃をどう思ってるんだかな。",
  ui_story_5071_50711401_37_dialog_content = "見つけた！若い頃のイスタバンさんだ！\n人目に付かない隅で――",
  ui_story_5071_50711401_38_dialog_content = "あれ？向かい側にいるのは…？",
  ui_story_5071_50711401_39_dialog_content = "カイド、聞いただろう？",
  ui_story_5071_50711401_40_dialog_content = "今のが君が救おうとしてる影ノ街の「ボス」たちだよ。",
  ui_story_5071_50711401_41_dialog_content = "バロン、話している時間はないんだ。\n通してくれ。時間は待ってくれない！",
  ui_story_5071_50711401_X41_dialog_content = "バロンさん！？でも、どうして…？\nイスタバンさんの記憶の中のバロンさんはぼんやりとしてる…",
  ui_story_5071_50711401_42_dialog_content = "あの若い城主が約束してくれたんだ。\n俺たちがこの危機を乗り越えられるよう援助してくれる！",
  ui_story_5071_50711401_43_dialog_content = "援軍も街の外まで来ているが、まだ何の動きも見せていない。\n俺たちをきちんと尊重してくれているんだ――",
  ui_story_5071_50711401_44_dialog_content = "協定にサインさえすれば、彼らは影ノ街と共に戦ってくれる。\n暗鬼の大軍に抵抗できるんだよ！",
  ui_story_5071_50711401_45_dialog_content = "今姿を現わせば、あいつらに一斉攻撃される。\nまずは2人で話し合って、どうにかここを切り抜ける方法を考えよう。",
  ui_story_5071_50711401_46_dialog_content = "ここは人目に付かないから、大丈夫だ。\n誰にも僕らの会話は聞こえない。",
  ui_story_5071_50711401_47_dialog_content = "カイド、協定を結ぶ代わりに何を約束したんだ？\n何を白夜城に差し出した？",
  ui_story_5071_50711401_48_dialog_content = "影ノ街の住民か？それとも自由貿易？もしくは、さらに高額の税金か？\n一度影ノ街を見捨ててるヤツらなんだぞ。戻ってくれば、前よりひどい状況になるに決まってる！",
  ui_story_5071_50711401_49_dialog_content = "なぜ影ノ街が白夜城に尻尾を振らなきゃいけないんだ？\n僕らの理想を忘れたのかい！？",
  ui_story_5071_50711401_50_dialog_content = "この件は「父さん」も同意している。連合を組んだ商会もだ。\nこのケーンと連名書が協定の証だ。",
  ui_story_5071_50711401_51_dialog_content = "全員の意見なんだよ。",
  ui_story_5071_50711401_52_dialog_content = "影ノ街の平民たちは、ずっと白夜城と各大商会に虐げられてきた――\n君は彼らの意見を聞いたのか？",
  ui_story_5071_50711401_53_dialog_content = "暗潮は明日にも影ノ街に到達するそうじゃないか。\nそれなのに、どの勢力も自分のことばかりで団結できていない。",
  ui_story_5071_50711401_54_dialog_content = "父さんと商会は勝手に白夜城に連絡して自分たちを守り、\n「キャンピ家」とその盟友は影ノ街から逃れる切符を高額で売りさばいてる…",
  ui_story_5071_50711401_55_dialog_content = "貧しい人たちは戦う能力もないのに、逃げることさえできない。\nただ死ぬのを待つばかりだ。",
  ui_story_5071_50711401_56_dialog_content = "俺たちも一緒に街を守るさ！",
  ui_story_5071_50711401_57_dialog_content = "それは君たちの幻想だよ。多くの人が街を離れたいと望んでる。\nでも、それを狙って強盗を働いているヤツがいるらしいじゃないか。",
  ui_story_5071_50711401_58_dialog_content = "能力のあるヤツは皆、道端の弱者に目を向けようとしない。\n僕らの影ノ街はなぜ、こんなふうになってしまったんだ…",
  ui_story_5071_50711401_59_dialog_content = "でも幸い、ここにいる闇組織のヤツらは純粋な影ノ街の出身だ。\n少し刺激すれば、その血の中に流れる狂暴さを思い出す。",
  ui_story_5071_50711401_60_dialog_content = "だから、裏でヤツらを動かして、ここに集めたんだよ。\n情報を流し、利益で誘えば、必ず食いついてくる。",
  ui_story_5071_50711401_61_dialog_content = "お前…何をするつもりだ？",
  ui_story_5071_50711401_62_dialog_content = "カイド、話したことがあったよね？\n僕はずっと自分の勢力を育ててきたんだ。",
  ui_story_5071_50711401_63_dialog_content = "暗鬼の襲撃に乗じて、影ノ街の膿を取り除くんだ。",
  ui_story_5071_50711401_64_dialog_content = "こいつらさえいなくなれば、罪のない人達を連れて、\nすんなり影ノ街を離れることができるだろう？",
  ui_story_5071_50711401_65_dialog_content = "僕と一緒に膿を取り除くことこそ、真の意味で影ノ街のためになるんだ。\n白夜城のクズどもに助けを求めることじゃない。",
  ui_story_5071_50711401_66_dialog_content = "バロン、なぜだ…なぜ、変わってしまったんだ…",
  ui_story_5071_50711401_67_dialog_content = "内輪もめをあおる力があるのに、\nなぜ彼らを説き伏せ、一緒に暗鬼と戦うとしない？",
  ui_story_5071_50711401_68_dialog_content = "今のお前は、今まで影ノ街の生き血を吸い続けてきた貴族ども\nと何の違いがあるんだ？",
  ui_story_5071_50711401_69_dialog_content = "こいつらは影ノ街を堕落させた張本人だ。\n生かしておいたところで被害者を増やすだけだよ。",
  ui_story_5071_50711401_70_dialog_content = "ようやくチャンスが巡ってきたんだ。カイド、僕と一緒にヤツらを片付けよう。\nそして、罪のない人達を連れて、街を去ろう…",
  ui_story_5071_50711401_71_dialog_content = "こいつらを消さなければ、影ノ街の弱者たちは逃げられない。",
  ui_story_5071_50711401_72_dialog_content = "…逃げて、どうするんだ？",
  ui_story_5071_50711401_73_dialog_content = "影ノ街が完全に白夜城の手に落ち、\n将来ここに住む人たちが俺たちと同じような目に遭うんだぞ。",
  ui_story_5071_50711401_74_dialog_content = "俺のような「悪魔の子」が他人から唾を吐かれ続ける影の中に生まれ――",
  ui_story_5071_50711401_75_dialog_content = "同じことが繰り返されるんだ。",
  ui_story_5071_50711401_76_dialog_content = "ようやく白夜城と合意できたんだ。\n俺は何としても、この対等な対話の機会を逃すわけにはいかない…",
  ui_story_5071_50711401_77_dialog_content = "君を説得することは無理みたいだね…",
  ui_story_5071_50711401_78_dialog_content = "<size=45><color=#FFB400>皆、聞いてくれ。カイドはここにいるぞ！</color></size>",
  ui_story_5071_50711401_79_dialog_content = "（突如静まりかえる――）",
  ui_story_5071_50711401_80_dialog_content = "バロン！？お前…",
  ui_story_5071_50711401_81_dialog_content = "聞こえるかい？ヤツらがこっちへ向かってくる。\n君はもう戦うしかないんだよ。僕の代わりに影の中の「汚れた血」を取り除くんだ。",
  ui_story_5071_50711401_82_dialog_content = "心配しなくていい。僕も「共に戦う」よ。\n僕の雇った助っ人たちも一緒にね。",
  ui_story_5071_50711401_83_dialog_content = "おい、慌てるな！手を結ぶ余地はまだある！\nあの小僧がケーンを差し出すなら、俺たちが物資を提供し、街を防御すればいい！",
  ui_story_5071_50711401_84_dialog_content = "うがああ！！だ、誰だ――",
  ui_story_5071_50711401_85_dialog_content = "襲われた奴がいるぞ！クソッ、案の定よからぬことしか考えてなかったか！\n協力なんて口先だけだったんだ！",
  ui_story_5071_50711401_86_dialog_content = "まずは「悪魔の子」を殺せ！！\nケーンは後でゆっくり奪い合えばいいさ！",
  ui_story_5071_50711401_87_dialog_content = "どけ、お前たちの相手をしている時間はない。",
  ui_story_5071_50711401_88_dialog_content = "俺の獲物だ！",
  ui_story_5071_50711401_89_dialog_content = "どけと言ってるんだ――",
  ui_story_5071_50711401_90_dialog_content = "カイド、戦わなければ、君が死ぬんだよ。\nそうなれば、夢も終わりだ。",
  ui_story_5071_50711401_91_dialog_content = "クソッ――どけ！！",
  ui_story_5071_50711401_92_dialog_content = "目先のことしか考えない愚か者め！\n俺の邪魔をするな！",
  ui_story_5071_50711401_93_dialog_content = "刺さったぞ！急げ！手を貸してくれ――",
  ui_story_5071_50711401_94_dialog_content = "うおおお！！",
  ui_story_5071_50711401_95_dialog_content = "クズども、これが見たいんだろ？\nだったら見せてやる、来い！",
  ui_story_5071_50711401_96_dialog_content = "やめて、今すぐ手を止めてください！\nそんな戦い、何の意味もない――",
  ui_story_5071_50711401_97_dialog_content = "全員、灰と化せ――！！",
  ui_story_5071_50711401_98_dialog_content = "誰も僕の話を聞いてない…",
  ui_story_5071_50711401_99_dialog_content = "なんて残酷な戦いなんだ…イスタバンさんにこんな狂暴な一面があったなんて…\nこれは暴走してるの？",
  ui_story_5071_50711401_100_dialog_content = "まさか…こんなふうに暴走して、\n自分の友だちまで殺めちゃったってこと？",
  ui_story_5071_50711401_101_dialog_content = "い、いや、そうじゃない。僕は何を考えてるんだ…\nイスタバンさんの精神に「ほころび」が出来た、今だ！",
  ui_story_5071_50711401_102_dialog_content = "どうか僕の声を聞いてください。\nいつものイスタバンさんに戻ってください――",
  ui_story_5071_50711402_1_dialog_content = "お頭たちが全員…",
  ui_story_5071_50711402_2_dialog_content = "見ろ！白夜城の軍隊が動いたぞ！？\nこっちへ…来るのか？",
  ui_story_5071_50711402_3_dialog_content = "2人だけになったね…",
  ui_story_5071_50711402_4_dialog_content = "カイド、おめでとう。ヘカトン・レイクの壮挙、再びだ。",
  ui_story_5071_50711402_5_dialog_content = "うおおお――！！",
  ui_story_5071_50711402_6_dialog_content = "バロン！どけ…俺はケーンを持って、\n協定を結びに行かなきゃならないんだ…",
  ui_story_5071_50711402_7_dialog_content = "これだけのことがあったのに、\nまだ白夜城に幻想を抱いてるのかい？",
  ui_story_5071_50711402_8_dialog_content = "カイド、僕が君に話した<color=#FFB400>夢</color>のこと、\n覚えてるかい？",
  ui_story_5071_50711402_9_dialog_content = "僕はもう夢の実現の一歩手前まで来たんだ。「ケーン」を持って僕に付いてきてくれ。\n連合商会に号令をかけ、弱者全員を連れて、ここを離れるんだ。",
  ui_story_5071_50711402_10_dialog_content = "僕たちは新しい家族になるんだ。\n互いに助け合って、同じく故郷を失った人達を守るんだよ。",
  ui_story_5071_50711402_11_dialog_content = "この<color=#FFB400>大陸</color>で、平等に楽しく暮らし、\nあらゆる場所へ出向いて、あらゆる人達と交易するんだ――",
  ui_story_5071_50711402_12_dialog_content = "（大陸各地を旅する商会…まさか、<color=#FFB400>大陸商会</color>の前身ってこと？\nでも、自由な交易って理念は<color=#FFB400>浮遊商会</color>と期せずして一致してる！）",
  ui_story_5071_50711402_13_dialog_content = "（バロンさんの夢は…シェオルさんと同じだったの？\nどうりでハンスさんは他人の夢を盗んだって言ってたわけだね）",
  ui_story_5071_50711402_14_dialog_content = "だが…「父さん」はどうするんだ？\nこの地を離れることを望まない商会の者たちはどうするんだ？",
  ui_story_5071_50711402_15_dialog_content = "闇組織に入るしかなかった子どもたちは…どうなるんだ？\nもし、子どもたちもここを離れたくないと言ったら――",
  ui_story_5071_50711402_16_dialog_content = "…父さんたちが離れたがらないのは、事業を捨てきれないからだ。\nこの街を「愛してる」からとは限らない。",
  ui_story_5071_50711402_17_dialog_content = "多くの人がこの街にすべてを奪われた…ここから離れたいんだ。\nその人たちを無理やり留めて、腐った影ノ街のために死ねと言うのかい？",
  ui_story_5071_50711402_18_dialog_content = "お前は道端の子どもたちのために涙を流す。\nだが、商会で働く者たちはその子どもたちの親や家族かもしれないんだぞ！",
  ui_story_5071_50711402_19_dialog_content = "故郷とのつながりはお前の思っているよりもずっと強い。\n断ち切ることなど、誰にもできやしない。",
  ui_story_5071_50711402_20_dialog_content = "人々は故郷を…時に愛し、時に憎む。\nだが、永遠に見捨てはしない――",
  ui_story_5071_50711402_21_dialog_content = "俺は残る…「父さん」と一緒に…\n俺たちは俺たちのやり方で故郷を守る。",
  ui_story_5071_50711402_22_dialog_content = "暗鬼の大軍が今にも押し寄せてくるんだよ。白夜城の軍隊も迫ってきている――\nもたもたしていれば、もっと深刻な混乱に陥る。",
  ui_story_5071_50711402_23_dialog_content = "ここを守ったところで、死なないなんて保証はないんだ！\n白夜城のヤツらは信用できない！",
  ui_story_5071_50711402_24_dialog_content = "少なくとも俺たちは…故郷のために死ぬんだ。",
  ui_story_5071_50711402_25_dialog_content = "ずっと前から、「父さん」とは反りが合わなかった…",
  ui_story_5071_50711402_26_dialog_content = "僕は君みたいに父さんに認められもしなかった。\n今思えば、君こそ本当の「イスタバンの子」なのかもしれないね。",
  ui_story_5071_50711402_27_dialog_content = "でも、君は違うだろう？僕の夢を応援してくれた時からずっと、\n君だけは本当に僕を理解してくれていた。",
  ui_story_5071_50711402_28_dialog_content = "僕らの夢のために、一緒に行こう――",
  ui_story_5071_50711402_29_dialog_content = "俺たちの夢はこの街を変えることだ！\n俺たちがあきらめてしまったら、夢はただの絵空事になってしまう！",
  ui_story_5071_50711402_30_dialog_content = "ようやく商会のやつらも連合を組むことの意味を理解して、団結できたんだ。\n今ここであきらめるわけにはいかない…",
  ui_story_5071_50711402_31_dialog_content = "そんなの幻想だよ、カイド――この街のヤツらは、\n利益しか顧みない。内輪で争うしか能のないヤツらだ。",
  ui_story_5071_50711402_32_dialog_content = "闇組織の存在は確かに人々の絶望の元だ。それは分かっている。\nだが、やつらだって救いようがないわけじゃない。",
  ui_story_5071_50711402_33_dialog_content = "多くの者がただ選べなかっただけだ…だが、この俺でさえ光に満ちた夢のために力を尽くしている。\n他にもきっと賛同するやつらがいるはずだ！",
  ui_story_5071_50711402_34_dialog_content = "俺たちさえあきらめなければ…いつかは「種」が芽を出すんだ。",
  ui_story_5071_50711402_35_dialog_content = "俺たちじゃなくてもいい。\n将来、いつの日か必ず、俺たちの夢をかなえるやつが現れる。",
  ui_story_5071_50711402_36_dialog_content = "カイド…君はずっと「今」にもがき続けてきたよね。\nチェスでも無茶して危険を冒してばかり、攻めることしか考えない。",
  ui_story_5071_50711402_37_dialog_content = "悪を懲らしめるにしても、いつだって目の前のすべてをその場で潰してきた。\nいつから…そんなふうに未来を見据えるようになったんだい？",
  ui_story_5071_50711402_38_dialog_content = "影ノ街の未来は俺たちの手でしか築けない。だが、それは友人を作ることを拒むとは違う。\n俺たちだけじゃ戦えないんだ…白夜城に応援を求めるべきだろう？",
  ui_story_5071_50711402_39_dialog_content = "バロン、お前が俺に友人の意味を教えてくれたんだ…\nなのに、なぜ…なぜ、そんなふうになってしまったんだ？",
  ui_story_5071_50711402_40_dialog_content = "白夜城は影ノ街に深い影を落とし続けて来た悪の根源だ…\n自分たちは光明を謳いながら、その影で僕たちの一生を縛っている。",
  ui_story_5071_50711402_41_dialog_content = "君がうらやましいよ…そんな簡単に恨みを捨て、\n何のわだかまりもなく前に進めるんだから。",
  ui_story_5071_50711402_42_dialog_content = "でも、僕は許せない。「汚れ」と妥協することなんてできないよ。\n不公平を見て見ぬふりするなんて、できない。",
  ui_story_5071_50711402_43_dialog_content = "僕は…身近な人達を守るだけで、もう精いっぱいなんだ。",
  ui_story_5071_50711402_44_dialog_content = "バロン…",
  ui_story_5071_50711402_45_dialog_content = "カイド、君はチェスで僕に勝てたことは一度もなかった。\nそれなのになぜ、白夜城のヤツらと駆け引きできると思うんだい…？",
  ui_story_5071_50711402_46_dialog_content = "あいつらはインチキがお得意なんだ。",
  ui_story_5071_50711402_47_dialog_content = "カイド、お願いだ。「ケーン」を僕に渡して、一緒に来てくれ…",
  ui_story_5071_50711402_48_dialog_content = "それは…できない。",
  ui_story_5071_50711402_49_dialog_content = "僕らの結末は、こんなはずじゃない。\nヘカトン・レイクで決着をつけなきゃならないなんて…",
  ui_story_5071_50711402_50_dialog_content = "まさか――君と刃を交える日が来るなんてね。\nでも…僕は…",
  ui_story_5071_50711402_51_dialog_content = "ここで何が起こったのだ？\n影ノ街側の代表カイド殿はどちらかな？",
  ui_story_5071_50711402_52_dialog_content = "！？",
  ui_story_5071_50711402_53_dialog_content = "中には入れねえよ！",
  ui_story_5071_50711402_54_dialog_content = "君たちと話している時間はない。カイド殿はどこにいる？",
  ui_story_5071_50711402_55_dialog_content = "白夜城のヤツが堂々と軍を率いて、故郷に侵入した！",
  ui_story_5071_50711402_56_dialog_content = "追い払え！",
  ui_story_5071_50711402_57_dialog_content = "影ノ街のドブネズミどもが、いい気になるな。",
  ui_story_5071_50711402_58_dialog_content = "こやつらを倒して、カイド殿を探せ。\nカイド殿を死なせてはならん。",
  ui_story_5071_50711402_59_dialog_content = "クソッ、白夜城の野郎どもめ！うわあっ――",
  ui_story_5071_50711402_60_dialog_content = "あなたがカイド殿かな？なかなか現れないものだから、我々は…",
  ui_story_5071_50711402_61_dialog_content = "カイド、これが君の「後手」か！？",
  ui_story_5071_50711402_62_dialog_content = "なんて堕落だ！卑劣すぎる！",
  ui_story_5071_50711402_63_dialog_content = "退がっていただこう――勝手に影ノ街に入ってもらっては困る。",
  ui_story_5071_50711402_64_dialog_content = "カイド殿、この度の協定に対する認識が甘いようですな。\n今の最優先事項は協定ですぞ。",
  ui_story_5071_50711402_65_dialog_content = "退がれ！",
  ui_story_5071_50711402_66_dialog_content = "影ノ街を売ったな！君は僕らの故郷を汚したんだ！",
  ui_story_5071_50711402_67_dialog_content = "影ノ街の者よ！言葉を慎みたまえ！",
  ui_story_5071_50711402_68_dialog_content = "故郷は汚させない！",
  ui_story_5071_50711402_69_dialog_content = "攻撃してはいけない――バロン、武器を下ろせ！",
  ui_story_5071_50711402_70_dialog_content = "退がれ！退がるのだ！くっ…こやつの光力術――",
  ui_story_5071_50711402_71_dialog_content = "長官がやられた！反撃しろ！",
  ui_story_5071_50711402_72_dialog_content = "いつも人を小馬鹿にして…そう簡単にここから退けると思うな！\n大人しく――",
  ui_story_5071_50711402_73_dialog_content = "（大変だ！白夜城の兵士たちは本当に殺す気だ…早く止めなきゃ！）",
  ui_story_5071_50711402_74_dialog_content = "（まずい…僕の意識じゃ止められない――）",
  ui_story_5071_50711402_75_dialog_content = "<color=#e8d9bb>ドサッ――</color>",
  ui_story_5071_50711402_76_dialog_content = "お、お前ら…カイド…",
  ui_story_5071_50711402_77_dialog_content = "<size=40>バロン！！</size>",
  ui_story_5071_50711402_78_dialog_content = "<size=50>うああああああ――！！</size>",
  ui_story_5071_50711402_79_dialog_content = "出て行け！全員、出て行け！！",
  ui_story_5071_50711402_80_dialog_content = "急げ、退くんだ！こいつ、おかしくなったぞ。\n協定はどうでもいい、急いで退くんだ！",
  ui_story_5071_50711402_81_dialog_content = "退け！急げ――",
  ui_story_5071_50711402_82_dialog_content = "バロン…お前…",
  ui_story_5071_50711402_83_dialog_content = "カイド…影ノ街では、何をやっても最悪の結果しか出ないみたいだね。\nこんな状態で、どうやって街を救えばいいんだ？",
  ui_story_5071_50711402_84_dialog_content = "白夜城の影がまた射してきたよ…抗うのを止めたら…\n影ノ街は「浄化」できない…",
  ui_story_5071_50711402_85_dialog_content = "不公平に苦しみ続けてきた人達を…\nいったい誰が救い出してあげられるんだ…",
  ui_story_5071_50711402_86_dialog_content = "大丈夫だ、バロン！できるさ。\nもう少し時間をかければ、俺たち2人でこの危機を乗り越えれば…",
  ui_story_5071_50711402_87_dialog_content = "お前の夢は絶対にかなう。\nこの街は生き生きと、活力あふれる街に生まれ変われる！",
  ui_story_5071_50711402_88_dialog_content = "あはは…君は本当に信じてるんだね…そうか…",
  ui_story_5071_50711402_89_dialog_content = "父さんには言わないでくれ…\n僕が何をしたか知ったら、父さんが恥をかく…悲しませたくないんだ…",
  ui_story_5071_50711402_90_dialog_content = "…分かった。",
  ui_story_5071_50711402_91_dialog_content = "もっと近くに…カイド…話があるんだ…",
  ui_story_5071_50711402_92_dialog_content = "ゲホッ、ゴホゴホッ…僕らは本当に純粋な影ノ街の者なんだね。\n僕らの心の奥底には、抗えない狂暴さが潜んでる…",
  ui_story_5071_50711402_93_dialog_content = "ここまで来たら、僕には君を止められそうにないよ。\nただ、これだけは約束してほしいんだ…",
  ui_story_5071_50711402_94_dialog_content = "これからも影ノ街のために、手段を選ばず、\nすべてを犠牲にしてでも…影ノ街を守ってくれ…",
  ui_story_5071_50711402_95_dialog_content = "分かった…約束する。",
  ui_story_5071_50711402_96_dialog_content = "…兄弟。",
  ui_story_5071_50711402_97_dialog_content = "…",
  ui_story_5071_50711402_98_dialog_content = "待ってください…これって、つまり…\nイスタバンさんがやったんじゃなかったんですね？",
  ui_story_5071_50711402_99_dialog_content = "…白夜城の兵は騒ぎを聞きつけ、\n協定を確実に結ぼうと影ノ街に入ってきたんだ。",
  ui_story_5071_50711402_100_dialog_content = "常に上に立ってきた彼らは俺たちを尊重することを知らなかった。そういう俺たちも\n神経質になりすぎていた――代償を払って初めて、協力の仕方を学んだ。",
  ui_story_5071_50711402_101_dialog_content = "だが、それで俺の罪が洗われるのか？",
  ui_story_5071_50711402_102_dialog_content = "ある賢者が言った――「言葉の力は魂に響く」と。\n俺は…",
  ui_story_5071_50711402_103_dialog_content = "バロンの言葉から抜け出せないでいる。",
  ui_story_5071_50711501_1_dialog_content = "白夜城との連盟を確実なものにするため、俺はバロンの死について語らなかった――\nいずれにせよ、俺のせいであることは変わらない。",
  ui_story_5071_50711501_2_dialog_content = "でも、真相は違います…",
  ui_story_5071_50711501_3_dialog_content = "「イスタバンの子」になる時誓った。決して家族同士で争うことなく、\n家族の利益を害することはしないと…",
  ui_story_5071_50711501_4_dialog_content = "だが結局、すべての誓いを破ってしまった。\n俺はもう「父さん」に合わせる顔がない。",
  ui_story_5071_50711501_5_dialog_content = "それでも、「父さん」は亡くなる時、すべてを俺に託した。\nそうして俺は「イスタバン」になったんだよ。",
  ui_story_5071_50711501_6_dialog_content = "イスタバンさん…",
  ui_story_5071_50711501_7_dialog_content = "俺は影になると決めた――",
  ui_story_5071_50711501_8_dialog_content = "暗闇に身を隠し、幾多の影となり、\n手段を選ばず、影ノ街を守り続ける。",
  ui_story_5071_50711501_9_dialog_content = "過去の真相を深く葬り、二度と思い返さない…\nだが、罪はいまだに悪夢となって俺を苦しめる。",
  ui_story_5071_50711501_10_dialog_content = "生き残った者の払うべき代償だ。実に公平じゃないか。",
  ui_story_5071_50711501_11_dialog_content = "違います…それは、不公平です。",
  ui_story_5071_50711501_12_dialog_content = "影ノ街の未来のためなら、俺はすべてを犠牲にすることもいとわない。\nそして、ずっとそうしてきた。",
  ui_story_5071_50711501_13_dialog_content = "すべてを背負い、同時に「すべて」を傲慢にも犠牲にする。\nバロンは…俺が払った最初の「代償」だ。",
  ui_story_5071_50711501_14_dialog_content = "イスタバンさんは間違っていません…自分でも分かってるんですよね？\nそれなのに自分で自分を罰することを選んだ…",
  ui_story_5071_50711501_15_dialog_content = "…すべて影ノ街のためにしたことだ。どんな結果も受け入れる。\nそこに正しい、正しくないなどという基準はないんだ。影ノ街を守るためならな。",
  ui_story_5071_50711501_16_dialog_content = "いつかきっと、この暗闇の上に立つ者が現れる。\nその時になれば、俺たちの夢を引き継ぐ者も出てくるだろう。そう信じてきた。",
  ui_story_5071_50711501_17_dialog_content = "その希望が見えてきたことを喜んでいるよ。",
  ui_story_5071_50711501_18_dialog_content = "本当にそう思っているなら、\nどうして、この記憶の中に閉じ込もっているんですか…？",
  ui_story_5071_50711501_19_dialog_content = "なぜか、か…真夜中にはっと目覚める時、\n俺も時々そう自分に問いかけてきた。",
  ui_story_5071_50711501_20_option_content = "申し訳なく思ってるんですね",
  ui_story_5071_50711501_21_dialog_content = "俺が己を責めていると言いたいのか？",
  ui_story_5071_50711501_22_option_content = "後悔してるんですね",
  ui_story_5071_50711501_23_dialog_content = "後悔…？俺が後悔していると？",
  ui_story_5071_50711501_24_dialog_content = "本当は昔のことを悔やんでるんじゃないですか？",
  ui_story_5071_50711501_X24_dialog_content = "だから、ずっとバロンさんの姿を…思い出せずにいるんですよね。",
  ui_story_5071_50711501_X25_dialog_content = "…",
  ui_story_5071_50711501_25_dialog_content = "本当に真相を話そうと思ったことはないんですか？",
  ui_story_5071_50711501_26_dialog_content = "真相とは時として鋭い武器となる。\nたとえ表面的な平和のためだとしても、俺はこのウソを貫き通す。",
  ui_story_5071_50711501_27_dialog_content = "後悔はしていない。",
  ui_story_5071_50711501_28_dialog_content = "本当は自分でも分かっているんですよね…\nずっと無念と後悔にさいなまれながら生きてきたこと…",
  ui_story_5071_50711501_29_dialog_content = "真相をバロンさんやお父さんに伝えられなかったことを、\nずっと無念に思ってきたはずです。",
  ui_story_5071_50711501_30_dialog_content = "お前は鋭いな。だが、2人とももう逝ってしまった。\n永遠に和解の日は来ない。",
  ui_story_5071_50711501_31_dialog_content = "だから、自分を罰して…悪夢の中に囚われているんですね…",
  ui_story_5071_50711501_32_dialog_content = "長い間、影を演じすぎたんだ。時に区別がつかなくなるんだよ――\n自分が影になったのか、影が自分を演じているのか。",
  ui_story_5071_50711501_33_dialog_content = "俺は本当に十分やったのだろうか、と…",
  ui_story_5071_50711501_34_dialog_content = "影ノ街に対して、\nイスタバンさんはもう十分すぎるほど尽くしています…",
  ui_story_5071_50711501_35_dialog_content = "あの時俺が迷わず、すぐにバロンを止めていたら、\nこんなことにはならなかったのかもしれないな。",
  ui_story_5071_50711501_36_dialog_content = "あいつを「代償」にしようと思ったことは一度もなかった。",
  ui_story_5071_50711501_37_dialog_content = "ハハ…こんなことを考えるとは、俺はまだカイドのままのようだ。\n今でも俺はお前の許しを得たいと思っているんだよ、兄弟…",
  ui_story_5071_50711501_38_dialog_content = "ハハ――",
  ui_story_5071_50711501_39_dialog_content = "ハハッ、ハハハハ――",
  ui_story_5071_50711501_40_dialog_content = "イスタバンさん？",
  ui_story_5071_50711501_41_dialog_content = "どうやら、俺も老いたようだな。\n若い頃のあの気迫を失ってしまったか？",
  ui_story_5071_50711501_42_dialog_content = "やれやれ…感傷に溺れるとはな。",
  ui_story_5071_50711501_43_dialog_content = "イスタバンさん！\nいつものイスタバンさんに戻ったんですね！",
  ui_story_5071_50711501_44_dialog_content = "いや、まだだ！",
  ui_story_5071_50711501_45_dialog_content = "内なる炎が暴れ出そうとしている！",
  ui_story_5071_50711501_46_dialog_content = "（イスタバンさんの感情が落ち着いてきてる…\nでも、何だかかすかに…）",
  ui_story_5071_50711501_47_dialog_content = "お前がいなかったら、忘れるところだった。\n過去の影は、俺に同じ轍を踏むなと忠告していたんだ。",
  ui_story_5071_50711501_48_dialog_content = "もう迷うわけにはいかない！",
  ui_story_5071_50711501_49_dialog_content = "やつらが俺の野性を呼び覚まそうとするなら、\nこの抑えられぬ怒りの炎を見せつけてやろうじゃないか！",
  ui_story_5071_50711501_50_dialog_content = "その通りです。イスタバンさん、早く目を覚ましてください！",
  ui_story_5071_50711501_51_dialog_content = "（成功したのかな？身体が…意識が遠のいていく…\n僕の意識がここから抜け出していくのが分かる…）",
  ui_story_5071_50711501_52_dialog_content = "イスタバンさん…外で待ってます…",
  ui_story_5071_50711501_53_dialog_content = "感謝する、善良なる空の末裔よ。",
  ui_story_5071_50711501_54_dialog_content = "俺も…",
  ui_story_5071_50711501_55_dialog_content = "カイド。",
  ui_story_5071_50711501_56_dialog_content = "！？",
  ui_story_5071_50711501_57_dialog_content = "本当に…久しぶりだね。",
  ui_story_5071_50711501_58_dialog_content = "バロンなのか…？",
  ui_story_5071_50711501_59_dialog_content = "カイド…質問があるんだ。もう一度答えてほしい。",
  ui_story_5071_50711501_60_dialog_content = "僕の目を見て、偽りなく答えてほしいんだ。",
  ui_story_5071_50711501_61_dialog_content = "…",
  ui_story_5071_50711501_62_dialog_content = "影ノ街を救うためなら、どんな代償でも払うかい？",
  ui_story_5071_50711501_63_dialog_content = "…今さら聞くまでもあるか？",
  ui_story_5071_50711501_64_dialog_content = "すべて捧げる！何もかも！",
  ui_story_5071_50711501_65_dialog_content = "本当に…カイドらしい答えだね…",
  ui_story_5071_50711501_66_dialog_content = "だったら、行くといい！\n影ノ街の敵に君の覚悟を見せつけてやるんだ！",
  ui_story_5071_50711501_67_dialog_content = "<color=#e8d9bb>ボンッ――</color>",
  ui_story_5071_50711501_68_dialog_content = "ハハ、アハハ…自分でもここまで持つとは思わなかったわ。",
  ui_story_5071_50711501_69_dialog_content = "飛空艇もそろそろ完全に爆発して消えますよ。\nまだ「カイド」の帰りを待っているのですか？",
  ui_story_5071_50711501_70_dialog_content = "そうよ。PlayerNameと約束したのよ。\nPlayerNameはシャドウマスターを連れて、戻ってくるわ。",
  ui_story_5071_50711501_71_dialog_content = "「カイド」はそもそもウソ偽りで固められた男…\n生きていたところで、あなたを助けに来るはずもありませんよ。",
  ui_story_5071_50711501_72_dialog_content = "あの男の正体を知れば、あなたも絶望するはずです。",
  ui_story_5071_50711501_73_dialog_content = "ハンスさん、遅くなりました――",
  ui_story_5071_50711501_74_dialog_content = "ここに来て、まだ増援がくるの？",
  ui_story_5071_50711501_75_dialog_content = "しかも暗鬼を操ってコマにしている？\nこれは…なかなかまずいわね。",
  ui_story_5071_50711501_76_dialog_content = "一斉にかかりなさい。休む暇を与えてはいけませんよ！",
  ui_story_5071_50711501_77_dialog_content = "シャドウマスター…",
  ui_story_5071_50711501_78_dialog_content = "<color=#e8d9bb>ボンッ――</color>",
  ui_story_5071_50711501_79_dialog_content = "何事？",
  ui_story_5071_50711501_80_dialog_content = "急にものすごい爆発が…",
  ui_story_5071_50711501_81_dialog_content = "な、なな、なんだ、あれは？",
  ui_story_5071_50711501_82_dialog_content = "火の中に、人が…ま、まさか――",
  ui_story_5071_50711501_83_dialog_content = "シャドウマスター！！",
  ui_story_5071_50711501_84_dialog_content = "幾千の傷痕…恐ろしい青い烈炎――",
  ui_story_5071_50711501_85_dialog_content = "<size=45>ヘカトン・レイクの悪魔だ！！</size>",
  ui_story_5071_50711501_86_dialog_content = "不敗の…あいつは不敗神話を誇る悪魔だ…\nあんなの相手にできやしない…",
  ui_story_5071_50711501_87_dialog_content = "逃げることは許しません。何を怖気づいているのです？\n私たちはあの男に復讐しにきたのです！",
  ui_story_5071_50711501_88_dialog_content = "今はすでに年老いた悪魔…\nこれだけの人数を倒せるはずありません…",
  ui_story_5071_50711501_89_dialog_content = "ここまでやっておいて、今さら逃げるつもり？",
  ui_story_5071_50711501_90_dialog_content = "に、逃がさないよ！",
  ui_story_5071_50711501_91_dialog_content = "シャドウマスター…遅刻よ。やはり歳には勝てないのかしら？",
  ui_story_5071_50711501_92_dialog_content = "すまなかった、シェオル。お前の言う通りだ。\n俺は確かに年老いた仮面の中に閉じこもっていた。",
  ui_story_5071_50711501_93_dialog_content = "今こそ元の影を取り戻すべきだな。",
  ui_story_5071_50711501_94_dialog_content = "「エヴァ」…あの時は俺が迷ったせいで、\n俺たちは「バロン」を失った。",
  ui_story_5071_50711501_95_dialog_content = "今度は迷わない――敵がお前であろうとな。",
  ui_story_5071_50711501_96_dialog_content = "黙りなさい！\nあんたに「バロン」の名を口にする資格はないわ！",
  ui_story_5071_50711501_97_dialog_content = "事件が起こった時、俺には分かった。\nお前が企てたことだとな。",
  ui_story_5071_50711501_98_dialog_content = "俺に復讐するのは構わん。\nだが、罪のない者を巻き込むべきじゃなかった。",
  ui_story_5071_50711501_99_dialog_content = "黙れ黙れ黙れっ！あんたに私の苦しみが分かるものかっ！",
  ui_story_5071_50711501_100_dialog_content = "この日のために、私がどれだけ望まぬことに手を染めたと思ってるの！？",
  ui_story_5071_50711501_101_dialog_content = "資金を得るために、忌々しい贋作を描き続けて…\nあんたの本性を暴くために、吐き気のする実験を繰り返してきた…",
  ui_story_5071_50711501_102_dialog_content = "これだけの人を集めて、力を結集させたのも、\n全部あんたに復讐するためよ！",
  ui_story_5071_50711501_103_dialog_content = "君の計画は失敗だよ。イスタバンさんの心は晴れ晴れしてるんだ。\n我を忘れたりしない！",
  ui_story_5071_50711501_104_dialog_content = "いいわ！やってやろうじゃないの…\n今でもまだ偽りを貫き、狂気を抑えこめるっていうなら…",
  ui_story_5071_50711501_105_dialog_content = "私の手であんたを葬ってあげるわ！\n「バロン」への手向けにしてやる！",
  ui_story_5071_50711501_106_dialog_content = "全員、かかりなさい！",
  ui_story_5071_50711501_107_dialog_content = "魂を売ったクズどもめ。\nお前はこんなやつらしか集められないのか？",
  ui_story_5071_50711501_108_dialog_content = "うわあああ――",
  ui_story_5071_50711501_109_dialog_content = "俺たちを見くびるなよ、「エヴァ」！",
  ui_story_5071_50711501_110_dialog_content = "ま、まったく相手にならない…逃げろ！",
  ui_story_5071_50711501_111_dialog_content = "あの時影ノ街で、俺とバロンが消し去った暗闇は、\nお前の見たものよりもずっと深かった。",
  ui_story_5071_50711501_112_dialog_content = "ば、化け物だ…",
  ui_story_5071_50711501_113_dialog_content = "シャドウマスター…強すぎる――",
  ui_story_5071_50711501_114_dialog_content = "もう「優雅」を気取る気がないなら、\nあとは命乞いの準備でもしておくがいい。",
  ui_story_5071_50711501_115_dialog_content = "ど、どういうことよ…ひどいケガしたんじゃないの？\nなぜ、まだこんな力が…",
  ui_story_5071_50711501_116_dialog_content = "何やってるの、かかって行きなさいよ！\nあいつはもう限界のはずよ！",
  ui_story_5071_50711501_117_dialog_content = "限界？準備運動が済んだばかりだぞ。",
  ui_story_5071_50711501_118_dialog_content = "ぜ、全部燃やし尽くしやがった…\nこ、こいつ…老いないのかよ…",
  ui_story_5071_50711501_119_dialog_content = "うわあああ――",
  ui_story_5071_50711501_120_dialog_content = "これが隠していた本当の姿なのね…\n混沌を焼き尽くす孤高の炎…",
  ui_story_5071_50711501_121_dialog_content = "これで、満足か？",
  ui_story_5071_50711501_122_dialog_content = "願いがかなったな。野獣を見事呼び覚ましたじゃないか。\nおめでとう！",
  ui_story_5071_50711501_123_dialog_content = "は、早く、あいつを放ちなさい――急ぐのよ！！",
  ui_story_5071_50711501_124_dialog_content = "お金なら全部あげるわ！さっさと「こいつ」を…",
  ui_story_5071_50711501_125_dialog_content = "<size=50>「エヴァ」――！！</size>",
  ui_story_5071_50711502_1_dialog_content = "見たでしょう！あの暗鬼でも止められないのよ…\nイスタバンこそ本物のバケモノよ！",
  ui_story_5071_50711502_2_dialog_content = "逃げる気ですか？",
  ui_story_5071_50711502_3_dialog_content = "こ、来ないで――",
  ui_story_5071_50711502_4_dialog_content = "！？",
  ui_story_5071_50711502_5_dialog_content = "バロン…",
  ui_story_5071_50711502_6_dialog_content = "見逃してやりたいのか？",
  ui_story_5071_50711502_7_dialog_content = "助けて――",
  ui_story_5071_50711502_8_dialog_content = "醜いぞ、「エヴァ」！",
  ui_story_5071_50711502_9_dialog_content = "や、やめて…",
  ui_story_5071_50711502_10_dialog_content = "これ以上の抵抗はよせ。\nお前に私刑は下さない――しかるべき審判を受けろ。",
  ui_story_5071_50711502_11_dialog_content = "バロンの夢は、俺たちの夢は――これからも俺が引き継いでいく。",
  ui_story_5071_50711502_12_dialog_content = "夢なんて…もう粉々に砕け散ったわ…",
  ui_story_5071_50711502_13_dialog_content = "実に残念だよ、「エヴァ」…\nお前がここまで堕落するとは思わなかった。",
  ui_story_5071_50711502_14_dialog_content = "お前はバロンの…",
  ui_story_5071_50711502_15_dialog_content = "しらじらしい真似はよして！\nあんたの憐みなんてまっぴらよ！",
  ui_story_5071_50711502_16_dialog_content = "お前ひとりでここまでやれるはずもない。\n多くの助けがあったんだろう。",
  ui_story_5071_50711502_17_dialog_content = "俺を敵視する連中に利用されたんだな…\nそいつらを俺は許さん！",
  ui_story_5071_50711502_18_dialog_content = "…",
  ui_story_5071_50711502_19_dialog_content = "言いたくないのなら、調べるまでだ。",
  ui_story_5071_50711502_20_dialog_content = "約束しよう。お前は公正な審判の下、裁かれる。",
  ui_story_5071_50711502_21_dialog_content = "しらじらしい真似は止せって言ってるでしょ！\n吐き気がするわ！",
  ui_story_5071_50711502_22_dialog_content = "あんたがバロンを殺したのに…\nバロンのすべてを奪っておきながら、裁きも受けずに――",
  ui_story_5071_50711502_23_dialog_content = "なぜ、私たちだけがあんたの犠牲にならなきゃいけないのよ！",
  ui_story_5071_50711502_24_dialog_content = "呪ってやる！あんたなんて永遠に暗闇の底に\n囚われていればいいのよ！",
  ui_story_5071_50711502_25_dialog_content = "…何年も前、バロンと俺は影ノ街にも\n自分たちの法律が出来ることを望んでいた。",
  ui_story_5071_50711502_26_dialog_content = "やつは秩序を望んでいた。その夢を俺に託してくれた。",
  ui_story_5071_50711502_27_dialog_content = "できることなら、それをお前に使いたくはなかったよ――",
  ui_story_5071_50711502_28_dialog_content = "バロン…",
  ui_story_5071_50711502_29_dialog_content = "大陸商会を創ったのも、\nバロンの夢をかなえたかったからだろう？",
  ui_story_5071_50711502_30_dialog_content = "お前の心は憎しみで満たされてしまった。\nだが、バロンへの愛が純粋さを残してくれていたんだ――",
  ui_story_5071_50711502_31_dialog_content = "やめて。それ以上言わないで…",
  ui_story_5071_50711502_32_dialog_content = "俺は影の中に長年身を潜めていたせいで、\n本当に救いようのないものがどんなものか見分けがつく。",
  ui_story_5071_50711502_33_dialog_content = "「エヴァ」、お前の心にはまだ最後の「純粋」さが残っている。",
  ui_story_5071_50711502_34_dialog_content = "それは過去のお前が残していった影だ。",
  ui_story_5071_50711502_35_dialog_content = "だから――約束しよう。",
  ui_story_5071_50711502_36_dialog_content = "いつかお前が罪を償い、俺も影ノ街の改革を成し遂げた時…",
  ui_story_5071_50711502_37_dialog_content = "俺の命を取りにくればいい。",
  ui_story_5071_50711502_38_dialog_content = "あなた…",
  ui_story_5071_50711502_39_dialog_content = "さあ、自警団が救援隊を連れて駆け付けたみたいよ。",
  ui_story_5071_50711502_40_dialog_content = "後のことは彼らに任せましょう。",
  ui_story_5071_50711502_41_dialog_content = "…放しなさい！",
  ui_story_5071_50711502_42_dialog_content = "なぜなの！？",
  ui_story_5071_50711502_43_dialog_content = "本当の殺し屋は目の前にいるじゃない！！",
  ui_story_5071_50711502_44_dialog_content = "見てみなさいよ、あの醜い無数の傷痕を――\nまだ分からないの？",
  ui_story_5071_50711502_45_dialog_content = "あの男こそ影ノ街最悪の罪人なのよ！",
  ui_story_5071_50711502_46_dialog_content = "あんたの母親がどうやって死んだか忘れたの？",
  ui_story_5071_50711502_47_dialog_content = "…",
  ui_story_5071_50711502_48_dialog_content = "私にはこういう仕事、向いてないわ。\n自警団の皆さん――急いでちょうだい！",
  ui_story_5071_50711502_49_dialog_content = "あいつの正体を見たでしょう？",
  ui_story_5071_50711502_50_dialog_content = "あの男の側に残るっていうなら、覚悟するのね――",
  ui_story_5071_50711502_51_dialog_content = "いつか必ず、真相に震え上がることになるわ！",
  ui_story_5071_50711502_52_dialog_content = "<color=#FFB400>カイド！呪ってやる――！</color>",
  ui_story_5071_50711601_1_dialog_content = "イヴォンさんの死亡原因が公表されたわ。やはり「毒液」だったわ。\n創作に没頭してたところをハンスに襲われて――",
  ui_story_5071_50711601_2_dialog_content = "残念だわ。もっとお話ししたかったのに…",
  ui_story_5071_50711601_3_dialog_content = "いい人だったのに…",
  ui_story_5071_50711601_4_dialog_content = "バージルがショックを受けていてね。何日も食欲がないし、よく眠れていないの。\nはぁ…どうやら仕事漬けにして、痛みを和らげるしかないみたいね。",
  ui_story_5071_50711601_5_dialog_content = "シェオルさん…たぶん、それは「搾取」では…？",
  ui_story_5071_50711601_6_dialog_content = "そうそう、イヴォンさんを追悼して彼女の作品を再販したの。\nこれが第1回目の作品よ。",
  ui_story_5071_50711601_7_dialog_content = "少しお使いを頼まれて、数冊シャドウマスターに届けてくれない？",
  ui_story_5071_50711601_8_dialog_content = "イスタバンさんもきっと喜びますね…あれ？\nこの数冊は…",
  ui_story_5071_50711601_9_dialog_content = "あ、それね！『赤水銀の夫人』を新しい装丁で再販したのよ。\n私はやはりこのシリーズが一番好きだわ。",
  ui_story_5071_50711601_X9_dialog_content = "百合の花の表紙がシンプルながらきれいですね…赤水銀の夫人にピッタリです…\nシェオルさんのお母さんにも…",
  ui_story_5071_50711601_X10_dialog_content = "消えることのない思い出、偉大な愛と心からの祝福――\nそれが百合の花言葉――",
  ui_story_5071_50711601_X11_dialog_content = "…何か聞きたいことはないのか？",
  ui_story_5071_50711601_X12_dialog_content = "母のことなら、話してくれたでしょう？",
  ui_story_5071_50711601_X13_dialog_content = "ああ。",
  ui_story_5071_50711601_X14_dialog_content = "他に補足でもあるのかしら？",
  ui_story_5071_50711601_X15_dialog_content = "…真相とは時として鋭い武器となる。\nそういう時、俺はいつも善意のウソを選んできた。",
  ui_story_5071_50711601_X16_dialog_content = "本当は病死だったんだ…お前を探すために身も心も疲れ果て、\n行方知れずの娘を思う気持ちが、彼女の身体をむしばんだ。",
  ui_story_5071_50711601_X17_dialog_content = "病に臥せっている時、俺は彼女を訪ね、\n最後の願いを託された。",
  ui_story_5071_50711601_X18_dialog_content = "娘を思う母親の偉大な愛がなしたことだ。\nそれを気に病んでほしくなかった…だから…",
  ui_story_5071_50711601_X19_dialog_content = "それも貸しに計上していいのかしら？",
  ui_story_5071_50711601_X20_dialog_content = "…冗談よ。ありがとう、「お父さん」。",
  ui_story_5071_50711601_X21_dialog_content = "でも、これからは何でも勝手に決めないでよ。",
  ui_story_5071_50711601_X22_dialog_content = "影ノ街の商売は信用と誠意が大事なの。",
  ui_story_5071_50711601_X23_dialog_content = "ハハハ、シェオル会長のありがたいお言葉、\nよく覚えておこう。",
  ui_story_5071_50711601_X24_dialog_content = "お母さんもきっと喜んでいるわ。\n自分の娘が百合の花の似合う女性に育って。",
  ui_story_5071_50711601_10_dialog_content = "ただ残念なのは、忙しくて、\n落ち着いて読み直す時間もないことね。",
  ui_story_5071_50711601_11_dialog_content = "飛空艇は…本当に残念でしたね…",
  ui_story_5071_50711601_12_dialog_content = "いいのよ。こんなこと初めてじゃないもの。\n商売には儲けも損も付きものよ。商人の宿命ってところね。",
  ui_story_5071_50711601_13_dialog_content = "私は自由なの。飛空艇がなくても、\nあちこちを駆けまわって商売できるわ――",
  ui_story_5071_50711601_14_dialog_content = "それを聞いて安心しました。前向きないつものシェオルさんを\n見られてよかったです。では、また！",
  ui_story_5071_50711601_15_dialog_content = "私もPlayerNameに慰めてもらえてうれしいわ…\nただ、巨像の主のあなたに言われると、実に腹立たしいわね。",
  ui_story_5071_50711601_16_dialog_content = "すみません――",
  ui_story_5071_50711601_17_dialog_content = "まったく…",
  ui_story_5071_50711601_18_dialog_content = "あなたは堂々と胸を張って飛んでいればいいのよ。\n私たちの夢を乗せて…",
  ui_story_5071_50711601_19_dialog_content = "<color=#e8d9bb>トントン――</color>",
  ui_story_5071_50711601_20_dialog_content = "入れ。",
  ui_story_5071_50711601_21_dialog_content = "イスタバンさん、僕です。本を届けにきました――あれ？",
  ui_story_5071_50711601_22_dialog_content = "どうした？俺の姿に驚いたか？",
  ui_story_5071_50711601_23_dialog_content = "それは…？",
  ui_story_5071_50711601_24_dialog_content = "影の内のきな臭さはまだ消えていない――\nいつでも戦う準備をしておくべきだと思っただけだ。",
  ui_story_5071_50711601_25_dialog_content = "…本は…ここに置いておきます。",
  ui_story_5071_50711601_26_dialog_content = "シェオルはいつもお前を使いによこすんだな…ありがとう。",
  ui_story_5071_50711601_27_dialog_content = "今でもまだ悪夢を見ますか？",
  ui_story_5071_50711601_28_dialog_content = "ハハ、それはどう定義するかによるな。\n自責の思いにとらわれていた以前の夢は、すべてがゆがめられた過去だった。",
  ui_story_5071_50711601_29_dialog_content = "だが今、俺が見ているのは何のゆがみも脚色もない、ありのままの真実――\nそれをいい夢だと思うか？",
  ui_story_5071_50711601_30_dialog_content = "<color=#e8d9bb>コンコンコンッ――</color>",
  ui_story_5071_50711601_31_dialog_content = "席を外す必要はない。ここにいろ。",
  ui_story_5071_50711601_32_dialog_content = "――入れ。",
  ui_story_5071_50711601_33_dialog_content = "イスタバン様！あの…イスタバン様！",
  ui_story_5071_50711601_34_dialog_content = "どうか…私の敬意をお受けください。\n以前、取引仲間だった者です。",
  ui_story_5071_50711601_35_dialog_content = "もしまだ覚えておいででしたら、\nどうか私の心からのざんげをお聞きください――",
  ui_story_5071_50711601_36_dialog_content = "話してみろ。",
  ui_story_5071_50711601_37_dialog_content = "浮遊商会艇では、私は確かに少々「動揺」し、\n悪友どもと共にけしからぬ行いに走ってしまいました…",
  ui_story_5071_50711601_38_dialog_content = "総合商会がその悪友どもの資産を差し押さえた時、私たちの商会も…\nどうか信じてください！本当に今は改心しているのです！",
  ui_story_5071_50711601_39_dialog_content = "ですから…その広いお心で、どうかお慈悲を…\n私どもの商会を総合商会に戻してください。",
  ui_story_5071_50711601_40_dialog_content = "お前は、仲間だというが――",
  ui_story_5071_50711601_41_dialog_content = "改革が始まった時、お前は俺と関わりを持たんようにし、\n影の目を避け続けていたな。",
  ui_story_5071_50711601_42_dialog_content = "そ、そんなことはありません。",
  ui_story_5071_50711601_43_dialog_content = "俺に隠れて、友人どもと「地下産業」で大儲けをしていた…",
  ui_story_5071_50711601_44_dialog_content = "うまく行っている時は、俺の言葉には一切耳を傾けず――",
  ui_story_5071_50711601_45_dialog_content = "総合商会の裁きを受けた今、ようやく思い出したように、\n影の許しと理解を得ようとしている。",
  ui_story_5071_50711601_46_dialog_content = "そ、それには事情が…",
  ui_story_5071_50711601_47_dialog_content = "言い訳はするな。お前は俺を取引仲間だと思ったことはないし、\n俺を尊重したこともない。",
  ui_story_5071_50711601_48_dialog_content = "お前にとって、「シャドウマスター」はただの邪魔者だ。",
  ui_story_5071_50711601_49_dialog_content = "そ、そんなことは…ありません。どうか聞いてください。",
  ui_story_5071_50711601_50_dialog_content = "必ず過ちを認め、改心いたします！二度と悪友どもとは結託しません。\n「地下産業」からも手を引きます！",
  ui_story_5071_50711601_51_dialog_content = "ですから、どうか総合商会にご容赦いただき、私どもの商売を\n完全に絶たないようお口添え願えませんか？どうか、お願いです！",
  ui_story_5071_50711601_52_dialog_content = "帰れ。",
  ui_story_5071_50711601_53_dialog_content = "で、では…私どもの商会はいったいどう…シャドウマスター様？",
  ui_story_5071_50711601_54_dialog_content = "…",
  ui_story_5071_50711601_55_dialog_content = "わ、分かりました！すぐに消えます。今すぐ…",
  ui_story_5071_50711601_56_dialog_content = "見苦しい姿を見せたな。",
  ui_story_5071_50711601_57_dialog_content = "<color=#FFB400>（前よりも圧倒的な威圧感だ！！）</color>",
  ui_story_5071_50711601_58_dialog_content = "正直言うと、少し怖くなりました…",
  ui_story_5071_50711601_59_dialog_content = "ハハハ、そうかしこまるな――\nお前とチェスでも指したいと思っていたんだぞ。",
  ui_story_5071_50711601_60_dialog_content = "<color=#e8d9bb>トントン――</color>",
  ui_story_5071_50711601_61_dialog_content = "お父様――",
  ui_story_5071_50711601_62_dialog_content = "…入れ。",
  ui_story_5071_50711601_63_dialog_content = "投票の結果が出ました。\n改革案に反対を唱えた者はおりません。",
  ui_story_5071_50711601_64_dialog_content = "今の俺は圧が強すぎるか？",
  ui_story_5071_50711601_65_dialog_content = "決してそう望んでのことではないが、\n確かにやつらのウワサ通りになったな。",
  ui_story_5071_50711601_66_dialog_content = "ハハ、まあ、いいだろう。\n面倒なことも簡単に済むようになったしな。",
  ui_story_5071_50711601_67_dialog_content = "お父様、その他にも…ハンスの背後にいた者たちですが、\n初期調査の結果によると…",
  ui_story_5071_50711601_68_dialog_content = "まだ続きがあるようです。こちらが資料です。",
  ui_story_5071_50711601_69_dialog_content = "やらせておけ。",
  ui_story_5071_50711601_70_dialog_content = "戦う準備はできている。もう俺は隠れはしない。",
  ui_story_5071_50711601_71_dialog_content = "今の影ノ街がどんなに脆かろうと、\n客人を迎えるべき時が来たのだ。",
  ui_story_5071_50711601_72_dialog_content = "クレーケン。",
  ui_story_5071_50711601_73_dialog_content = "はい。",
  ui_story_5071_50711601_74_dialog_content = "準備させるんだ。忙しくなるぞ。",
  ui_story_5071_50711601_75_dialog_content = "分かりました。すぐに宴の準備をいたします――",
  ui_story_5071_50711601_76_dialog_content = "お父様、お仕事はやはり少しお控えください。",
  ui_story_5071_50711601_77_dialog_content = "ケガだけでなく、毒にも当たっているのですよ。\nしっかり休養をとらなくては。",
  ui_story_5071_50711601_78_dialog_content = "（あれ？なんだか、ベセルの態度がやわらかくなった気が…\n普通の親子みたいだなぁ…）",
  ui_story_5071_50711601_79_dialog_content = "俺はまだ老いていないぞ。好きにさせてくれ。",
  ui_story_5071_50711601_80_dialog_content = "あの、すみません。僕はこれで――",
  ui_story_5071_50711601_81_dialog_content = "お忙しいみたいなので、失礼することにします。",
  ui_story_5071_50711601_82_dialog_content = "実に残念だな。お前と一局指したかったんだが。",
  ui_story_5071_50711601_83_dialog_content = "また次の機会にしよう。",
  ui_story_5071_50711601_84_dialog_content = "さようなら――",
  ui_story_5071_50711601_85_dialog_content = "あなた、お父様に何をしたのですか？",
  ui_story_5071_50711601_86_dialog_content = "私たちは皆、お父様の変化に驚いているのです。",
  ui_story_5071_50711601_87_dialog_content = "何もしてないよ！イスタバンさん自身が悟っただけだよ。",
  ui_story_5071_50711601_88_dialog_content = "…そうですか？",
  ui_story_5071_50711601_89_dialog_content = "まあ、いいでしょう。以前よりも正直になられて、分かりやすくなりました。\n私にとってもうれしいことです。",
  ui_story_5071_50711601_90_dialog_content = "ベセル様、通話要請がたくさん来ております。\n次の会議の進行もお願いいたします。",
  ui_story_5071_50711601_91_dialog_content = "分かりました。PlayerNameさん、ありがとうございました。\nまたお会いましょう。",
  ui_story_5071_50711601_92_dialog_content = "うん、またね。",
  ui_story_5071_50711601_93_dialog_content = "さっさとしやがれ！その程度のやる気じゃ話になんねえぞ！\nボスがお待ちかねなんだ！",
  ui_story_5071_50711601_94_dialog_content = "がんばれ！がんばれ～！",
  ui_story_5071_50711601_95_dialog_content = "（活気があるなぁ…）",
  ui_story_5071_50711601_96_dialog_content = "どこのどいつを倒すんだか知らねえが、突っ込め！！",
  ui_story_5071_50711601_97_dialog_content = "（陽の光がまぶしい。今まで影ノ街で、\nこんなに明るい日差しを見たことあったかな？）",
  ui_story_5071_50711601_98_dialog_content = "気を付けろ！学校に建材を運んでるからって、\n交通ルール無視していいわけねえだろ！",
  ui_story_5071_50711601_99_dialog_content = "（陽の光が満ちた影ノ街は、美しい――）",
  ui_story_5071_50711601_100_dialog_content = "急げ！客に届ける荷物をさっさと車に積んで来い――",
  ui_story_5071_50711601_101_dialog_content = "影ノ街の商会は手際が悪いなんて思われちゃ、\nたまったもんじゃねえ！",
  ui_story_5071_50711601_102_dialog_content = "こんな天気のいい日は、ゆっくり過ごすのがよさそうだな。",
  ui_story_5071_50711601_103_dialog_content = "バイスと映画でも観に行こうかな…\nチケット買えるかな…？",
  ui_story_5071_50711601_104_dialog_content = "この本は…",
  ui_story_5071_50711601_105_dialog_content = "そうだな…陽の光の下でじっくり読むのにふさわしい物語だ。",
  ui_story_5071_50711601_106_dialog_content = "ハハ。ちょうど今日はいい天気だ。\n俺たちの故郷も生き生きと輝いている…",
  ui_story_5071_50711601_107_dialog_content = "まるで俺たちの夢が輝いているようじゃないか――",
  ui_story_5071_50711601_108_dialog_content = "そう思わないか？",
  ui_story_5071_50711601_109_dialog_content = "うまくやってるんだね。ようやくそれらしくなってきた。",
  ui_story_5071_50711601_110_dialog_content = "何年も学んで、やっとここまで来た――",
  ui_story_5071_50711601_111_dialog_content = "僕はいい先生だったみたいだね。",
  ui_story_5071_50711601_112_dialog_content = "美しい…僕たちの故郷は、こんなに明るく、美しかったのか…",
  ui_story_5071_50711601_113_dialog_content = "これから先、影ノ街の夢はさらに大きく強くなる。だから…",
  ui_story_5071_50711601_114_dialog_content = "いつかきっと翼をはばたかせ、空を飛べる日が来る――",
  ui_story_5071_50711601_115_dialog_content = "その日を楽しみに待ってるよ。"
}
return config
